// Additional public a16z Speedrun profile context for SR001–SR006.
const SPEEDRUN_OFFICIAL_DETAILS = {
  "SR001:Canto Reality": {"officialUrl":"https://speedrun.a16z.com/companies/canto-reality","officialOverview":"Canto Reality, Inc. is an exploratory deployment lab building social experiences.","founderDetails":{"Aryan Deshpande":{"role":"Member of Technical Staff","bio":"Engineer » aryandeshpande.xyz"},"Shuby Deshpande":{"role":"Member of Technical Staff","bio":"Engineer • Researcher"}}},
  "SR001:Elsewhere": {"officialUrl":"https://speedrun.a16z.com/companies/elsewhere","officialOverview":"We make games that feel like an adventure you go on with your friends, and the adventure is never the same twice","founderDetails":{"Paul Sawaya":{"role":"Founder / CEO","bio":"Founder & CEO of Elsewhere. Previously, co-founder and CTO of Human Interest (YC S15). Active angel investor."}}},
  "SR001:Ex-Human": {"officialUrl":"https://speedrun.a16z.com/companies/ex-human","officialOverview":"Ex-Human is the world’s first empathetic AI platform, trained on millions of real conversations to deliver truly human-like interactions. Seamlessly integrating text, images, and video, it creates emotionally intelligent AI companions that engage users in meaningful, personalized ways. Powered by proprietary AI technology fine-tuned on real-world interactions, Ex-Human enables businesses to develop AI characters that drive deeper user engagement, boost retention, and increase monetization.","founderDetails":{"Artem Rodichev":{"role":"CEO","bio":"Founder & CEO of Ex-human. Creating AI that feels alive, fun, and empathetic. Previously built the AI brains behind Replika, the world’s most popular AI companion with 30M+ users."}}},
  "SR001:GGFolks": {"officialUrl":"https://speedrun.a16z.com/companies/ggfolks","officialOverview":"GGFolks was formed to build Puzzle Wizards (early access) and future new MMOs across Steam, iOS, Android and other platforms. The team built and helps operate Puzzle Pirates (2003) and Spiral Knights (2011), older MMOs with active communities. With the exception of speedrun's investment, GGFolks is founder funded.","founderDetails":{"Daniel James":{"role":"CEO","bio":"I have been making network games since making Wizard on Essex MUD in 1983. Over ~five startups, a VARR stint at META and innumerable projects I have taken the classic product founder role, including game and systems design, biz, customer support, etc. I live in SF with my wife, two teenagers who think I am a colossal fossil, a witchy black cat and a ridiculo"}}},
  "SR001:Househunt": {"officialUrl":"https://speedrun.a16z.com/companies/househunt","officialOverview":"Guess house prices, buy fix and flip homes to build your dream real estate empire","founderDetails":{"Ankith Harathi":{"role":"Co-founder & CEO","bio":"- Co-founder & CEO @ Macro (acquired), Founding team @ Gamer Sensei (acquired). Harvard Business School MBA, Harvard MS Comp Sci, Cornell BS MechE"},"Nitin Rajinikanth":{"role":"Cofounder & CTO","bio":"- Founding team at Macro, acq by mmhmm - Software dev mgr at Hitachi Vantara - Cornell Engineering (B.S. Computer Science)"}}},
  "SR001:Incite Interactive": {"officialUrl":"https://speedrun.a16z.com/companies/incite-interactive","officialOverview":"Incite is an AI-Native Gaming Studio creating the world's first Agentic Life Simulation Game, AuraVale. The team is led by industry veterans from Zynga, The Sims, and Roblox, and are backed by a16z’s Speedrun, Earthling VC, and a stellar cast of gaming industry leaders.","founderDetails":{"Andrew Friday":{"role":"CEO","bio":"Manifesting upside in the video gaming industry since 2009. Currently building AuraVale, an agentic life simulation."},"Dan Fessler":{"role":"Chief Creative Officer","bio":"I am the creative side of Incite with a fixation on bringing emergent narrative games to the masses.\nL58: I got my start as a pixel artist for mobile games at companies including Gameloft, Glu Mobile, and Zynga. Before Incite I was the Chief Visual Officer at Manticore Games where we made a AAA UGC metaverse platform called Core"},"Nico Coderre":{"role":"CTO","bio":"Working on thinking and feeling characters in an emergent narrative simulation."}}},
  "SR001:Level Headed Games": {"officialUrl":"https://speedrun.a16z.com/companies/level-headed-games","officialOverview":"Having worked with multiple billion-dollar franchises, our team is using our expertise to make break-out multiplayer games for the underserved Gen Z and cross-generational markets. We have big ambitions, but we don’t need to burn through tens of millions to make an awesome game. We are well-connected and resourceful, and get the most out of every dollar we spend. Our first game, Whimpact! (announce coming soon), brings the repeatable fun of joyful arena party games like Fall Guys or Mario Kart, and adds long term player progression thanks to your collection of adorable creatures called Whims.","founderDetails":{"Leah Hoyer":{"role":"CEO / Creative Director","bio":"Leah Hoyer is the founder and CEO of Level Headed Games, where she and the team are setting a new bar for cooperative online video games. Prior to her new venture, Ms. Hoyer was GM and Vice President of Creative for Wizards of the Coast’s New IP Studio.\nL49: She has developed and produced television series, video games, and interactive experiences for some o"}}},
  "SR001:Matchday": {"officialUrl":"https://speedrun.a16z.com/companies/matchday","officialOverview":"Our mission is to connect soccer's 5 billion fans. We have secured world class IP, including 65K officially licensed soccer players from FIFPRO, the global player union. Our first game is Matchday Champions, the only casual soccer game on the market. The game is charting app stores in Europe, with top retention and monetization metrics in key cohorts. Champions is the first step in achieving our vision of building the Roblox for soccer. We are a team of seasoned founders (combined exits > $1B), gaming veterans (EA, King, Glu), and Leo Messi. https://m.day/get-champions","founderDetails":{"Derrick Ko":{"role":"CEO & Co-founder","bio":"Derrick is an avid gamer and dedicated Manchester United fan. Prior to starting Matchday, he was the CEO and co-founder of Spin, one of the micromobility pioneers, which was acquired by Ford Motor Company. He was previously at Lyft as an early growth product manager by way of acquisition, and a founding engineer at Pivotal Labs Singapore."}}},
  "SR001:Neon": {"officialUrl":"https://speedrun.a16z.com/companies/neon","officialOverview":"Neon's mission is to accelerate the games industry’s shift from a platform oligopoly to a competitive ecosystem by helping every game creator become an enduring brand. Neon's first product is a white-label e-commerce and global merchant of record platform that lets game teams complement app store monetization with their own DTC channel. Today, Neon partners with a range of mobile and PC studios to help them generate 15-35% of their total revenue through direct.","founderDetails":{"Chris Faught":{"role":"Founder & CEO","bio":"Prior to Neon, Chris spent over a decade building payment networks and commerce software at Affirm, Inc., Apple Pay, and ONE Finance. Chris is a graduate of Carnegie Mellon University and the Stanford Graduate School of Business, and resides in the SF Bay Area."}}},
  "SR001:Original Games": {"officialUrl":"https://speedrun.a16z.com/companies/original-games","officialOverview":"At Original, you can find MZ, Wooga, Playgendary, Playrix, EA alumni (And more!), who are working on casual games that perfectly merge universal accessibility and deep engagement. Our teams make the best possible decisions for our games and the players.","founderDetails":{"Arseny Lebedev":{"role":"Co-Founder","bio":"I like games!"}}},
  "SR001:Rascal Games": {"officialUrl":"https://speedrun.a16z.com/companies/rascal-games","officialOverview":"We're making the next digital 3rd place where gamers can build a new identity, go on adventures with friends, and be valued by them for years to come.","founderDetails":{"Jonathan Lin":{"role":"CTO","bio":"Hi, I'm Jonathan. I like to build stuff, play games, and geek out on random topics (in no particular order)."},"Rick Ling":{"role":"CEO","bio":"Making games now. Prev. led & built communities product @ Discord, and before that, helped many gamers get better at video games @ Blitz (backed by YC + Riot -> acq by Discord)."}}},
  "SR001:Ray Browser": {"officialUrl":"https://speedrun.a16z.com/companies/ray-browser","officialOverview":"Next-generation gaming browser. Instantly play the best games with no downloads required. Enjoy the smoothest gameplay and keep all your favorite apps at your fingertips with split-screen."},
  "SR001:Rosebud AI": {"officialUrl":"https://speedrun.a16z.com/companies/rosebud-ai","officialOverview":"Rosebud AI lets no code creators vibe code games. We have over 500K games already made on our platform."},
  "SR001:Runware": {"officialUrl":"https://speedrun.a16z.com/companies/runware","officialOverview":"Runware offers the fastest, most cost-efficient unified API for AI media generation, enabling sub-second creation across images, audio, video, and more. Powered by custom, renewable-energy hardware, it delivers 5–10× lower costs with no infrastructure or machine-learning expertise required.","founderDetails":{"Flaviu Radulescu":{"role":"Founder & CEO","bio":"Former CTO, Bigstep. Built bare-metal big data clusters for Vodafone, Booking.com, TFL. Managed 100+ person tech teams."},"Maura Dima":{"role":"Partnerships Manager"}}},
  "SR001:Sloyd": {"officialUrl":"https://speedrun.a16z.com/companies/sloyd","officialOverview":"Sloyd is on a mission to create the ultimate 3D creation platform, enabling creators to make 3D assets fast and easy. Our core differentiation is optimized, usable 3D objects that are instantly customizable. We are the only infrastructure that can do in-game creation, enabling User Generated Content on a new scale. Our webapp allows quick editing of 3D templates using AI prompting, or with simple sliders and toggles. Users can access hundreds of templates to customize 3D assets. They can also upload an image and generate 3D models directly.","founderDetails":{"Andreas Edesberg":{"role":"Co-Founder, CEO","bio":"Andreas Edesberg, co-founder and CEO of Sloyd, works in the intersection of creative technology, AI, and gaming. With over 300,000 users globally, Andreas uses his diverse background to help Sloyd become a game-changer in the industry. He honed his strategic skills in management consulting, while his 15 years in sound design and music production have not jus"}}},
  "SR001:SuperGaming": {"officialUrl":"https://speedrun.a16z.com/companies/supergaming","officialOverview":"Our Studios Vision has Always been Building Games that People Play for Years. We specialize in making realtime multiplayers shooters and have over 200 million installs. Our latest title Indus is currently launched in India with over 15 Million Pre Registrations and launches Globally in 2025.","founderDetails":{"Christelle Dcruz":{"role":"Co-founder, VP Engineering","bio":"First woman game developer at SuperGaming. Spent over 12 years crafting gaming experiences.\nL42: Began building educational games at TapToLearn and evolved into creation of games including multiplayer games."},"Roby John":{"role":"CoFounder and CEO","bio":"SuperGamings Story is better known as 3 Guys, A Dog and a Dream that met the App Store Roby was the first IOS developer in India in 2008, Built TapToLearn (YC W2012) Started SuperGaming in 2019 to build and publish our own games with a focus on building realtime multiplayer shooters."}}},
  "SR001:Talofa Games": {"officialUrl":"https://speedrun.a16z.com/companies/talofa-games","officialOverview":"Talofa is building Roblox for Fitness. Our platform makes it simple for creators to develop fitness games for Gen Z. The flagship game on the platform, Run Legends, has over 400,000 downloads and has been featured multiple times on the Apple App Store and Google Play Store. Talofa’s team has been built up with game veterans from EA, 2K, and Riot Games and the CEO, Jenny Xu, has created mobile games with over 10M downloads.","founderDetails":{"Jenny Xu":{"role":"CEO","bio":"Jenny Xu is a long-distance runner, fitness instructor, and Forbes 30 Under 30 honoree, CEO of Talofa Games. She began running and making games at age 12, studied Computer Science at MIT, and has shipped 10 mobile titles with over 10 million downloads. A Niantic Beyond Reality Contest grand prize winner, she raised $6.3M in venture capital, making Talofa one"}}},
  "SR001:The Possible Company": {"officialUrl":"https://speedrun.a16z.com/companies/the-possible-company","officialOverview":"The Possible Studio is a moviemaking app that starts with writing, trusted by bloggers and newsletter writers to elevate their writing. We use AI to help storytellers augment their narrative with images, video, voiceover, sound effects and more. The company is led by Co-founder & CEO Phil Chacko, who previously led product management for XR at Unity. Co-founder & CTO Venk Subramanian was a VP of Engineering at Unity and has built applications in E-commerce, social media, and more.","founderDetails":{"Phil Chacko":{"role":"Co-Founder & CEO","bio":"Spent close to a decade prior to Possible making tools for creators, including leading product management for XR at Unity where he shipped 0-to-1 creator products and improved Unity's market leading developer tools for spatial computing. Worked on cloud infrastructure at Netflix during the early streaming wars.\nL41: His first startup, Featherfab, didn't make"},"Venk Subramanian":{"role":"CTO & Co-Founder","bio":"I'm passionate about building great teams and delivering stellar products."}}},
  "SR001:Trass Games": {"officialUrl":"https://speedrun.a16z.com/companies/trass-games","officialOverview":"Trass Games is a nimble and fast-paced game studio dedicated to crafting hit social VR experiences, including Yeeps. Officially founded in 2021 by Jack, Nathan, and Steve, the studio’s origins trace back to 2015 when Jack and Nathan met as high school freshmen, bonding over a shared passion for building unique games. Together, they developed over 30 titles across mobile and PC before becoming captivated by VR in 2019. Since then, they’ve been at the forefront of this emerging medium, pushing boundaries alongside the Trass Games team to become one of the most respected developers in the space.","founderDetails":{"Jack Southard":{"role":"CEO / Co-Founder","bio":"Born and raised in San Francisco, Jack has been creating games for as long as he can remember. He started building in Scratch during middle school and quickly moved on to developing more complex projects. In high school, he teamed up with Nathan Jew, and together they built over 30 mobile and PC games—each one a unique and often ridiculous experience that ha"},"Steve Shockey":{"role":"COO / Co-Founder"}}},
  "SR001:Unleashed Games": {"officialUrl":"https://speedrun.a16z.com/companies/unleashed-games","officialOverview":"Unleashed Games is a disruptive new consumer startup creating innovative, socially-driven games that bring people together. Built by a team responsible for mega hits like World of Warcraft, Medal of Honor, and Monopoly Go!, we are delivering Haven, a cross-platform, collaborative RPG. Our mission is to address the loneliness crisis through meaningful connections in gaming, tapping into an underserved audience of female gamers and gamer parents with a family-friendly adventure generator. Unleashed Games is positioned to redefine gaming for modern audiences.","founderDetails":{"Irena Pereira":{"role":"CEO","bio":"Irena Pereira is a 25-year veteran of the game industry, known for her expertise in emergent gameplay, data-validated design, and AI-driven storytelling. As the founder of Unleashed Games, she is pioneering new ways to foster deep social connections in gaming through Haven: Forge Friendships to Save the World.\nL43: With a background spanning AAA studios, ind"}}},
  "SR001:Uthana": {"officialUrl":"https://speedrun.a16z.com/companies/uthana","officialOverview":"Uthana is an AI platform for human motion. We turn text, video, and motion data into production-ready 3D movement for simulation, robotics, and digital characters. Our models generate and extract realistic human motion, retarget it across different characters and embodiments, and produce outputs that can be used directly in 3D pipelines, simulation environments, and humanoid robots. Our goal is to make human motion programmable: enabling developers to generate, transform, and deploy movement as easily as other AI-generated content.","founderDetails":{"Viren Tellis":{"role":"CoFounder and CEO","bio":"Viren is a co-founder and CEO of Uthana, a startup that builds generative AI for motion, creating realistic and interactive content for gaming and entertainment. He has over 15 years of experience in strategy, management, product, and operations, spanning various industries and domains. He is also the co-founder and CEO of Hedado, a philanthropic platform th"}}},
  "SR001:Voidpet": {"officialUrl":"https://speedrun.a16z.com/companies/voidpet","officialOverview":"Collect all the Voidpets in our mobile RPG game.","founderDetails":{"Ben Awad":{"role":"CTO","bio":"One of the biggest software engineering creators with over 1M subscribers across YouTube and TikTok."},"Linda Awad":{"role":"CEO","bio":"Born and raised in NYC. Building Voidpet."}}},
  "SR001:Windwalk": {"officialUrl":"https://speedrun.a16z.com/companies/windwalk","officialOverview":"We build enterprise community solutions for the largest fandoms. Teams deploy Harbor to supercharge their community strategies by building their ultimate gamified homebase. Harbor unifies disparate online communities allowing marketing teams to drive explosive growth, and collect meaningful social data to better inform campaigns.","founderDetails":{"Colin Feo":{"role":"CEO"},"Richard Warren":{"role":"Co Founder"}}},
  "SR001:Zibra AI": {"officialUrl":"https://speedrun.a16z.com/companies/zibra-ai","officialOverview":"Zibra sits at the intersection of spatial computing and AI infrastructure. Our compression-native infrastructure serves as an enabling layer for training directly on large-scale 3D data - exactly the kind of infrastructure required for next-generation AI systems across multiple verticals. Our GPU-native, PyTorch-integrated compression technology is purpose-built for massive 3D datasets.","founderDetails":{"Alex Petrenko":{"role":"CEO"}}},
  "SR002:Aghanim": {"officialUrl":"https://speedrun.a16z.com/companies/aghanim","officialOverview":"Aghanim's core solution is a game hub—a comprehensive community portal and an extension of the mobile game in the browser, full of metagame experiences and personalized offers. Such game hubs are built in less than 30 seconds automatically with the help of genAI and then require minimal integration, making them a no-brainer for studios to integrate and see net revenue uplift.  Founded in California by ex-Xsolla C-level executives / Harvard Business School alumni with over 40 years expertise in video games and fintech, and backed by top-tier VCs (Bessemer Venture Partners, a16z, P72V, and…","founderDetails":{"Constantin Andry":{"role":"Co-founder","bio":"With a major in Software Architecture, Constantin built his career in video games as a CMO, launching over a dozen PC, web, and mobile video games, and as a CBDO, focusing on international business development and video game licensing. After moving to Los Angeles in 2016, he joined Xsolla as Deputy CMO and quickly became VP of Product Strategy, Head of Busin"}}},
  "SR002:Braid": {"officialUrl":"https://speedrun.a16z.com/companies/braid","officialOverview":"Braid's employee engagement platform focused on brain-boosting games for remote and hybrid teams. Within 3 months of launching over 100 companies are already using Braid to increase their teams' productivity and engagement.","founderDetails":{"Quinn Li Oshea":{"role":"CEO","bio":"Built my first company at 16 and sold it 3 years later. Have scaled multiple products to over 1M DAU and am extremely passionate about making work more fun for everyone."}}},
  "SR002:Clementine": {"officialUrl":"https://speedrun.a16z.com/companies/clementine","officialOverview":"We build games where the content and functionality game are modded as you play them. That's the main mechanic! We built this system to generate functional, reliable code from natural language in real-time. And we are building a monster trainer as a first title.","founderDetails":{"Ramon Iglesias":{"role":"Founder and CEO","bio":"A Stanford PhD who traded optimizing ride-share fleets for revolutionizing gaming, Ramón combines deep technical expertise with an unbridled love for storytelling. When not reading every book in Morrowind or imagining newspaper headlines in Civilization VI, he's building Clementine's AI tools to help developers create the next generation of games."}}},
  "SR002:Crater Studios": {"officialUrl":"https://speedrun.a16z.com/companies/crater-studios","officialOverview":"Crater Studios is pioneering a Micro-AAA development model, combining the quality and depth of AAA games with the speed and efficiency of indie studios. By leveraging AI-driven workflows, modular development frameworks, and a data-driven approach to game incubation, we rapidly prototype, test, and launch high-quality games at a fraction of traditional costs. Our first title, Dwarven Realms, has proven the model’s success, reaching 150,000+ players and generating $850K in revenue within its first year.","founderDetails":{"Mari Israel":{"role":"CTO","bio":"With over 15 years of extensive experience, Mari is a software engineer proficient in developing diverse systems, ranging from robust backend platforms to immersive gaming experiences.\nL48: He has successfully guided multiple startups from inception to IPO, specializing in building scalable solutions and addressing complex technical challenges at every growt"},"Noni Amnon Israel":{"role":"Co-Founder and CEO","bio":"Noni (Amnon) Israel is the co-founder and CEO of Crater Studios, where he is pioneering a Micro-AAA development model that blends high-quality game development with lean, scalable production. With a background in game development, technology, and business strategy, Noni previously worked at Epic Games, Apple, Blizzard Entertainment and Meta, gaining deep exp"}}},
  "SR002:Dare Drop": {"officialUrl":"https://speedrun.a16z.com/companies/dare-drop","officialOverview":"Dare Drop helps game publishers and studios like EA and Focus Entertainment reach and keep their audiences engaged on Twitch, YouTube, and TikTok. Compared to agencies, Dare Drop delivers 4x more views per $ for games, and helps creators grow 3x faster than normal while doing it.","founderDetails":{"Joe Bechtold":{"role":"Founder / CEO","bio":"Previously led product for one of the first influencer marketing platforms, eventually acquired by AT&T."}}},
  "SR002:Dream Voyage": {"officialUrl":"https://speedrun.a16z.com/companies/dream-voyage","officialOverview":"Voyage is an AI-driven consumer studio building viral, category-defining products. SINE Daily Manifest, our AI-powered spiritual health app, exploded on TikTok. Vdrop turns social media into a payment network, enabling money transfers with a single tweet. RPS, our Solana-based social game, has racked up 100M+ views on TikTok.","founderDetails":{"Coco Chen":{"role":"CEO","bio":"Former Tinder PM turned consumer founder. Into food, longevity, travel, and product growth."}}},
  "SR002:Drill Creative": {"officialUrl":"https://speedrun.a16z.com/companies/drill-creative","founderDetails":{"Alan Noon":{"role":"CEO","bio":"Multidiscipline insomniac game developer. I've led teams at some of the biggest game companies in the world. I've also built stuff from the ground up, lone wolf style.\nL41: I have shipped product on just about every major gaming platform you can think of."},"Jeannie Noon":{"role":"COO","bio":"With experience providing staffing support in the consulting industry and as a communications administrator in academia, Jeannie Noon brings a strong background in talent coordination, operational efficiency, and strategic communication. Their expertise spans recruitment, administrative support, and communication, making them a valuable asset in a fast-paced"}}},
  "SR002:First Day Entertainment": {"officialUrl":"https://speedrun.a16z.com/companies/first-day-entertainment","officialOverview":"We are at the forefront of gaming innovation and dedicated to developing AI-powered games.","founderDetails":{"Mike Mei":{"role":"Co-founder","bio":"Dedicated in game development for over decades. Love play but also build good games."},"Stephen Gou":{"role":"Co-Founder","bio":"Stephen is an expert in LLM and game development. Previously the founding engineer at Cohere, a multi-billion dollar foundation model startup where he researched and developed LLMs and applied models at scale. Stephen also had years of experience in game development with Triple-A game studios."}}},
  "SR002:Gamebeast": {"officialUrl":"https://speedrun.a16z.com/companies/gamebeast","officialOverview":"Gamebeast is the AI-native intelligence layer for gaming. We unify analytics, LiveOps, community insights, and attribution into one platform driven by anyone on your team with agents.","founderDetails":{"Christian Meris":{"role":"Vice President of Business Development","bio":"Christian oversees all aspects of business development, sales, and financial goals at Gamebeast.\nL41: With a strong foundation in management and a proven track record—including leading a team to become the #1 Black Label dealer in the nation—Christian brings expertise, strategy, and vision to the company’s growth and success."},"Zander Brumbaugh":{"role":"CEO","bio":"Zander is a Seattle-based game designer, author, AI researcher, and founder of Gamebeast. Numerous games Zander has created have reached #1 on Roblox, achieving over 500 million play sessions in total and even merchandised at stores like Walmart and Target. He was recognized as part of Forbes 30 Under 30 2025 for his work.\nL40: Zander is also a best-selling "},"G":{"role":"CEO at","bio":"amebeast Zander Brumbaugh Zander is a Seattle-based game designer, author, AI researcher, and founder of Gamebeast. Numerous games Zander has created have reached #1 on Roblox, achieving over 500 million play sessions in total and even merchandised at stores like Walmart and Target. He was recognized as part of Forbes 30 Under 30 2025 for his work.\nL40: Zand"}}},
  "SR002:Gridsnap": {"officialUrl":"https://speedrun.a16z.com/companies/gridsnap","officialOverview":"Gridsnap is a game studio leveraging the power of Unreal Editor for Fortnite (UEFN) to create innovative experiences within the Fortnite ecosystem. We develop our own unique IP while also partnering with influencers to build dedicated spaces for their communities on the platform. Additionally, Gridsnap supports up-and-coming developers by acquiring a stake in their games in exchange for hands-on development assistance.","founderDetails":{"Thomas Hall":{"role":"CEO","bio":"Founder & CEO of Gridsnap. I’ve spent over half my life in UGC gaming, shaping major projects in Minecraft and Fortnite, and working with top influencers and global brands."}}},
  "SR002:Hedra": {"officialUrl":"https://speedrun.a16z.com/companies/hedra","officialOverview":"Hedra is research company building the world's fastest inference and training infrastructure. We work with companies to build custom model solutions across media inference, physical AI and defense.","founderDetails":{"Michael Lingelbach":{"role":"CEO","bio":"Michael is a former PhD student from Stanford focusing with a background in computer vision and embodied AI. His fascination with controllable generative media dates back to his early highschool days as a thespian and amateur VFX fan. Now Michael leads a team at the intersection of product and foundation model research, building highly controllable omnimodal"}}},
  "SR002:k-ID": {"officialUrl":"https://speedrun.a16z.com/companies/k-id","officialOverview":"k-ID is the compliance infrastructure for the age-adaptive internet. We provides age assurance, regulatory intelligence, and compliance technology to gaming, social media, consumer AI, and other platforms with user-generated content, helping operators maintain compliance across more than 200 jurisdictions worldwide. k-ID's products include AgeKit and AgeKit+ (age classification and verification), AgeKey (reusable age credentials), CDK (market-specific compliance logic), and Neimo (regulatory intelligence).","founderDetails":{"Jeff Wu":{"role":"Co-Founder","bio":"Jeff Wu serves as the Chief Safety Officer and Chief People Officer for k-ID. Jeff brings almost two decades of experience in Trust & Safety, Government Outreach, and Investigations at top technology companies, including pre-IPO hyper growth stages at both Meta Platforms and Google Inc.\nL46: He has been recognized for his ability to develop government relati"},"Julian Corbett":{"role":"Chief Strategy & Growth Officer","bio":"Julian Corbett is a co-founder and the Chief Growth Officer of k-ID, the new market standard for enabling age-appropriate and regulatory compliant game experiences for kids and teens.\nL50: Julian uses his extensive experience in leadership in the tech and gaming industry to manage the company’s partnerships, strategy and revenue functions. Before joining k-I"},"Kieran Donovan":{"role":"Founder & CEO","bio":"Dad. Founder. Attorney."},"Timothy Ma":{"role":"Co-Founder and Chief Legal Officer","bio":"Timothy is a co-founder and Chief Legal Officer of k-ID.\nL48: With 12 years of experience at Tencent, he brings extensive expertise in building teams, identifying business opportunities, and scaling businesses in a legally compliant manner.\nL49: As a father of two, Timothy is committed to helping industries create safe, age-appropriate experiences for kids a"}}},
  "SR002:Legion": {"officialUrl":"https://speedrun.a16z.com/companies/legion","officialOverview":"The official developers behind Covenant, a first-person mythical action game, set in a dark fantasy world.","founderDetails":{"Christian Filip":{"role":"CEO & Creative Director","bio":"I'm Christian, CEO & Creative Director of Legion. I was a Level Designer on Battlefield, Call of Duty, and Halo."},"Jacob Stegmeier":{"role":"CFO & Lead Developer","bio":"I'm Jake, CFO & Lead Dev at Legion. Previously I was a Level and Game Designer on Call of Duty, Halo, and Fortnite."},"Seth Short":{"role":"COO & Producer","bio":"I'm Seth, COO & Producer of Legion. I previously worked on Battlefield 2042 before Leading Level Design at LILA Games."}}},
  "SR002:Lil Snack": {"officialUrl":"https://speedrun.a16z.com/companies/lil-snack","officialOverview":"Lil Snack is The DAILY Games Company, making play a daily routine. We deliver new bite-sized games every day, tied to pop culture moments and trends. Play on the web and across partner experiences on Amazon Prime, Peacock, BuzzFeed, Imgur and more. Come back daily for fresh themes, and track your streak, collect wins, while having a lil fun with our community of daily players.","founderDetails":{"Eric Berman":{"role":"Co-Founder, CEO","bio":"I'm Eric, the Lil CEO of Lil Snack! I love building new consumer experiences. At HULU I lead distribution of the the first streaming video apps, then joined Crunchyroll at it's inception, eventually selling to Warner Media for $1Bn+, and stayed on to launch HBO Max. My entrepreneurial journey in games started as the COO of OK Play, which we successfully sold"},"Travis Chen":{"role":"Co-Founder, CPO","bio":"I'm Travis, Co-Founder and Chief Product Officer of Lil Snack! I previously worked on the Guitar Hero and Call of Duty franchises before leading game design at Scopely and AR at Snapchat (think dog face and dancing hot dog).\nL46: I also make weird little indie games like Operator, which gamifies customer support lines and Typing Karaoke, a typing singing gam"}}},
  "SR002:LIVE AWARE": {"officialUrl":"https://speedrun.a16z.com/companies/live-aware","officialOverview":"Live Aware transforms game development by eliminating feedback silos—automating the ingestion and analysis of data, and enabling teams to take action quickly. Every day, developer teams and their trusted communities use Live Aware to capture game sessions and capture their detailed and nuanced thoughts in real time as they explore new builds and features. Live Aware’s AI automatically consolidates feedback by organizing, tagging, and surfacing actionable insights to help teams identify trending issues, surface critical bugs, and link them to real gameplay footage for immediate action.","founderDetails":{"David Berger":{"role":"CTO","bio":"Shipped my first game in 1995 eventually landing at Fasa Interactive working on Mechwarrior, Shadowrun and Crimson Skies. From there to Microsoft where I continued with Fast Studios eventually becoming Director of Engineering.\nL48: After a brief stop in publishing, was a founding member and director of engineering for 343 Industries shipping Halo 4, Halo 5 a"},"Nathan Wheeler":{"role":"CEO","bio":"Nathan Wheeler is Co-founder and CEO of Live Aware. He built his early career as an educator in Seattle before transitioning into game development at the indie studio Very Very Spaceship.\nL47: Nathan’s unique blend of educational experience and hands-on development expertise has made him a master of community-driven design, perfectly positioning him to lead "}}},
  "SR002:Magic Circle Studio": {"officialUrl":"https://speedrun.a16z.com/companies/magic-circle-studio","officialOverview":"1M+ players, playable directly inside Discord & on the web. Players use AI remix our games to make them hilariously relevant to their friend group's niche humor and inside jokes.","founderDetails":{"Avi Romanoff":{"role":"Founder & CEO","bio":"Previously Gaming PM at Google. 200K TikTok followers when it isn't banned. Hacker at heart."}}},
  "SR002:Neon Wild": {"officialUrl":"https://speedrun.a16z.com/companies/neon-wild","officialOverview":"Neon Wild are personalized interactive story worlds designed to boost a child's confidence and self-esteem. Featuring the hit DreamWorks property, Gabby's Dollhouse!","founderDetails":{"Matt Weckel":{"role":"CEO","bio":"Experienced product and design executive with 15+ years experience. Currently the CEO & Co-founder of Neon Wild, an AI-powered personalized entertainment platform for families."}}},
  "SR002:Parhelion Studio Co.": {"officialUrl":"https://speedrun.a16z.com/companies/parhelion-studio-co","officialOverview":"Parhelion is a game studio focused on revolutionizing the anime media space through games and technology. We specialize in live service products with an emphasis on customer happiness and feedback driven development.","founderDetails":{"Andrew Yang":{"role":"CEO","bio":"I'm a serial entrepreneur passionate about developing innovative products and ideas in the anime space. With over eight years of experience creating anime mobile live service gacha games, I've led teams, directed art, and built projects that push the boundaries of anime-inspired entertainment.\nL50: My ambition is to make anime a truly global medium, where cr"},"David Cai":{"role":"Co-founder","bio":"Developing anime style games from the west"},"Kevin Jeon":{"role":"CTO","bio":"Expanding anime content development in the United States."}}},
  "SR002:Plutus Labs": {"officialUrl":"https://speedrun.a16z.com/companies/plutus-labs","officialOverview":"Plutus is a one-stop platform enabling UGC and AI generated prediction markets & hyper-casual games with branded rewards. Home to over 1.4mn+ users globally.","founderDetails":{"Karata Dasmahapatra":{"role":"Co-Founder & CEO","bio":"Founder & CEO at Plutus Labs. Dartmouth '25, Squash Player"},"Shivanshu Tyagi":{"role":"Co-Founder, Plutus Labs"}}},
  "SR002:Qloud Games (Loftia)": {"officialUrl":"https://speedrun.a16z.com/companies/qloud-games-loftia","officialOverview":"We're building Loftia: a cozy social MMO aimed at providing players with a solace from their real life stressors and troubles, instilling a sense of hope and positivity for the future.","founderDetails":{"Eric Mallon":{"role":"Co-Founder/CTO","bio":"A refugee from a decade in enterprise software, I'm building games and loving it."},"Martina Qin":{"role":"Creative Director & Co-Founder","bio":"A marketing and community building expert who is passionate about fostering wholesome connections through social games!"},"Michael Su":{"role":"CEO","bio":"I'm a technologist with a passion for video games, engineering, and the human experience.\nL52: Currently weaving all of these aspects together through building Loftia: a new-age, solarpunk inspired cozy MMO!"}}},
  "SR002:Quago": {"officialUrl":"https://speedrun.a16z.com/companies/quago","officialOverview":"Quago provides gaming studios with a deeper layer of player insights by analyzing sensor data and player connectivity. Powered by machine learning, our technology detects in-game cheaters and identifies fake traffic in UA campaigns in real time - uncovering behaviors that traditional tools and MMPs miss. With high-confidence detection, our AAA studio customers and other leading game developers can take targeted action, safeguard revenue, optimize UA spend, and ensure their data reflects real player activity at scale.","founderDetails":{"Alon Dayan":{"role":"Co-founder & CEO","bio":"I’m the CEO and Co-founder of Quago. Previously, I founded Unbotify, a bot detection company acquired by Adjust in 2019 and later integrated into Applovin.\nL48: With a background in cybersecurity and fraud prevention, I now lead Quago in helping AAA gaming studios tackle in-game cheating and UA fraud at scale."},"Dan Blechner":{"role":"Co-founder & CPO","bio":"I’m the Co-founder and CPO of Quago, shaping our product strategy and technology to help gaming studios detect in-game cheating and UA fraud at scale. Before Quago, I founded Volleto, where I focused on bridging online and offline experiences through data-driven automation and real-time insights.\nL49: With a background in product development, large-scale sys"},"Ran Arieli":{"role":"Co-founder & CTO","bio":"I’m the Co-founder and CTO of Quago, where I lead the development of machine learning technology to detect in-game cheating and UA fraud at scale. Previously, I was the Data Science Team Lead at Unbotify.\nL50: I built and led a team developing a pioneering bot detection solution, later acquired by Adjust and integrated into Applovin. With a background in beh"}}},
  "SR002:Rivet": {"officialUrl":"https://speedrun.a16z.com/companies/rivet","officialOverview":"Orchestrate agents. Operate their environment. Automate their work. Deploy what they build.","founderDetails":{"Nathaniel Flurry":{"role":"Co-founder & CTO"},"Nicholas Kissel":{"role":"Cofounder, CEO"}}},
  "SR002:StyleFrame": {"officialUrl":"https://speedrun.a16z.com/companies/styleframe","officialOverview":"StyleFrame is the AI video toolkit built for motion design, animation, and VFX from concept to final pixel. Keyframes on a real timeline, motion references, restyle, ink and paint: you keep the keys, we do the in-betweens. Art direct with visuals instead of a prompt box, and change anything after the fact without starting over. We are the best harness for any professional quality AI video task!","founderDetails":{"Rishi Pandey":{"role":"Co-Founder","bio":"I am a San Francisco based applied ML engineer and new media artist exploring the the convergence of creativity and computing. Previously I worked at TikTok as an AR artist / engineer."},"Shaheel Mitra":{"role":"Co-Founder"}}},
  "SR002:Tractive": {"officialUrl":"https://speedrun.a16z.com/companies/tractive","officialOverview":"Tractive is building AI-powered tools for 3D artists to get assets game-ready 10x faster, by using machine learning to automate tasks like mesh retopology, UV unwrapping, and rigging.","founderDetails":{"Chris Harding":{"role":"Co-founder","bio":"Previously CTO at Disperse, a construction startup using AI to generate 3D models of large-scale building sites.\nL40: Helped scale the organisation to 200+ and raise $32m in VC funding. Former tech lead at Palantir, led their anti-human trafficking project."},"Mohsan Alvi":{"role":"Co-Founder","bio":"Previously CSO at Disperse, a construction startup using AI to generate 3D models of large-scale building sites. Helped scale the organisation to 200+ and raise $32m in VC funding. PhD in Computer Vision from the world-leading VGG research group at the University of Oxford."}}},
  "SR002:videogame.ai": {"officialUrl":"https://speedrun.a16z.com/companies/videogameai","officialOverview":"100% automation is coming to every industry. We believe games will be the first. We've built a vast agent infrastructure modeled after the game production pipeline and we've added AI agents for every specialty required to make games. Our agents work 24/7. As we speak, our AI agents are building games.","founderDetails":{"Aaron Yuan":{"role":"Founder","bio":"6 year game studio GM/co-founder. 40+ million cumulative plays."}}},
  "SR003:2weeks": {"officialUrl":"https://speedrun.a16z.com/companies/2weeks","officialOverview":"We specialize in rapidly developing experimental prototypes to identify games that can become breakout hits and durable franchises, and we're working in public to directly involve our audience in the process.","founderDetails":{"Brandon Dillon":{"role":"CEO and Co-Founder","bio":"Industry veteran with more than two decades of experience establishing and developing new franchises at ArenaNet, Double Fine, and Oculus"},"Richard Foge":{"role":"CCO","bio":"Hello! I'm Richard Foge. I've been making games professionally since the mid-90s on a range of hardware from arcade cabinets to modern consoles.\nL48: I have managed to contribute to a diverse set of genres from racing (Jet Moto 3, Road Rash 64, and Kinetica)—shooters (Socom: FireTeam Bravo 1 & 2)—MMOs (Guild Wars 1 & 2)—and third-person action games (God of "}}},
  "SR003:Adzap": {"officialUrl":"https://speedrun.a16z.com/companies/adzap","officialOverview":"PC & Console gaming is a $90B market, bigger than mobile and growing faster. Steam and other platforms are hitting saturation, yet no “Applovin for PC/Console” has emerged. On mobile, Applovin became the most valuable company by owning UA. We believe now is the moment to bring that model to PC & Console. That’s what Adzap is building: the player acquisition platform for PC/Console games. Already live with Unity, UE, and custom engine integrations, and powering top titles from Tier-1 publishers.","founderDetails":{"Jules Baculard":{"role":"CEO","bio":"French American, I've been a publisher at HOMA, publishing viral mobile games with 200M+ installs, grossing $40M+ revenue lifetime. There, I saw first hand how studios can use data to find virality more reliably, leveraging UA platforms to brute force their way to distribution.\nL54: I started Bark because I believe the approach I had on mobile can be product"},"Mathias Salanon":{"role":"COO","bio":"Being an eternal enthusiast and lifelong learner, I am passionate about technology. During my years in business school, at MIT and L’Ecole Polytechnique and still now, I always learn to understand the world through different lenses.\nL55: That led me from experiencing the intense journey of launching my own company when I was 21 yo to a total immersion into t"}}},
  "SR003:AvatarOS": {"officialUrl":"https://speedrun.a16z.com/companies/avataros","officialOverview":"We are making digital humans REAL! The team that built the virtual sensation, Miquela, is back with the best avatar technology in the world. Miquela is a virtual phenomenon with 50M streams on Spotify, 6M followers on social, and named Time Magazines 25 Most Influential People on the Internet. She has received casting calls for the hottest shows in Hollywood, including HBO's \"Euphoria\".","founderDetails":{"Isaac Bratzel":{"role":"CEO","bio":"Founder - AvatarOS | Responsible for two of the most influential digital human avatars ever - Lil Miquela, and Amelia.ai - both acquired after raising over $200M in venture funding combined."}}},
  "SR003:Clouted": {"officialUrl":"https://speedrun.a16z.com/companies/clouted","officialOverview":"Clouted is where culture meets distribution. We're the growth system for modern entertainment - built for artists, labels, festivals, gaming studios, startups, consumer apps, and the brands that live inside culture. Through our proprietary platform, The Clouted Engine, we automate mass content operations: transforming raw footage into viral-ready short-form content, distributing it through thousands of trained creators, and driving real results - streams, chart placements, ticket sales, and cultural momentum - at a fraction of the cost of traditional performance marketing.","founderDetails":{"Adriel Yong":{"role":"Co-Founder and COO"},"Justin Banusing":{"role":"CEO & Co-Founder","bio":"Justin is a founder, DJ, and festival producer who built an entertainment company from the inside of the culture he was trying to serve. After recognizing that the biggest problem in music wasn't talent - it was distribution - he co-founded Clouted to become the growth infrastructure layer for modern entertainment. He also produced &FRIENDS Festival, growing"}}},
  "SR003:Communion": {"officialUrl":"https://speedrun.a16z.com/companies/communion","officialOverview":"Communion is a new creative entity fusing fashion, games, and emergent tech to create a life matrix — an endless game with infinite scenarios. Altar is the first step. Based in Venice Beach, CA."},
  "SR003:Definitely Games": {"officialUrl":"https://speedrun.a16z.com/companies/definitely-games","officialOverview":"We're a game studio founded by two award-winning, creative engineers with successful exits and the tech chops to scale anything.","founderDetails":{"Casey Pugh":{"role":"Co-founder","bio":"Casey is an Emmy & Peabody award winning creative technologist that has spent the last 17 years blending product, design, and code into a fine soup. He co-founded VHX (acquired by Vimeo) and developed the Wavelength mobile game (Apple Design Award Finalist & Apple Game of the Day). ----- Casey co-founded VHX where he ran product.\nL45: What started off as a s"},"Charlie Tran":{"role":"Co-founder","bio":"Programmer with 16 years experience in building tech products. Led engineering at two startups with successful exits: Parsec, acquired by Unity in 2021 for $320M. Early infrastructure engineer, then Head of Engineering post-acquisition. VHX, acquired by Vimeo acquired in 2016 (amount not disclosed).\nL44: Early fullstack engineer, then Senior Director of Engi"}}},
  "SR003:Echo Chunk": {"officialUrl":"https://speedrun.a16z.com/companies/echo-chunk","officialOverview":"We're building AI strategy games that generate themselves. We just launched our first game as Launch Partners with Discord and it's been a massive hit. Echo Chess is doing to chess what pickleball did to tennis. We believe there’s a huge opportunity for innovating on easy-to-learn, hard-to-master games like chess and open them up to a mass-market audience, and we’ve found the enormous latent demand to be severely underserved.","founderDetails":{"Sami Ramly":{"role":"Founder, CEO","bio":"creator of echo chess"}}},
  "SR003:Else": {"officialUrl":"https://speedrun.a16z.com/companies/else","officialOverview":"Every customer wants \"just one more thing.\" With Else, anyone can vibe code full-stack functionality on top of your product in complete isolation.","founderDetails":{"Christopher Paretti":{"role":"CEO","bio":"Previously: Design Director of Horizon Worlds @ Meta CEO and co-founder of VRB (exited to Samsung) VP of Design at GREE"},"Jakob Wilkenson":{"role":"CTO","bio":"Most of my career has been in startups, it's my happy place. Most recently I was GM of a business unit at Unity after joining through the Parsec acquisition. I'm excited to be back in the trenches again!"}}},
  "SR003:Endo Health": {"officialUrl":"https://speedrun.a16z.com/companies/endo-health","officialOverview":"Endo Health is building the AI native clinic: end-to-end weight loss care powered by AI. We believe in a world where everyone can receive world-class healthcare. Glow, our AI companion, coaches users through daily voice conversations and prescribes medications through an integrated telehealth pipeline. 7 figure ARR, profitable, 100%+ MoM growth, and 10,000+ kg lost, buying humanity 1,500+ years of lifespan. Founded by Brian Yun (MD turned engineer), backed by a16z speedrun, General Catalyst, and Anne Wojcicki.","founderDetails":{"Brian Yun":{"role":"Co-founder, CEO","bio":"Medical doctor turned engineer, ex-Group lead at Krafton (PUBG), a16z scout"},"Chanwoo Park":{"role":"Co-founder","bio":"MIT AI PhD student. Building a product on Multi-agent AI X Games X healthcare"},"Ian Ryu":{"role":"Co-founder","bio":"Software engineer, ex-Tech lead at Krafton (PUBG)"},"E":{"role":"Co-founder, C","bio":"O at Endo Health Brian Yun Medical doctor turned engineer, ex-Group lead at Krafton (PUBG), a16z scout"}}},
  "SR003:Entropia": {"officialUrl":"https://speedrun.a16z.com/companies/entropia","officialOverview":"We are reinventing webcomics and anime with AI. Anime & webcomics is a $70B market where per 1 second of animation takes 8 hand drawn panels & many hours. By turning every webcomic episode into a bite sized, animated, immersive anime video with AI, we are building a new medium of storytelling.","founderDetails":{"Srijon Sheikh":{"role":"Founder & CPO","bio":"Srijon is a Stanford AI Grad who loves building products and community. From his college dorm, he grew a community to 160K members and grew his first company to $100K ARR.\nL40: At Story Engine, he does all operations and fullstack"},"Wanrong He":{"role":"Co-founder","bio":"Wanrong is a Stanford graduate student with a strong AI research background and a passion for consumer apps and anime. She has built multiple successful products, including two that earned Product of the Day on ProductHunt.\nL41: Known for her ability to drive social media growth, she have over 15,000 followers online."},"Zhizhuo Zhou":{"role":"Co-founder","bio":"Incredibly excited to disrupt entertainment with the open ai large model hypothesis."}}},
  "SR003:Exia Labs": {"officialUrl":"https://speedrun.a16z.com/companies/exia-labs","officialOverview":"Exia Labs builds technology that helps organizations understand complex environments and simulate what happens next. From national security to public safety, we give people better tools to explore possibilities, anticipate outcomes, and make critical decisions.","founderDetails":{"Jonathan Pan":{"role":"CEO","bio":"Jonathan Pan is Co-founder and CEO of Exia Labs. He has been leading product teams at companies like Meta, Amazon, Walmart, and Riot Games for over 14 years. Most recently, he was Senior Director of Product Management at Walmart's Innovation Team. He is also a Visiting Fellow at Hoover Institution, Stanford University where he conducts research on AI and war"},"Serj Kazar":{"role":"Co-Founder & CTO","bio":"Serj is co-founder and CTO of Exia Labs, and is a leading applied AI x Games Engineer. He has working in the data, ML, and AI domain for a decade. Serj's career followed the growth trajectory of the data industry, going from managing data ecosystems and writing MapReduce all the way to integrating ML & AI into games today.\nL43: Most recently, he was a Princi"}}},
  "SR003:Flat2VR Studios": {"officialUrl":"https://speedrun.a16z.com/companies/flat2vr-studios","officialOverview":"At Flat2VR Studios, we transform beloved flatscreen games into fully immersive VR experiences. From high-octane racing and intense shooters to quirky rhythm games, our mission is to reimagine iconic titles for VR gamers. With roots in the modding community, we’ve adapted over 30 flat games into VR hits, loved by millions. As a full-service studio, we handle development, funding, publishing and go-to-market strategies, making the shift to VR seamless for our IP partners. Using cutting-edge tools, we adapt games quickly and efficiently, maintaining the highest quality standards.","founderDetails":{"Elliott Tate":{"role":"CCO","bio":"Elliott Tate is a key figure in the VR industry, serving as Chief Creative Officer at Impact Reality and Flat2VR Studios. As the founder of major VR communities like Beat Saber Modding and Flat2VR, Elliott has built a thriving network of over a million dedicated members.\nL51: His expertise in launching blockbuster VR titles - such as Supernatural, Zenith MMO"},"Eric Masher":{"role":"Chief Operating Officer","bio":"Eric Masher specializes in building communities in the VR space. He founded one of the largest VR-focused communities on Facebook, Quest 2 Community, which now boasts 180k+ members. He is deeply in tune with the VR audience along with professionals in the VR space.\nL53: He was a Title Advisor to Andromeda Entertainment, which has more VR games published in m"},"Harry (Skeeva) Skigis":{"role":"CIO","bio":"Harry (Skeeva) Skigis Co-Founder, Impact Reality / Flat2VR Studios | Co-host, Between Realities VR Podcast With over six years of hands-on experience in the VR/AR/XR industry, Harry (Skeeva) Skigis is known for his deep knowledge of market trends, game studios, and the latest advancements in immersive technology.\nL56: Skeeva is the co-founder of Impact Reali"},"Jasmine Uniza":{"role":"CEO","bio":"Jasmine Uniza is the CEO and co-founder of Impact Reality and Flat2VR Studios, a subsidiary of Impact Reality. With a strong background in engineering and program management, Jasmine previously served as a Technical Program Manager at Oculus/Meta, overseeing VR hardware development, and at Apple, managing iPhone Operations. She also worked as a Mechanical De"}}},
  "SR003:Hatsu Labs": {"officialUrl":"https://speedrun.a16z.com/companies/hatsu-labs","founderDetails":{"Brandon Saw":{"role":"CEO"}}},
  "SR003:Human Computer": {"officialUrl":"https://speedrun.a16z.com/companies/human-computer","officialOverview":"Human Computer is a ground-breaking gaming studio founded by Alex Schleifer and Eliot Garcia Weisberg, aiming to revolutionize the industry with innovative, story-driven games within a shared universe. Our goal is to become the world's premier triple-I studio, built on highly versatile original IP and unparalleled production values.","founderDetails":{"Alex Schelifer":{"role":"CEO","bio":"Previously CDO at Airbnb, now building a next generation video game studio."},"Eliot Garcia Weisberg":{"role":"Co-Founder & Gameplay Director","bio":"I'm a multidisciplinary creator with 20 years of experience across film, interactive, and gaming. Prior to Co-Founding Human Computer I led product launches at Airbnb, uniting product, marketing, and brand narrative via film, interactive, and live events.\nL52: At Human Computer I lead gameplay direction for our debut game, Hotel Bagatelle."}}},
  "SR003:Keewano": {"officialUrl":"https://speedrun.a16z.com/companies/keewano","officialOverview":"Keewano is building the database for machine reasoning at scale. Traditional analytics databases are optimized for people asking known questions through tables, dashboards and predefined views. AI agents ask differently, so KeewanoDB's storage format was designed around how machines reason: every event complete, in order, in context, and live the moment it lands. That design unlocks unlimited events, agent-scale throughput, and the grounded context agents need behind every answer.","founderDetails":{"Dima Karger":{"role":"COO","bio":"After 20+ years managing large-scale business, product, and operational teams as General Manager at Plarium, my focus shifted to solving AI’s core limitation: contextual reasoning.\nL43: Keewano was built because traditional databases lack the architecture required for AI agents to reason effectively. We give agents the context to answer complex questions tra"},"Mark Kardashov":{"role":"CEO","bio":"In 1964, Japan didn’t try to make trains faster on the same track. They built a new line. Databases are at that fork now. AI agents need a fundamentally different data architecture, and we’ve built KeewanoDB as the new line."},"Pavel Bibergal":{"role":"CTO","bio":"CTO with over two decades of experience transforming complex technical visions into reality.\nL44: I specialize in building and leading massive engineering organizations, architecting resilient solutions across a wide spectrum of technologies. By directing huge, multidisciplinary technical departments, I have consistently executed on multimillion-dollar initi"},"Vitaly Bukhovsky":{"role":"CISO","bio":"With over 20 years of experience in the cybersecurity industry, I specialize in innovative cloud and security solutions for businesses.\nL45: As a former CTO and company owner, I have successfully navigated two exits in the B2B market, demonstrating my ability to drive growth and deliver value. I oversee a skilled team of professionals dedicated to developing"}}},
  "SR003:LFG": {"officialUrl":"https://speedrun.a16z.com/companies/lfg","officialOverview":"At LFG we have a strong conviction that studios building on UGC platforms have been executing wrong. We're a team that deeply understand how to make top games on these platforms and to do so in an aggressive, fast & capital efficient manner.","founderDetails":{"Ross Targett":{"role":"CEO","bio":"3x exited founder who just completed latest earn-out. Getting the old team back together to build something bigger with what we have learnt."}}},
  "SR003:Little Umbrella": {"officialUrl":"https://speedrun.a16z.com/companies/little-umbrella","officialOverview":"A tech-driven game studio and publisher behind the #1 social AI game on Discord, 'Death by AI,' which reached 20 million players in just 3 months. Launching 3 new social AI games in next 12 months. The next wave of social gaming is coming and we are leading it.","founderDetails":{"Asad Memon":{"role":"Co-founder"},"Tabish Ahmed":{"role":"CEO","bio":"With a deep passion for social gaming and fast-paced innovation, I co-founded Little Umbrella (A Playroom Studio) where we developed a proprietary social game kit called 'Playroom Kit' and harnessed the power of AI to deliver unique game hits like 'Death by AI' which reached 20M users in 3 months.\nL46: Previously, I have led Metaverse Platform Design at Meta"}}},
  "SR003:Manifest": {"officialUrl":"https://speedrun.a16z.com/companies/manifest","officialOverview":"Manifest is a Gen Z mental health app that builds emotional wellness for our users through daily challenges that transform self-care into a rewarding and habitual experience.","founderDetails":{"Amy Wu":{"role":"Founder and CEO","bio":"Founder and CEO of Manifest. Former: ICONIQ Growth Investor, Player Edition Co-Founder, a16z Marketing, Stanford Engineer."}}},
  "SR003:NoMi": {"officialUrl":"https://speedrun.a16z.com/companies/nomi","officialOverview":"Tapping into a $90B market by doing for self-development what Headspace and Calm have done for mindfulness. We strip away the formality and inaccessibility of self-help, transforming the experience into a fun and rewarding journey of personal growth. NoMi takes relatable Gen-Z experiences and turns them into playable games, helping to look at things from different perspectives so that we can challenge your negative thoughts and build up your confidence. Everyone receive's personalized advice on ways to improve for the future, making self-help fun, easy and accessible.","founderDetails":{"Lailla Elgohary":{"role":"CEO","bio":"Ex-design manager from Instagram focused on the teen and creator space. Prior to that, I headed up product design at J.P. Morgan Chase, Disney, Goldman Sachs and ASOS."},"Sofie Marien":{"role":"CTO, CMO","bio":"Award-winning mobile developer and marketing specialist with over 11 years experience in games at PlayStation and Hasbro."}}},
  "SR003:nunu.ai": {"officialUrl":"https://speedrun.a16z.com/companies/nunuai","officialOverview":"nunu.ai is building intelligent agents to test and play games. We infuse AI agents into the game development process, from QA all the way to player simulation. Our vision is to develop generally capable agents that can navigate and act in any given 3D environment, starting with applications in gaming and moving towards general 3D simulations and robotics.","founderDetails":{"Jan Schnyder":{"role":"CEO","bio":"AI agents, games and robots."},"Kyrill Hux":{"role":"CTO","bio":"bridging bodies and brains"},"Nicolas Muntwyler":{"role":"CAIO","bio":"building unembodied minds"}}},
  "SR003:Orbital": {"officialUrl":"https://speedrun.a16z.com/companies/orbital","officialOverview":"Metro Labs Inc. is an entertainment company built from the ground up with AI. We're building a multi-modal AI model focused on creativity, powering Backlot, a platform where fans can co-create with our IP.","founderDetails":{"Euwyn Poon":{"role":"Founder"}}},
  "SR003:Refactor Games": {"officialUrl":"https://speedrun.a16z.com/companies/refactor-games","officialOverview":"Based in Santa Monica, CA. We are the creators of action packed next-generation sports video games. Our Sports Physics Engine creates new unique animations every frame, so that every play is different. Our games are cross-platform, penetrating 100% of the video game market. We have well established relationships with every sports license holder and every major video game platform or distributor. It is our mission to expand the sports video game market and to bring exceptional returns to shareholders, platforms, leagues, athletes and game developers.","founderDetails":{"Arman Megurditchian":{"role":"Co-Founder & Art Director","bio":"Co-founder and art director at Refactor Games, based in Santa Monica. I’ve been a 3D generalist for ten years with a passion for sports video games."},"Nathan Burba":{"role":"Co-Founder & CEO","bio":"USC grad. Founding CEO of Survios. Former Director of Project Holodeck. VR pioneer. Engineer & Generalist. Enjoys bringing talented people together to make magic happen. Part-time DJ. Sports junkie. Devout Philadelphia Eagles fan."}}},
  "SR003:RUNREAL": {"officialUrl":"https://speedrun.a16z.com/companies/runreal","officialOverview":"RUNREAL accelerates game development with cutting-edge tools designed to supercharge developer workflows. Our CICD platform allows you to easily build, test, and deploy your game on any device, accelerating development cycles and ensuring cross-platform compatibility. RUNREAL proactively monitors the health of your development process by leveraging our unique bare metal cloud infrastructure, providing real-time insights and early detection of potential issues.","founderDetails":{"Marwan Hilmi":{"role":"CEO","bio":"Building games for the last ten years. Early adopter of new tech and developer tools."},"Stephen Lacy":{"role":"Co-Founder","bio":"Open source enthusiast building infrastructure at massive scale."}}},
  "SR003:Schemata": {"officialUrl":"https://speedrun.a16z.com/companies/schemata","officialOverview":"We empower teams to create, visualize, and interact with high-quality 3D environments faster and more cost-effectively than ever before. With proven traction—millions in revenue, multiple defense and commercial partnerships, and industry awards—Traverse is leading the democratization of AI-driven 3D simulation and is positioned to deliver applications across sectors such as defense, oil and gas, and infrastructure.","founderDetails":{"Huy Nguyen":{"role":"CTO, Cofounder","bio":"Huy is a former computer graphics researcher at the Stanford Virtual Human Interaction Laboratory (VHIL) and computer vision researcher at the Stanford Artificial Retina Project.\nL47: He has made significant contributions to the areas of brain-computer interfaces, computer vision, and computer graphics, resulting in three published papers in the “Journal of "},"James Brown":{"role":"CEO, Co-Founder","bio":"James is a former Infantry and Information Operations Officer in the US Marine Corps. He has led large teams overseas, secured millions in funding for software procurement, and has directly briefed the Secretary of the Navy on programs he managed.\nL46: James has four years of startup/venture capital experience, is a Mechanical Engineer with two NASA fellowsh"},"Quin Roberts":{"role":"COO, Co-Founder","bio":"Quin leads Traverse3D's business development and customer operations.\nL48: Two themes underpinning his career have been relationship building and a passion for learning. He loves listening to customer leads talk about their frustrations, asking questions, and helping them find a solution."}}},
  "SR003:Sekai": {"officialUrl":"https://speedrun.a16z.com/companies/sekai","officialOverview":"Building the next TikTok for interactive content using AI. Like how TikTok started from lip-sync videos, we are starting with anime fan fiction. We are team of TikTok veterans and we are seeing a once in a generation opportunity. TikTok turned reality into short videos; AI is transforming anything you can imagine into interactive content. What you imagine is what you get.","founderDetails":{"Arthur Cheung":{"role":"Cofounder","bio":"Founding member of TikTok, Country Manager for TikTok India"},"Lucky Zhang":{"role":"CEO","bio":"Serial founders with exits to Apple and TikTok; Founded TikTok's largest rival in LatAm and was acquired by them; Built the largest local Spotify in SEA with 30m+ users"}}},
  "SR003:Soundmap": {"officialUrl":"https://speedrun.a16z.com/companies/soundmap","officialOverview":"Soundmap is the hottest social music app right now with 1.8m+ lifetime downloads in 6 months :)","founderDetails":{"Paul Xu":{"role":"Co-founder"},"Zibo Gao":{"role":"CEO / Co-Founder","bio":"- Building consumer apps since 2020. 3m+ total downloads and counting - Invested with Intonation Ventures in pre-seed/seed consumer apps - Graduated from Columbia in 2019"}}},
  "SR003:Spark Space": {"officialUrl":"https://speedrun.a16z.com/companies/spark-space","officialOverview":"Spark Space: The AI Writing Tutor That Truly Connects with Students Students LOVE Spark Space because it feels like a real tutor who understands them—their interests, their struggles, and their passions. More than just an AI, it bonds with them like a friend, making writing feel personal, engaging, and even fun. With a gamified experience inspired by Duolingo and their favorite video games, students see instant progress, keeping them motivated and excited to improve.","founderDetails":{"David Vinca":{"role":"Co-Founder & CEO"},"Kira Yang":{"role":"Founding AI Engineer"}}},
  "SR003:TaleMonster Games": {"officialUrl":"https://speedrun.a16z.com/companies/talemonster-games","officialOverview":"We are a full-stack founding team that started working together 5 years ago at Peak Games. This time, we’re going beyond what we achieved with Toon Blast. We’re combining the best of casual game engagement with mid-core game monetization. We developed our first game, Match Valley, in just 5 months with just 5 founders. We soft-launched it last month and it already has 72 minutes of average session time!","founderDetails":{"Berk Yasar":{"role":"Co-founder & Client Engineering Lead"},"Emre Yanik":{"role":"Co-founder & Backend Engineering Lead"},"Eren Saricicek":{"role":"Co-founder & Art Lead"},"Irem Sumer":{"role":"Co-founder & CEO"}}},
  "SR003:TapTap Live": {"officialUrl":"https://speedrun.a16z.com/companies/taptap-live","officialOverview":"We modernize timeless, classic games for Gen Z. Starting with trivia! TapTap Trivia 1. Play with the NATION in our daily live trivia game 2. Play with your CAMPUS by starting a 1v1 battle anytime 3. Play as fast as CULTURE CHANGES, thanks to our AI content engine (fresh questions from 100+ news sources every day)","founderDetails":{"Gordon Sun":{"role":"Founder & CEO","bio":"CEO of TapTap Live. Former exec at Cameo, scaled to $100M+ GMV."}}},
  "SR003:VRL": {"officialUrl":"https://speedrun.a16z.com/companies/vrl","officialOverview":"VRL develops viral mobile games. The team previously created NGL (#1 on the App Store, 200M+ downloads, $20M in ARR)","founderDetails":{"Raj Vir":{"role":"CEO","bio":"Founder of NGL (200M downloads, #1 on the App Store, $20M in ARR)"}}},
  "SR004:Alpaka Games": {"officialUrl":"https://speedrun.a16z.com/companies/alpaka-games","officialOverview":"Alpaka Games is a self-publishing mobile game studio bringing the Rollic business model to the action genre. We’re focused on testing unique core mechanics—some proven, others a mix-and-merge of existing ones—allowing us to refine gameplay quickly without long, costly production cycles.. Our team, with expertise from Rollic and Codeway, focuses on delivering hybrid-casual actions with scalable monetization. Backed by a16z Speedrun, we are building the next generation of mobile hits from the ground up.","founderDetails":{"Can Aksoy":{"role":"CEO","bio":"Can has spent 3 years at Rollic which achieved 2.5 Billion in installs and earned 1.5 Billion Dollar in Revenue before selling to Zynga. He ran LiveOps, a new game studio and publishing initiatives that delivered 300M installs and over 200M Dollar in revenue in just three years.\nL44: He was leading the action genre there before deciding to take the leap into"},"Levent Alp":{"role":"COO","bio":"Levent graduated from the University of Virginia and later completed a master’s in Management of Entertainment and Technology Industries at Bocconi University, where he focused on how blockchain impacts creative industries. Over the past four years, he has worked at Istanbul-based tech startups, spanning early-stage, growth-stage, and late-stage.\nL45: In the"},"Özgün Levent Kaya":{"role":"CTO","bio":"Ozgun has 3 years of experience as a Senior Game Developer at Codeway, where he focused on action tower defense games. His expertise covers the full development cycle—prototyping, technical development, soft launches, global launches, and live ops. He’s now leading game development at Alpaka Games."}}},
  "SR004:Atorie": {"officialUrl":"https://speedrun.a16z.com/companies/atorie","officialOverview":"Atorie is the “luxury Temu”— Growing 100% wow, $1.4M in annual run rate. We are a marketplace enabling high-end manufacturers to sell directly to consumers. We help factories increase their margins by 100% while giving consumers access to unique goods (Italian leather, cashmere, etc.) at 10–20% of the typical retail price. The platform leverages AI to redefine the manufacturing and e-commerce stack (with merchandising/design agents, AI fashion models, and personal shoppers on the consumer side...).","founderDetails":{"Luis Angulo":{"role":"Co-Founder & CTO","bio":"engineering, product, fashion, soccer"},"Redouane Ramdani":{"role":"CEO","bio":"I'm the co-founder of Atorie. Previously, I co-founded Snipfeed—backed by top VCs—scaling it to $100M in GMV and empowering over 300,000 creators before selling the business to a PE firm. I've been immersed in the manufacturing industry since childhood, with family roots in the business and early experience selling online in high school.\nL42: Now, our missio"}}},
  "SR004:Checkmate": {"officialUrl":"https://speedrun.a16z.com/companies/checkmate","officialOverview":"Labyrinth is an early stage startup founded by Neil Garde, seasoned Google PM, and James Sha, AI researcher and Co-founder / CTO of Onyx (acq. by Curefit). We are currently in stealth, building an AI-powered vertical SaaS application that leverages recent advancements in AI to solve complex, high-impact problems.","founderDetails":{"James Sha":{"role":"Co-founder & CTO","bio":"Co-founder & CTO @ Labyrinth | Previously Co-founder & CTO @ Onyx, scaled to 300k+ users & acq by Curefit | ex-Google | Forbes 30u30"},"Neil Garde":{"role":"Co-founder & CEO","bio":"Co-founder & CEO @ Labyrinth | PM at Google | 8 years leading products in AI, AR/VR, Games, and Platforms"}}},
  "SR004:Cheddr": {"officialUrl":"https://speedrun.a16z.com/companies/cheddr","officialOverview":"Cheddr is a real-money sports wagering app built for the mass market, legally operating in 46 states—nearly twice as many as DraftKings. Sports betting is a massive industry, with $150 billion wagered annually in the U.S. A staggering 25% of adults and 82% of all male college students place bets each year. Yet, online sportsbooks are only legal in 25 states, and most platforms exclude players under 21. Existing options tend to be complex often resembling Excel spreadsheets with little social interaction or engagement.","founderDetails":{"Jason Krupat":{"role":"CEO","bio":"Jason Krupat, is a serial entrepreneur with two decades of experience in casino, sweepstakes, and skill-based gaming. He has led real-money game studios at industry giants including Yahoo!, Game Show Network, Publishers Clearing House, Skillz, Worldwinner and VGW. Jason was also co-founder of Burn Ghost, a crypto skill gaming platform that raised funding fro"},"Katelyn Friedson":{"role":"Chief Product Officer","bio":"Katelyn Friedson is a veteran product leader with over 15 years of experience launching and scaling consumer-facing platforms.\nL49: She has been part of three successful exits, including iHeartRadio's acquisition of Thumbplay and Care.com’s IPO. With extensive experience in casino, sweepstakes, and Web3 gaming, Katelyn has built and grown platforms that enga"}}},
  "SR004:Chronicler": {"officialUrl":"https://speedrun.a16z.com/companies/chronicler","officialOverview":"Chronicler is an AI-powered assistant that lives inside messaging apps, using AI agents to transform self-texted notes, reminders, and ideas into an organized, searchable second brain—while also proactively managing tasks, scheduling, and follow-ups to keep you on track.","founderDetails":{"Clark Chen":{"role":"CTO","bio":"From building tools, apps, and hacks for tens of thousands of users in middle school to leading the development of new consumer features for over 2 billion users at WhatsApp, my passion has always been creating products that people love. That passion continues to drive everything I do."},"David Duan":{"role":"CEO","bio":"Optimizing my own chaos"},"David Tsui":{"role":"COO","bio":"Ex-Meta/ex-Uber engineer.\nL44: Part of the Messenger business automation then Whatsapp marketing messages teams. I led the development of the home-screen portal and settings for Whatsapp large businesses."}}},
  "SR004:Circle Games": {"officialUrl":"https://speedrun.a16z.com/companies/circle-games","officialOverview":"At Circle Games, we focus on building mobile puzzle games that stand out by design and succeed by execution. We analyze market trends to spot rising mechanics and build around the ones with the highest growth potential—because the market conditions sets the future of the game. Our philosophy, \"details are the product\", drives us to perfect every aspect of the player experience. From polished core mechanics to social systems and engaging mini-games, we ensure our games reach the right audience and keep them coming back.","founderDetails":{"Arda Ozarslan":{"role":"Co-Founder","bio":"Games, Games, Games, Games and Games. Oh and also Games."},"Gokturk Balikci":{"role":"Co-Founder & CEO","bio":"Ex-Zynga New Games Division"},"Mehmet Zahit Ay":{"role":"Co-Founder"},"Mustafa Ozdemir":{"role":"Co-Founder","bio":"Play Sort Express!"}}},
  "SR004:Clubs Poker": {"officialUrl":"https://speedrun.a16z.com/companies/clubs-poker","officialOverview":"Clubs Poker is an innovative online social poker and casino network that allows users to play their favorite games and win real cash prizes. Designed for both casual players and high-stakes enthusiasts, our platform leverages innovative technology and engaging social features to drive retention and maximize lifetime value. With a thriving, growing community and a battle-tested team behind it, Clubs Poker is positioned to become the premier online poker destination in the United States.","founderDetails":{"Jeff Kaplan":{"role":"Chief Operating Officer and Co-Founder","bio":"Jeff is a seasoned executive whose 15+ year career has spanned stints in gaming, Web3, media and entertainment, and management consulting.\nL43: Jeff has been instrumental in bringing multiple new products to market including the Clubs Poker platform, Barstool Sportsbook and Casino, the NBC Sports Predictor app and the Freeport fractional art investing platfo"},"Jon Kaplowitz":{"role":"Co-Founder and CEO","bio":"Media and technology executive with over 20 years of experience in leading innovation and building new businesses in small and large companies.\nL42: Skill-set includes incubating new businesses, deal generation and execution, operating companies in both domestic and international markets, and financial and strategic analysis."},"Sean Hurley":{"role":".."}}},
  "SR004:Coverd": {"officialUrl":"https://speedrun.a16z.com/companies/coverd","officialOverview":"Coverd offers users comprehensive spending insights and thrilling games to win back their purchases: from covering credit card purchases to winning tickets to a dream event for as little as $1. After launching through a mobile app and website, Coverd will introduce the Coverd credit card with gaming features embedded. Created by problem-solvers with expertise in derivative pricing, high frequency trading, and software engineering from Morgan Stanley, Hudson River Trading, Google and Meta, Coverd gives everyone a chance to live big. Reach us at investors@coverd.us","founderDetails":{"Albert Wang":{"role":"Founder"},"Eric Xu":{"role":"CEO","bio":"Founder of Coverd. Ex team lead @Hudson River Trading. Life is just an endless parlay."}}},
  "SR004:Coverstar": {"officialUrl":"https://speedrun.a16z.com/companies/coverstar","officialOverview":"Coverstar is the social platform for Gen Alpha. We combine the creativity of TikTok with the social gaming of Roblox, built from the ground up to be safe and parent-trusted. AI-powered avatar twins help our community create content and jump into multiplayer social games, turning passive screen time into active participation. As regulators crack down on unsafe products and demand grows for better digital experiences for kids, Coverstar is emerging as the fastest growing social platform built for the next generation.","founderDetails":{"Peter Moser":{"role":"CTO","bio":"I'm an Entrepreneur with a track record of delivering high-quality products. As a proud dad, I am dedicated to building a better future for the next generation."},"Ryan So":{"role":"CEO","bio":"I'm a dad and an exited founder. I want to make a better world for my kid and her entire generation."}}},
  "SR004:Darwin": {"officialUrl":"https://speedrun.a16z.com/companies/darwin","officialOverview":"Darwin is building the search engine for finding agents on the web. We index the capabilities of people, businesses, software, products, services, and AIs so anyone can find the right capability for an intent and act on it. As the agentic web becomes increasingly open and machine-readable, Darwin provides the discovery, ranking, and execution layer that turns intent into outcomes.","founderDetails":{"Sanjit Juneja":{"role":"Founder & CEO"}}},
  "SR004:Dial": {"officialUrl":"https://speedrun.a16z.com/companies/dial","officialOverview":"The $2T global telecom industry was built for humans. Your agent is behind bars. It handled the weird date picker, cleared the CAPTCHA, filled the form - twenty-five flawless steps. Then: “enter the code we texted you.” And it stopped, because it has no phone to receive one. Dial is already replacing months of CPaaS work for builders shipping agents into production. No telecom knowledge required, and you can be sending your first message before your coffee’s done.","founderDetails":{"Gal Dayan":{"role":"CEO","bio":"Coding. All day, all night | ex-Justt | ex-Matzov"},"Omri Ben Shoham":{"role":"CTO","bio":"Passionate about coding & entrepreneurship 🚀💡 | exSalesforce | 8200"}}},
  "SR004:Double Dusk": {"officialUrl":"https://speedrun.a16z.com/companies/double-dusk","officialOverview":"Double Dusk is building character-based 2 player games that combine breakout concepts with viral loops. The gaming market is shifting towards co-op, we will take it to the end game with 2 player experiences designed to last and grow with your friendships. We’re a team of repeat founders who have built lean venture game studios (Gamelynx), scaled Silicon Valley startups (Freckle), and been in the trenches leading content for billion dollar games (VALORANT, Sky: Children of Light).","founderDetails":{"Alexander Mistakidis":{"role":"CEO","bio":"Previously game designer on VALORANT combat & characters. I spoke at GDC 2024 about VALORANT's gameplay validation and R&D process. Previously founded Gamelynx, a YC backed game studio that reached >1M users."}}},
  "SR004:Double Fifth": {"officialUrl":"https://speedrun.a16z.com/companies/double-fifth","officialOverview":"We are building Plaid for Behavioral Data—a unified API that allows users to selectively grant developers access to their digital data across various other platforms. We do the difficult work of scraping, building, and maintaining data connectors and transforming disparate data formats into a unified schema, making it immediately useful for developers. Netflix watch history, ride data from Uber, DoorDash order history, or purchase history from Amazon. Everything is cleanly structured and readily accessible.","founderDetails":{"Johnny Zeng":{"role":"CEO","bio":"Happy to talk data."}}},
  "SR004:Edgar": {"officialUrl":"https://speedrun.a16z.com/companies/edgar","officialOverview":"Edgar is a game engine powered by sweepstakes to bring real money engagement into F2P. Our first step to building this engine is developing the next-gen social casino in partnership with Betty Gaming.","founderDetails":{"Justin Park":{"role":"CEO","bio":"Founder and CEO."},"Martin Moon":{"role":"CEO","bio":"Founder and CEO."}}},
  "SR004:Figment": {"officialUrl":"https://speedrun.a16z.com/companies/figment","officialOverview":"Figment is a studio and technology company that is pioneering an entirely new media format which couldn’t exist before AI — stories that can adapt in real time to become hyper personalized, interactive, and infinite worlds. We are building a comprehensive ecosystem for AI-powered interactive storytelling consisting of both a consumer-facing storytelling platform and professional-grade, AI-powered tooling for visuals + narratives. Our social-first consumer platform becomes a content engine where the best stories can be adapted into increasingly higher fidelity media.","founderDetails":{"Eliot Chang":{"role":"CPO / Co-founder","bio":"Product oriented designer and prototyper with a background in game design and social software. Product designer for social features on Fortnite's Player Journey team.\nL65: Head of product and design at Glimpse (YC W20) and led them from 0-1 to acquisition. Led design on R&D initiatives at public gaming companies like Skillz."},"Shubha Jagannatha":{"role":"CEO / Co-Founder","bio":"Builder and artist with an undying love for great storytelling + world-building. Spent my career shuffling between innovative startups and studios, with the past three years at Pixar Animation Studios where I led the charge in crafting the technical wizardry behind our 3D filmmaking pipeline for five unique animated masterpieces.\nL64: Bachelor’s and Master’s"},"Warren Veerasingam":{"role":"CTO / Co-founder","bio":"Driven by curiosity and creativity, I often find myself at the intersection of storytelling and technology.\nL66: With four patents and having pioneered the integration of AI-powered asset search into Pixar Animation Studios' pipeline, I view software as a powerful form of communication — not just between programmer and computer, but among all stakeholders se"}}},
  "SR004:Ghosted": {"officialUrl":"https://speedrun.a16z.com/companies/ghosted","officialOverview":"As the world becomes increasingly artificial, we're building a fortress of realness where you can meet new people and make connections. - No-filter: using AI, we enforce a strict \"authentic & natural picture\"-only policy. - Stories not profiles: profiles and feeds are dynamic, like you. - Transparency: we give users access to all their story views, likes and replays. We have 50,000 genZ users, 20% D30 retention, 1 million profile views / month.","founderDetails":{"Adrien Guilmineau":{"role":"Co-Founder / COO","bio":"Product Lead at Rippling, Head of Product at Hofy (aq.\nL48: Deel $150m), Co-Founder & CEO/CTO: Aria (AI video captioning, 30k prosumers, Stride.VC), Co-Founder & CEO: Sidekick (B2B marketplace for coaching, $1m revenue, Afore Capital)."},"Florian Mari":{"role":"Cofounder / CTO","bio":"I spent years as a Software Engineer building apps, at Trainline, Deezer, a browser startup, and built a SaaS — and now I'm leveraging that experience as CTO at Ghosted."},"Jean-Sébastien Wallez":{"role":"CEO at Ghosted","bio":"I’ve spent the past ten years building consumer products for millions of users, from early messaging chatbots to some of the first AR games on Snapchat."},"Louis Maestrati":{"role":"Co-founder and CMO","bio":"CMO of ghosted.\nL49: Come speak to me about ambassadors, ads and growth… or about AI (prev researcher) and crypto (prev CTO of a crypto company)."}}},
  "SR004:Greathorn Games": {"officialUrl":"https://speedrun.a16z.com/companies/greathorn-games","officialOverview":"Greathorn is a game studio focused on making great games that build inter-player relationships and communities by getting people to talk to one another during play. Our games feature uniquely social game mechanics that drive conversation about tactics and strategy, while also encouraging community formation through deep and innovative integrations with Discord and other community platforms.","founderDetails":{"Ian Dundore":{"role":"CEO & Co-Founder","bio":"Hi, I'm Ian! I spent the first half of my career bringing gamers together in major massively-multiplayer online games like EVE Online and Star Trek Online. I spent the second half building technology and teams at Unity which co-developed, co-shipped, and collaborated with many of Unity's largest and smallest customers to deliver amazing games.\nL44: Now I'm s"},"Karl Kent":{"role":"Co-Founder/Head of Content","bio":"Expert Technical Artist, originating from Art, turned studio founder. Looking to add player to player interaction back to multiplayer games."}}},
  "SR004:Hooper": {"officialUrl":"https://speedrun.a16z.com/companies/hooper","officialOverview":"AI is the new GPS: Just like how Strava leveraged GPS in phones to serve runners, Hooper is using video AI to empower athletes in basketball and other sports on the consumer-level. To get stats and highlights for a game, it’s now 100x cheaper and 10x faster. Vision: Open the access to pro-level training & storytelling to every athlete. The app today comes with stats, mixtapes, medals, and leaderboards, spurring comparison and competition. High retention: In the beta, users have shown that they love the product. The industry average of users returning to the app after 30 days is 8%.","founderDetails":{"Mike Wu":{"role":"Co-Founder","bio":"Building in sports. About me: https://www.mikehwu.com Prior: Stanford PhD, Sanas, Meta, Lattice Data"},"Steven Kang":{"role":"Co-founder","bio":"After being roommates for 4 years at Yale with my cofounder, we both moved out together to the bay area. I have 10 years of experience in product dev and management at early to late stage startups, and most recently for Attentive's generative AI products. Cofounder and I won a hackathon together in 2017 with a computer vision algorithm to track sentiment fro"}}},
  "SR004:Intangible": {"officialUrl":"https://speedrun.a16z.com/companies/intangible","officialOverview":"Intangible is an new kind of AI 3D platform built for high-stakes creative work in physical and digital AI. Think of it as a Creative Platform for World Models. Combine the power and precision of 3D, with the speed and cost savings of AI. The result is creative work that looks and feels elite, and decidedly non-AI. Over 150,000 customers use Intangible to communicate, fundraise and drive revenue in a wide range of physical and digital industries.","founderDetails":{"Bharat Vasan":{"role":"Founder & CEO","bio":"Bharat is the CEO & Founder of Intangible, the AI 3D Studio built for high-stakes creative work in the physical and digital economy. A repeat technology founder/CEO with multiple exits in hardware/software and $500m+ in capital raised, Bharat gets how difficult it is for businesses to convince a skeptical world of their offering. In a world enabled by AI, \"s"},"Charles Migos":{"role":"Founder & CEO at Intangible Bharat Vasan Bharat is the CEO & Founder of Intangible, the AI 3D Studio built for high-stakes creative work in the physical and digital economy. A repeat technology founder/CEO with multiple exits in hardware/software and $500m+ in capital raised, Bharat gets how difficult it is for businesses to convince a skeptical world of their offering. In a world enabled by AI, \"show, don't tell\" pro-grade, creative work becomes mission critical for every business.\nL44: It's why he co-founded Intangible with Apple, ILM and Pixar veterans like legendary designer,","bio":". Intangible combines the power and precision of 3D, with the speed and cost savings of AI. The result is creative work that looks and feels elite, and decidedly non-AI. Over 150,000 customers use Intangible to communicate, fundraise and drive revenue in a wide range of physical and digital industries.\nL45: These range from media & entertainment (film, adver"}}},
  "SR004:Kitbash": {"officialUrl":"https://speedrun.a16z.com/companies/kitbash","officialOverview":"Lark is a realtime database that's designed for the AI era. It's drop-in compatible with Firebase RTDB so existing projects can switch by changing a few config vars. We offer both cloud hosting as well as an open source community version so companies can build on a foundation they can choose to own while letting us handle the devops.","founderDetails":{"Riley Dutton":{"role":"Founder","bio":"In 2012, I Co-Founded Roll20, the largest site for playing D&D online. We grew from a $40k Kickstarter campaign to 18 million users and nine figures of lifetime revenue. In 2016, I Founded OrbusVR, the first MMO built from the ground up for room-scale VR. We were a Meta Quest launch title and shipped more than 200k units even though it was our first VR title"}}},
  "SR004:Layerpath": {"officialUrl":"https://speedrun.a16z.com/companies/layerpath","officialOverview":"Layerpath turns recordings, images, Loom or YouTube links into interactive tours, step-by-step guides or training videos, styled to your brand. When the software changes, update only the steps that changed instead of rebuilding the whole walkthrough. At booth 11, see how a request in Slack becomes a walkthrough you can edit and share.","founderDetails":{"Vinay Chandrasekaran":{"role":"Founder & CEO","bio":"I've spent 20 years asking one question: did they actually get it? Not did they watch it - did they understand what to do next? I built product mockups for 300+ startups, then spent 10 years in GTM at Zoho as it scaled from $200M to $1.5B. Same pattern every time: the product was good. The understanding wasn't. Now I'm building Layerpath. Aspiring triathlete"}}},
  "SR004:Mara": {"officialUrl":"https://speedrun.a16z.com/companies/mara","officialOverview":"Mara builds autonomous, short-range, AI-powered robotic defense systems. Our first product is Spike: a dirt-cheap air defense system which protects military equipment & critical infrastructure from simultaneous attack by dozens of jam-proof enemy drones. Unlike traditional cUAS, which is slow, expensive, and centralized, our system is fast, distributed, and built for frontline deployment. What makes us different? We train our autonomy in a video game—combining simulation-driven AI with player data to develop constantly adapting tactics.","founderDetails":{"Daniel Kofman":{"role":"CEO","bio":"Defense tech geek from birth who made rifle-stopping armor as a teen. Now building the robot army of the free world. Dedicated to the vigorous defense of freedom."},"Sriram Raghu":{"role":"CTO","bio":"I’m an engineer who started out taking apart computers as a kid and never stopped. I’ve worked on FPGAs, web frontends, and everything in between."}}},
  "SR004:Marlo": {"officialUrl":"https://speedrun.a16z.com/companies/marlo","officialOverview":"Built for talent agencies and digital creators, Marlo is the agentic operating system of the creator economy. Marlo, our AI talent manager sits on inboxes & social DMs to put creator brand deals on autopilot. Marlo sorts inbound, drafts responses, & builds a knowledge base 24/7. We make sure that creators never miss a brand deal or opportunity and enable them to focus on what matters most, creating & pushing culture. We partner with and power some of the biggest creators in the world like Alan Chikin Chow, Noah Beck, and the Key Brothers.","founderDetails":{"Austin Chen":{"role":"CEO & Co-Founder","bio":"Austin is a second time founder with an exit to Apple. He previous built Asaii, an artist discovery platform (signing Alina Baraz, Khalid, Alice Merton) that Apple acquired to kickstart their in-house record label & Apple Music for Artists.\nL43: Most recently, he was a product director at TikTok looking after creator monetization bringing products like TikTo"},"Nishi Kaza":{"role":"CTO & Co-Founder","bio":"Nishi has built and scaled AI-driven products in adtech, content intelligence, and music, including Apple Music’s DJ Mixes program and foundation models at Scale AI.\nL44: With a dual degree in EECS and Business from UC Berkeley, he brings a track record of shipping high-impact products that have touched millions of people."}}},
  "SR004:Mini Studio": {"officialUrl":"https://speedrun.a16z.com/companies/mini-studio","officialOverview":"We’re creating AI-animated, emotionally and story rich animated films that millions of kids and families will remember forever.","founderDetails":{"Fabrice Nadjari":{"role":"Co-Founder at Mini Studio","bio":"I am an engineer, creative entrepreneur, storyteller and content strategist with over 15 years of experience in conceiving and developing creative content for and with brands, scientific, international and cultural institutions. I am currently the co-founder of Mini Studio AI, a cutting-edge AI Creative Production Platform redefining the future of animation "},"Marcella Ricca":{"role":"Co-founder/Chief content officer","bio":"Marcella Ricca is a clinical neuropsychologist, life transformational coach, and storyteller who has spent her life exploring the connection between emotion, creativity, and transformation. Her journey has been shaped by a deep commitment to helping individuals and communities grow, heal, and find their voice.\nL47: For years, she supported people through per"},"Youmna Chamcham":{"role":"CEO/Founder","bio":"On a mission to spread joy to millions of kids and families by building the next gen Disney. Democratizing cartoon production for all through our Saas CartoonCreator tool. Mom, filmmaker & product designer.\nL44: Years in children's TV + tech."}}},
  "SR004:Moku": {"officialUrl":"https://speedrun.a16z.com/companies/moku","officialOverview":"Moku is providing game developers with a launch pad and distribution platform, to show off their game and get users in early who are incentive aligned and willing to pay for tradeable assets. Game developers can now go from MVP to getting their first dollar, in less than 5 minutes.","founderDetails":{"Bruce Wasicsko":{"role":"Cofounder","bio":"I’ve spent the last three years building in Web3 gaming, in the trenches on go-to-market strategies and building Moku, a web3 publisher. I've been involved in crypto since 2017, combining my passion for blockchain with a background in tech leadership. Before Moku, I spent nearly a decade at Bridgewater, managing tech teams within the investment engine and wo"},"Hantao Yuan":{"role":"Cofounder","bio":"With 10+ years of experience in traditional gaming, I've helped brands like IGG, Redbull, and more with creator acquisition and strategy. After exiting my esports team via M&A with Overtime, I decided it was time to figure out the distribution game in web3. I've gotten diamond in every game I've played."}}},
  "SR004:Nativ": {"officialUrl":"https://speedrun.a16z.com/companies/nativ","officialOverview":"Nativ enables businesses to expand globally by using AI to culturally adapt visual content for different markets. From marketing materials to product visuals, our technology ensures that images, videos, and graphics resonate with local audiences, going beyond simple translation to embrace cultural nuance. By making content feel truly native in every region, we enable brands to connect authentically with new customers and unlock growth in untapped markets. We have grown from 0 to $100K ARR in 3 months, working with 5 partners. We've already unlocked over a billion new users for our customers.","founderDetails":{"Ahmed Ahres":{"role":"Co-Founder & CTO","bio":"Hi! I'm Ahmed, I grew up in Tunisia playing professional Tennis. At age 16, I graduated high school and went to study Computer Science. I learned to code by building and shipping games on mobile & web. At age 20, I was hired as the first technical intern at Revolut in the Computer Vision team.\nL51: During my time there, I built and shipped the selfie authent"},"Ashish Ranjan Jha":{"role":"Co-Founder & CEO","bio":"Hi! I'm Ashish. I grew up in India, studied at IIT Roorkee, clearing the prestigious IIT JEE exam, ranking 999 out of 400,000 students. Wrote my first computer program at age 13 - a soccer game on FoxPro. I scored a distinction studying ML(AI) at EPFL - a top-5 world-class Swiss University. I declined a 5-year PhD fellowship offer from the Head of the Comput"}}},
  "SR004:Nexad": {"officialUrl":"https://speedrun.a16z.com/companies/nexad","officialOverview":"We generate context-aware ads in real time, and put them into chatbots, AI search engines, and other AI apps.","founderDetails":{"Jason Hu":{"role":"CEO"}}},
  "SR004:Nilo": {"officialUrl":"https://speedrun.a16z.com/companies/nilo","officialOverview":"Nilo enables players to create 3D worlds in seconds. Nilo is a social, generative AI-native 3D sandbox that runs in the browser (desktop, mobile, Discord, Telegram). With Nilo, Generation Alpha has fun creating and sharing 3D experiences together. Founded in April 2024, Nilo is backed by A16Z Speedrun, Essence VC, Earthling VC, Andreas Klinger and Logan Kilpatrick and recently won the most creative award at SF Demo Day hosted by Product Hunt. Nuno, the founder, spent 15 years building game engines, including Unreal Engine 5 and Fortnite at Epic Games.","founderDetails":{"Nuno Leiria":{"role":"Founder & CEO","bio":"15 years in the games industry, contributing to AAA titles such as Fable and Fortnite. Created and led the optimization team for Unreal Engine 5 at Epic Games. https://nunoleiria.com/"}}},
  "SR004:o1.exchange": {"officialUrl":"https://speedrun.a16z.com/companies/o1exchange","officialOverview":"o1.exchange is Onchain Everything Exchange. $8.7M raised from Coinbase, Alliance, a16z sr, and select angels."},
  "SR004:Outcome": {"officialUrl":"https://speedrun.a16z.com/companies/outcome","officialOverview":"To help bigger companies move at startup speed. TeamOS facilitates day-to-day coordination, collects data on how teams depend on others, and combines it with data from existing collaboration tools (e.g. Jira, Github, calendars, etc.) in a single knowledge graph. This enables its AI consultants to learn and recommend what to change in teams, processes, ownership or priorities to eliminate collaboration bottlenecks. We make continuous improvement inevitable.","founderDetails":{"Antoine Merour":{"role":"CEO","bio":"Scaled Riot Games operations in Europe. VP of Strategy & BD at Philips. Student of complex adaptive systems, in nature (think ant colonies), in military history, and in business."},"Gudrun Fema Olafsdottir":{"role":"Product lead, Co-founder","bio":"On a personal mission to give everyone the opportunity to be a part of a great team.\nL66: Led Tempo Software's ($600M) mission critical product business transformation into a SaaS business, expansion into new markets and their flagship product."},"Sveinn Kristjansson":{"role":"Tech lead, Co-founder","bio":"Spent 7 years at Spotify helping them win the streaming wars against Apple and YouTube, where I led the creation of our company-wide Knowledge Graph and transformed Search with LLMs while our systems scaled to billions of lookups per second.\nL67: I'm a repeat founder who's been coding for 20 years (and still love it), and I've got a knack for attracting extr"},"Viggo Gudmunds":{"role":"Operations / Design","bio":"Led operations for EVE Online ($1B+ lifetime revenue).\nL65: Co-founded Radiant Games and built a coding game that millions of kids have played."}}},
  "SR004:Plots": {"officialUrl":"https://speedrun.a16z.com/companies/plots","officialOverview":"Plots is an AI-powered event discovery platform for Gen Z. We are enabling people to experience the world we live in. Plots makes it easy for Gen Z to discover live experiences, meet new people, and build a life they love. Join us in our mission is to get young people off of their phones and into real life.","founderDetails":{"Ryan Ogle":{"role":"CTO","bio":"I'm the former founding CTO of Tinder. I'm passionate about building incredible products and mobile applications from concept to reality.\nL50: Originally from Seattle, now living in Los Angeles, I'm obsessed with building Plots."},"Tristan Amell":{"role":"CEO","bio":"Hello everyone, my name is Tristan. I'm a 21 year old who was born in Toronto, grew up in Paris and am now living in Los Angeles, California. I'm a track & field athlete who loves rockclimbing, spikeball and listening to country music."}}},
  "SR004:Rehearsals": {"officialUrl":"https://speedrun.a16z.com/companies/rehearsals","officialOverview":"Rehearsals creates AI digital twins of your real customers. Within 5 minutes, predict performance on pricing changes, advertising content and new product flows with 85% accuracy. Use our 50,000 existing replicas or bring your own data, either way we help companies 10x their daily tactical decision speed and accuracy.","founderDetails":{"David Schmetterling":{"role":"CTO","bio":"Hi! i'm David.\nL40: I led the Computer Vision team and brought AI technologies to developers at Wayfair! I have managed and grown teams as an Engineering Manager, and developed fullstack and mobile app software as a developer. I'm so excited to be building a product with my best friend since middle school. You are going to love Rehearsals!"},"Liam Bolling":{"role":"CEO","bio":"Launched the first Gemini LLM API at Google Labs/Deepmind, co-founded Project Mariner and previous venture backed startup founder ($1m ARR/25Madison/StartX). Product lead who brought local events to Google Maps, co-founded Microsoft Viva and software engineer who created Tumblr’s onboarding."}}},
  "SR004:Sitch": {"officialUrl":"https://speedrun.a16z.com/companies/sitch","officialOverview":"Tired of dating apps & the endless swiping? Conversations that go nowhere? Meeting randos at bars? Maybe you need your very own matchmaker. Sitch uses AI + Humans to provide a custom Matchmaking experience which is far more intimate than swiping apps.","founderDetails":{"Chad DePue":{"role":"Co-founder","bio":"Chad is former VP at Uniswap, Sr. Director at Snap, CTO of the Whisper App, and GP at Uncommon Projects. He built Snap Kit, Games, Snap Minis, Music, and ran Bitmoji, Messaging, Memories, and Security at Snap. Chad loves building Consumer Social apps and believes AI can transform how we find love."},"Nandini Mullaji":{"role":"Co-founder","bio":"Nandini is the Stanford GSB version of Sima Aunty from Indian Matchmaking.\nL56: She has set up 3000+ of people (and 3 marriages) and has Top 10 dating substack \"Guru Nandini Says.\" She has previously built two profitable consumer apps in dating and education, and has a passion for prompt engineering. Nandini graduated with an MBA from Stanford Graduate Schoo"}}},
  "SR004:Spekter Games": {"officialUrl":"https://speedrun.a16z.com/companies/spekter-games","officialOverview":"Web3 features can supercharge retention, monetization, and virality, but have failed to translate to mainstream gamer adoption. Web3 games have struggled to attract mainstream gamers due to two key issues: friction in onboarding, and Web3 incentive designs that take the fun out of the games. To reduce friction, we are publishing our games on chase-based super apps such as Telegram. Telegram is massive, and they have been quietly launching features that allow us to run our games directly on Telegram, enabling seamless game distribution, payments, and crypto wallet adoption.","founderDetails":{"Taehoon Kim":{"role":"CEO, Founder","bio":"Taehoon Kim (TK) is a serial entrepreneur with over 20 years in the gaming industry. TK has raised over $100M in capital from top-tier VCs, and successfully founded and exited multiple companies, including nWay, Pixelberry, and Nurien. At nWay, he led the development of real-time, cross-play multiplayer hits like Power Rangers: Legacy Wars and Battle for the"}}},
  "SR004:Sunflower": {"officialUrl":"https://speedrun.a16z.com/companies/sunflower","officialOverview":"Addiction is one of the great problems humanity faces, there are literally billions of humans locked behind their addictions being prevented from achieving their true potential. We're building the ultimate toolkit to help keep you sober. Sunflower combines Visual Progression Tracking, an AI Sponsor, CBT-based journaling exercises, and world-class educational content. For the first time thanks to AI - technology is capable of being more powerful than a human therapist or sponsor.","founderDetails":{"Koby Conrad":{"role":"CEO","bio":"Previously ran Growth at Rupa Health from $5M -> $75M/yr in lab sales. Scaled user acquisition by 4,000% before the company got acquired. Looking to do something 100x bigger."}}},
  "SR004:SweatPals": {"officialUrl":"https://speedrun.a16z.com/companies/sweatpals","officialOverview":"We are turning every corner of the world into a social fitness community. Since COVID reshaped how we stay active, grassroots fitness movements - run clubs, sports leagues, and community-led workouts - have been popping up everywhere. SweatPals is the marketplace built just for them: think of us as the “Airbnb for fitness,” empowering anyone to create, host, and monetize their own fitness community. For members to discover and join communities most suited to them.","founderDetails":{"Mandi Zhou":{"role":"Co-Founder & CPO","bio":"Product leader with 10 years of experience, previously building products used by Apple, Ulta, and Shell. My personal journey began when I immigrated to the U.S.\nL48: alone at 14, speaking little English and struggling with psoriasis that often made me self-conscious. Searching for relief, I discovered that regular exercise and sunlight eased my symptoms—and,"},"Salar Shahini":{"role":"Cofounder & CEO","bio":"2x Founder, sold my last company in 2022 I grew up in Iran and fell in love with entrepreneurship at age 13, when I made pinback buttons featuring Persian cartoon characters and sold them at school. I saved up, move to the U.S., and earned my Master’s in engineering in Boston. Along the way, I created a deep tech solution now used by 500+ municipalities acro"}}},
  "SR004:Talus Robotics": {"officialUrl":"https://speedrun.a16z.com/companies/talus-robotics","officialOverview":"Traditional seeing-eye guide dogs cost around $80,000—leaving over 99% of those who need them without access. At Talus Robotics, our mission is to transform this reality and champion independence and inclusion for the blind and visually impaired. We’ve developed groundbreaking robotic guide dogs that cost under $5,000, delivering unprecedented freedom, safety, and empowerment to those who’ve long been underserved. After that, we're tackling adjacent markets in elder care and emotional support.","founderDetails":{"Dhruv Malik":{"role":"President","bio":"Building the future of in home, consumer robotics."},"Ryan Benmalek":{"role":"CEO","bio":"2x venture backed founder, AI PhD. Since starting college at 14, I've been obsessed with AI. After graduating with CS & Neuro (with lots of research), I did a PhD in Deep learning (Computer Vision & NLP) and research at top labs (MILA, AI2, Google Brain, Apple, etc.). I'm passionate about building machines of loving grace - human centered embodied AI."}}},
  "SR004:trophi.ai": {"officialUrl":"https://speedrun.a16z.com/companies/trophiai","officialOverview":"Imagine having a world-class coach guiding you in real-time, whether you're racing in a simulator, perfecting Rocket League mechanics, or even mastering real-world skills like surgery, aircraft piloting, or welding. At trophi.ai, we’ve built a flexible AI native coaching platform that delivers elite, personalized feedback at a fraction of the cost of human coaching. Our AI observes activities, analyzes decisions, and provides real-time, expert-level insights—redefining how people learn and improve. AI coaching is the future, and we are building the infrastructure to power it.","founderDetails":{"Mike Winter":{"role":"CEO","bio":"I'm a second-time founder who previously grew a company from zero to 170 million dollars in ARR. Along the way, I managed a team of over 100 top-tier engineers and built multi-million dollar relationships with companies like CVS Pharmacy and Major League Baseball. As a computer engineer, I've tackled challenges in AI, Radar Simulation, Cloud Communications, "}}},
  "SR004:Unbound": {"officialUrl":"https://speedrun.a16z.com/companies/unbound","officialOverview":"We have developed a revolutionary 3D creation engine that allows anyone to craft their imagination. Unbound drops 20+ year-old architectural assumptions that make today's 3D tools too laborious beyond professional use. Designed with fundamentally new building blocks, Unbound offers unprecedented creator control and is engineered from the ground up for seamless human-AI collaboration. Since launching in early access in January 2025, Unbound has been enthusiastically embraced by our growing community of over 3,600+ passionate creators.","founderDetails":{"Andrea Interguglielmi":{"role":"CPO","bio":"On a mission to unf*ck game development! With over 20 years of experience at the intersection of game development and creative tools for artists, I bring a unique production experience that led me to create Unbound. Previously at DreamWorks Animation and Lionhead Studios, my most recent VR game was fully funded by Meta."},"Florian Hoenig":{"role":"CEO","bio":"Hi, I'm an exited founder in the creator space, passionate about bringing 3D content creation to the masses.\nL50: My strength is developing purpose-driven deep tech, GPU algorithms, real-time computer graphics and machine learning."}}},
  "SR004:Waveful": {"officialUrl":"https://speedrun.a16z.com/companies/waveful","officialOverview":"Waveful is the first AI social app where people can freely share their passions, build authentic communities and actually monetize their content. Thanks to AI powered features and algorithms, it's much easier to create and find communities for what you like, and find the right people for you. Making it possible for adult people to become influencers for the first time. We've grown to over 3.5M users and $1M+ in revenue in 2025.","founderDetails":{"Dennis Motta":{"role":"CTO & Co-Founder","bio":"Master's degree in Computer Science and Engineering - AI Engineering Specialization. +50M downloads for my previous product (Minecraft mods)."},"Steven Motta":{"role":"CEO & Co-Founder","bio":"Hey, i'm Steven 👋 I started making money as developer when I was 9 years old, creating mods for Minecraft that got over 2M+ downloads. Even if i'm just 21 right now, I have over 10+ years of experience in the mobile consumer market, having launched and grown multiple games and apps.\nL48: I love building products that millions and billions of people will use"}}},
  "SR005:Agent Astra": {"officialUrl":"https://speedrun.a16z.com/companies/agent-astra","officialOverview":"Agent Astra is an AI-native logistics platform rebuilding freight from the ground up. Our proprietary technology delivers the service range of a global logistics provider with one-tenth the workforce, starting with asset-light freight forwarding. We own and operate the businesses running on our platform, targeting 2–3x the EBITDA margins of traditional players.","founderDetails":{"Artur Zhdanov":{"role":"CTO","bio":"15+ years in Software & Product. Led Mobility Platform @ARRIVAL (UK EV unicorn $13B).\nL42: Serial startup CTO — built & scaled engineering orgs, delivered MVP-to-scale products."},"Pierre-Antoine Rohr Lacoste":{"role":"CEO","bio":"12+ years of experience in Logistics & Tech. Previously Head of Sales @MetaMap. $0-18M ARR in 2 years, $100M raised, 200+ hires, and opened markets on 5 continents. Owner of restaurants in CDMX. Published research paper in Ancient History."},"Rhu Hashemi":{"role":"Chief Investment Officer & Co-Founder","bio":"Living the dream of building companies through M&A. Started in M&A 8 years ago. I oversee all our M&A efforts at Agent Astra. Previously, led M&A at a roll up from inception to IPO. It's a privilege to partner with founders and create deals that are positive-sum. This is my life's work."}}},
  "SR005:Ambiguous AI": {"officialUrl":"https://speedrun.a16z.com/companies/ambiguous-ai","officialOverview":"Ambiguous is the workspace built for human-AI collaboration. 17 productivity apps reimagined so work flows between your team and agents. They include Docs, Mail, Chat, Sheets, CRM, Calendar, and more. Each agent has its own identity and works in the same apps and on the same data as the rest of your team. You can send it an email, message it in chat, assign it a task, or @mention it in a comment. Teams of up to five can use all 17 apps for free, and agents can get started through MCP or CLI in under a minute.","founderDetails":{"Ryan Waliany":{"role":"CEO & Co-Founder","bio":"Ryan Waliany is a serial entrepreneur and investor, currently founder and CEO of Ambiguous, the workspace built for human-AI collaboration — 17 productivity apps reimagined so work flows between your team and agents. He has a track record of scaling ventures from idea to multi-million-dollar businesses, combining operational expertise with a vision for the f"}}},
  "SR005:Anchr": {"officialUrl":"https://speedrun.a16z.com/companies/anchr","officialOverview":"Anchr is building the first network of AI agents for food distributors, automating away manual bottlenecks across their value chains. Our agents automate workflows across functions like order intake, procurement, inventory management and support by integrating into systems and processes already in place.","founderDetails":{"Smayan Mehra":{"role":"Co-Founder","bio":"I studied computer science and engineering at Duke, after which I spent some time at Apple building vision models. I was recruited to LiveRamp by the CTO under whom I built AI products powering the worlds largest data collaboration network. Outside of work I surf, golf, love raquet sports, working out and poker. I'm a top 3% chess player on chess.com."},"Tzar Taraporvala":{"role":"Co-Founder"}}},
  "SR005:AndThen": {"officialUrl":"https://speedrun.a16z.com/companies/andthen","officialOverview":"AndThen is a voice-first platform built to spin up daily interactive experiences across genres and repeatable formats. From game shows to mysteries to character-driven stories, every experience is designed to be short, episodic, and replayable. Our tech stack supports multi-agent voice interactions and narrative guardrails, allowing us to expand into new game types quickly while keeping conversations coherent, engaging, and fun. We bring deep experience in media, entertainment, and technology.","founderDetails":{"Gavin Purcell":{"role":"CEO","bio":"I’m Gavin Purcell, CEO of And Then and former showrunner of The Tonight Show Starring Jimmy Fallon. I’ve spent my career creating formats that reach millions, and now I believe the future of entertainment won’t be passive... it will be interactive and voice-first. AndThen is built to let real human creators design experiences where AI characters have goals a"},"Kevin Pereira":{"role":"Chief of Whimsy","bio":"Producer/host of internationally recognized properties. Angel investor. Head of AI product at Telly."},"Rex Sorgatz":{"role":"Co-Founder","bio":"Full-stack builder. Repeat founder with one exit."}}},
  "SR005:Argu AI": {"officialUrl":"https://speedrun.a16z.com/companies/argu-ai","officialOverview":"Existing CCTV video systems are limited to pretrained models and use cases. Argu solves that with agentic video intelligence technology, which is operated entirely with words. We help critical infrastructure and governments to save lives, eliminate tenders and long integration cycles, and gain visibility on what matters. With Argu, everything is visible now.","founderDetails":{"Ido Deutsch":{"role":"CEO","bio":"Software engineer, 2x founder, pro athelete - former basketball player and captain in Israel's national team."},"Lior Strugach":{"role":"CTO & Cofounder","bio":"Ex Israeli Intelligence with a background in algorithmic research and computer vision. Now building the next revolution in the space of digital eyes"},"Shani Daniel":{"role":"COO","bio":"Shani Daniel, co-founder and COO of Argu AI, and a second-time founder.\nL46: I’ve been managing business teams and companies for over 20 years, specializing in execution under uncertainty, human behavior, negotiation, and legal strategy. My background also includes years as a political strategist, navigating complex business challenges with limited informati"}}},
  "SR005:Artifact AI": {"officialUrl":"https://speedrun.a16z.com/companies/artifact-ai","officialOverview":"Artifact deploys custom agents for accounting firms and finance professionals. Our edge is ground breaking accuracy for ledger posting and reconciliation workflows.","founderDetails":{"Ariel Harmoko":{"role":"Cofounder and CEO","bio":"Ex-professional racing driver from the age of 8. Raced in F3 at 15. 3x National Champion. Youngest ML Researcher at Cambridge at 15. Deployed JP Morgan's first internal GPT for software developers and equity derivative traders."}}},
  "SR005:Atrios": {"officialUrl":"https://speedrun.a16z.com/companies/atrios","founderDetails":{"Daisy Dolan":{"role":"COO","bio":"Obsessed with building high performing revenue teams :)"},"Taylor Offer":{"role":"CEO","bio":"2nd time founder, $50M+ revenue last company, learn more at www.tayloroffer.com"}}},
  "SR005:Avenir AI": {"officialUrl":"https://speedrun.a16z.com/companies/avenir-ai","officialOverview":"Employee benefits - the second-largest cost center for employers - are broken. Confusing and costly for employees and companies, and shockingly manual for brokers. Legacy systems force people to sift through millions of lines of data across claims, utilization, and regulations. This is a $1.9T market stuck on manual - Avenir AI automates it. We built AI agents that deliver immediate savings and smart optimization across plans, vendors, and workflows. This level of intelligence and speed was not possible before.","founderDetails":{"Ariadne Dulchinos":{"role":"CTO","bio":"Hi, I'm Ari, co-founder of Avenir AI (AI agents for HR/Benefits). I graduated MIT (Bachelor's and Master's), where I studied Computer Science and Cognitive Science. I previously built B2B AI products at Apple and Microsoft, including AI Experiences where Copilot was born.\nL56: I researched in ML for Healthcare for 3 years at MIT's top AI labs: CSAIL and the "},"Maria Zou":{"role":"Co-founder","bio":"I made my first sale at 10 and never stopped loving the craft of building. I’m a proud nerd - my people are nerds who ship real-world change. After MIT research on tech innovation for workplace wellbeing, I left Private Equity to start Avenir AI. In PE and IB, and through the early fintech revolution, I saw software rewire finance. My take is that legacy ind"}}},
  "SR005:Axon": {"officialUrl":"https://speedrun.a16z.com/companies/axon","officialOverview":"Axon is a research and trading firm. We have pioneered brain-inspired, low-latency AI for financial markets. Our work advances both the infrastructure that delivers speed and the models that deliver intelligence.","founderDetails":{"Ayush Shah":{"role":"Co-Founder & CTO","bio":"Ayush Shah is a leader in AI with a decade of experience driving breakthroughs in research and applying them to real products at scale. He has worked at IBM Research, PolyAI, and led the Applications department at Unlikely AI.\nL40: Ayush holds significant patents and publications in AI, reflecting a track record of innovation, and has built products used by "},"Nick D'Aloisio-Montilla":{"role":"Co-Founder CEO","bio":"Nick has founded and sold 2 businesses to Yahoo and Twitter. Angel investor in Deepmind. Now applying his PhD research from Oxford at Axon (#1 in his year)."}}},
  "SR005:Bead AI": {"officialUrl":"https://speedrun.a16z.com/companies/bead-ai","officialOverview":"Auditors spend endless hours on manual tasks: chasing documents, comparing screenshots, and populating excel sheets. Our AI agent handles grunt work, so auditors focus on judgment and strategy – and the business saves 60% of the cost. We’re starting with Sarbanes-Oxley Act compliance – audits that cost $2m+/year in salaries for every US listed company.","founderDetails":{"Alexey Zanin":{"role":"CEO","bio":"Ex-compliance lead at Meta. Building Bead AI so auditors focus on judgement."},"Tobias Otte":{"role":"Co-Founder / CTO","bio":"15 years building and scaling tech startups"}}},
  "SR005:bins": {"officialUrl":"https://speedrun.a16z.com/companies/bins","officialOverview":"Bins brings a fun-first approach to online shopping through a gamified peer-to-peer marketplace with an emphasis on secondhand. We aim to put a new thrift shop in our users' pockets each morning, creating a playground of unique & unfiltered styles. In an online world littered with infinite choices, we give users a digestible, comforting sense of finiteness while still putting discovery first.","founderDetails":{"Akshay Raj":{"role":"Co-Founder","bio":"Solving fun problems 🙃"},"Nathan Oh":{"role":"co-founder"}}},
  "SR005:BotBot": {"officialUrl":"https://speedrun.a16z.com/companies/botbot","officialOverview":"At BotBot, we turn AI behavior into a closed-loop growth lever. Right now, behavior is trapped in code; brand, design, marketing, and product teams can’t own the experience. Our partners like Mattel, Bosch, Warner Bros., need a way in. BotBot gives them editable behavior (tone, timing, memory, upsells) with instant A/B and telemetry, so each variant maps to conversion, retention, CSAT, and containment. Design, ship to a cohort, read the lift, iterate. Same models, measurably better business results. This is the power of design and UX for AI.","founderDetails":{"Michael Mayernick":{"role":"Co-founder","bio":"I'm an entrepreneur and software engineer who has spent his career working in applied AI and machine learning. I previously led Engineering at McDonald's AI labs (McD Techlabs) and later IBM Watson Orders, which was responsible for the McDonald's Drive-thru AI project. Prior to that, I was the technical co-founder of a venture backed, predictive analytics st"},"Steve Mayernick":{"role":"Co-Founder","bio":"I’m an operator with deep experience in AI, UX, and growth, having built teams, products, and growth engines at RJMetrics, Guru, and Pryon that created massive impact. What I’ve seen again and again is that products win on feel and UX - the way they sound, respond, and create moments of delight. As AI takes over more of that surface area, we risk a future wh"}}},
  "SR005:Brief": {"officialUrl":"https://speedrun.a16z.com/companies/brief","officialOverview":"While AI agents can build and ship code at unprecedented speed, they lack the strategic context and product intuition to make meaningful decisions. Brief provides the missing \"intention layer\" - giving AI agents business context, user understanding, and institutional memory to make intelligent product trade-offs.","founderDetails":{"Drew Dillon":{"role":"CEO & founder","bio":"A 2x founder and product leader who learned the power of organizational clarity during a crisis. As Director of Product at Yammer and Principal PM at Microsoft, he saw how context drives execution. When thrust into emergency engineering leadership—managing remotely from San Francisco to Australia—he doubled team output with two-thirds the staff by focusing o"}}},
  "SR005:Creed": {"officialUrl":"https://speedrun.a16z.com/companies/creed","officialOverview":"Creed Labs is a voice-AI studio. We turn the most natural interface that humans have -- speech -- into products that people use every day. Our first product launched 8 weeks ago, and have been doubling nearly every week reaching 500K+ users + best in class retention and positive unit economics."},
  "SR005:Dex": {"officialUrl":"https://speedrun.a16z.com/companies/dex","officialOverview":"Dex is an AI recruiter and career coach that gets to know candidates well beyond their CV to uncover their ambitions, motivations and deal breakers. He uses that knowledge to match candidates with top-tier tech companies that value the same things, making for more meaningful, long term matches. But he doesn’t stop at job matching, he’s also a career coach (that’s actually helpful). He promotes self-reflection, guides career planning, company evaluations and even helps prep and practice for interviews. For companies, Dex is solving the single biggest challenge in business: hiring.","founderDetails":{"Harry Uglow":{"role":"Co-founder and CTO","bio":"I've spent my entire career focused on delivering new product experiences through cutting-edge software. I led engineering on Atomico's industry-leading data analytics and insights platform, as well as deploying LLMs and GenAI products to support the investment team. Previously, I led product and engineering at Kinscape, leading the business through a pivot "},"Paddy Lambros":{"role":"CEO","bio":"I'm Paddy, Co-Founder and CEO at Dex. I've spent more than a decade helping companies like Improbable and the VC fund Atomico to hire elite talent. I've interviewed more than 10,000 people, everything from software engineers to secret agents. Expelled from school and spent time on the streets, I've made it here, and I'm just getting started.\nL49: I'm Paddy, "}}},
  "SR005:Dispatcher": {"officialUrl":"https://speedrun.a16z.com/companies/dispatcher","officialOverview":"Software that turns drones into agents capable of real-time decisions","founderDetails":{"Maxwell Wang":{"role":"Co-Founder CTO","bio":"I’ve been building drones since I was 12, still building drones to turn science fiction into reality."},"Nick Clouse":{"role":"Founder","bio":"Building Dispatcher to provide actionable insights in critical environments"}}},
  "SR005:doublespeed": {"officialUrl":"https://speedrun.a16z.com/companies/doublespeed","officialOverview":"We've built an attention intelligence platform to build and deploy social agents at scale across every demographic and niche. Capturing mindshare on organic social is currently a human labor problem, instead our autonomous creators learn from every interaction, and become more valuable over time driving conversions and engaging with millions 24/7.","founderDetails":{"Hassan Syed":{"role":"Co-Founder","bio":"EX-ML @ Google (search ads infra), Microsoft, Amazon. CTO at RoamAround (500k+ users, acquired 2024). Recently exited an Al image luxury fashion consulting business."},"Zuhair Lakhani":{"role":"Co-founder","bio":"Scaled growth for top consumer apps and CPG companies as an agency during time at USC. Dropped out to run growth at Cosmos (Series A). Left to start doublespeed."}}},
  "SR005:EverCurrent": {"officialUrl":"https://speedrun.a16z.com/companies/evercurrent","officialOverview":"EverCurrent is the first AI-native platform of record to align tools, processes, and knowledge for hardware teams. EverCurrent AI automatically documents the changes across teams, and ties each decision to its wider context. It multiplies the value of the tools, processes, and knowledge hardware teams have — keeping changes recorded, decisions in context, and risks visible.","founderDetails":{"Ye Wang":{"role":"CEO","bio":"Ye Wang is a second-time founder, researcher, and engineer whose career has consistently pushed the frontier of how teams design and build the physical world. Raised by an industrial designer mother and a manufacturer father, she grew up around the miracle of building. As a teenager, she represented the U.S. at the International Olympiad in Informatics (IOI)"}}},
  "SR005:Ezra AI Labs": {"officialUrl":"https://speedrun.a16z.com/companies/ezra-ai-labs","officialOverview":"Recruiting today is drowning in noise: AI-written resumes, scripted interviews, and candidates openly cheating with ChatGPT. Ezra was built by recruiters, for recruiters, on two years of R&D in Voice AI to restore the signals that matter—nuance, authenticity, and fairness. We help you find the needles in the haystack at scale, so you stop wasting time on noise and start connecting with the right candidates.","founderDetails":{"Ophir Samson":{"role":"CEO","bio":"Second-time exited voice AI founder, fortune 50 engineering exec, math PhD @ MIT, MBA @ Stanford, professional magician"}}},
  "SR005:Fearn": {"officialUrl":"https://speedrun.a16z.com/companies/fearn","officialOverview":"Fearn is a modern high-touch patent prosecution firm that is killing the billable hour. At Fearn, we marry the latest advances in computer science with the legal expertise of our former Big Law patent prosecutors. Our approach results in top-tier patents, turned around in days. Our work is always reviewed by a former Big Law patent prosecutor. In addition, we charge only fixed fees, so you'll never be surprised by your legal bill.","founderDetails":{"Angela Gao":{"role":"CTO","bio":"Prior to Fearn, I completed my PhD at Caltech, studying AI and its mathematical underpinnings. My PhD thesis focused on developing physics-aligned generative models. I also worked at Google Research, where I developed proprietary AI models. At Fearn, I continue to develop rule-aligned models, but instead of physics alignments, our AI models are aligned to th"},"Han Kim":{"role":"CEO","bio":"For years, I was a patent prosecutor at MoFo, a top Big Law firm for intellectual property. I drafted and prosecuted for Fortune 500s, as well as for start-ups, across the domains of software, hardware, and biotechnology. Prior to my time in law, I was a PhD student at Caltech, studying AI / comp neuro. There, I studied the relationship between biological an"}}},
  "SR005:First Voyage": {"officialUrl":"https://speedrun.a16z.com/companies/first-voyage","officialOverview":"First Voyage creates mythological pets that turn wellness into play. By blending AI, gamification, and immersive worldbuilding, we build products people love, and feel deeply connected to. In just two months since launch, our first creature, Momo, has helped users complete over 400,000+ quests -- with a leading category D1 retention of 46%.","founderDetails":{"Besart Copa":{"role":"CEO","bio":"Growth marketing at AnchorFree, 500M+ users. Grew Coachify to $1.5M ARR in 14 months. Georgetown University."},"Egehan Ozsoy":{"role":"CTO","bio":"Hi, I'm Egehan and I love building stuff."}}},
  "SR005:Forgepoint": {"officialUrl":"https://speedrun.a16z.com/companies/forgepoint","officialOverview":"Forgepoint builds AI coworkers for the manufacturing back office. Our mission is to give American manufacturers an edge by putting the best technology in the world in their hands. Our first product, Frank, is an AI inside sales rep that handles the RFQ-to-quote process end to end. He's already deployed with hundreds of reps, estimators, and engineers at shops across the country, cutting their time-to-quote by up to 90%.","founderDetails":{"Alex Pareto":{"role":"CTO","bio":"Alex is CTO of Forgepoint.\nL43: Alex started his career as a founder in a YC backed startup that was later acquired by NTWRK, where he joined as the Director Engineering. After NTWRK, Alex joined Brex as a founding engineer on the Spend Management team. Over 5 years, he grew to lead Spend Management engineering for ~40 engineers and managers before starting "},"Jack Strauss":{"role":"Co-Founder and CEO","bio":"Co-founder & CEO of Forgepoint. We build AI coworkers for the manufacturing back office. Our first product, Frank, is an AI Inside Sales Rep already working with hundreds of reps, engineers, and estimators, cutting time-to-quote by up to 90%.\nL42: I've spent my career at the intersection of manufacturing and technology: Chinese OEM factory floors early on, t"}}},
  "SR005:General Magic": {"officialUrl":"https://speedrun.a16z.com/companies/general-magic","officialOverview":"General Magic builds insurance specific AI that runs your brokerage. We give brokerages a trained workforce of AI agents that covers underwriting, customer servicing, and quality assurance end to end, making your team feel 10x bigger without adding a single headcount. Brokerages lose hours every day to work that never should have needed a person: answering underwriting questions, chasing documents, handling servicing requests, and reviewing calls. Our agents do that work. Edward answers underwriting questions instantly with citations from carrier manuals.","founderDetails":{"Anthony Azrak":{"role":"CEO","bio":"I'm a second-time founder and software engineer. My journey started when I built robots at age 7, and later caught the AI bug at an early age after attending Yoshua Bengio's seminars. My first internships were for B2C startups where I built traditional and non-traditional user interfaces.\nL51: I later started my first company, a B2B SaaS company that sold EH"},"Jai Mansukhani":{"role":"Co-founder & President","bio":"I’m a second-time technical founder with a background in computer science and math from the University of Toronto. I previously ran one of Canada’s largest AI communities and built and sold AI infrastructure into the largest public school network in Canada.\nL52: Along the way, I worked at startups like Wombo, where I led GTM and partnerships, providing a mix"}}},
  "SR005:Jigsaw": {"officialUrl":"https://speedrun.a16z.com/companies/jigsaw","officialOverview":"Jigsaw is a research lab focused on recursive self-improvement. We develop rigorous methods for turning AI R&D into post-training artifacts that advance self-improving systems at frontier research labs. We're working with the largest frontier labs to accelerate their efforts toward ASI. Our team includes researchers from Stanford AI Lab, USC, and UCSD who have published AI research at the most prestigious venues.","founderDetails":{"Jongbin (Jay) Won":{"role":"COO","bio":"Prior to Jigsaw, I cofounded a startup which focused on building agentic environments situated around games. Scaled that to 6 figs monthly revenue.\nL40: Before that I scaled enterprise partnerships at Polygon Labs. Graduated early from USC in 2022."},"Miguel Monares":{"role":"CEO","bio":"Prior to Jigsaw, Miguel was a researcher at Stanford AI Lab working on agents and evals. In 2024, he dropped out of university and moved to Tokyo to build simulated worlds for agents ($200k+ MRR). Before that, Miguel worked as an AI engineer in big tech and top research labs."}}},
  "SR005:Jooba": {"officialUrl":"https://speedrun.a16z.com/companies/jooba","officialOverview":"Jooba is the AI-native recruiting firm that runs your entire top of funnel. We reach out to candidates under your name, send top talent straight to your Slack, and cost a fraction of what traditional agencies charge. Our team has shipped software to millions at Netflix and Figma, built agents at Essential AI and Resolve AI, co-authored papers on LLM reasoning, and spent months shadowing a major recruiting agency. We also built one of the fastest-growing LinkedIn accounts in recruiting. Teams like Guard Owl, Gridwise, Cal.com, and Delphi already hire with us.","founderDetails":{"Mark Benliyan":{"role":"Founder & CEO","bio":"By 19, I had already graduated computer science at UCLA and shipped software to millions of people at Netflix and Figma. I then built one of the fastest growing LinkedIn accounts in the world (in recruiting) with over 110k+ followers and 3M+ monthly impressions. After that, I quit my $300k+ job at Figma to shadow a major recruiting agency and learn everythin"}}},
  "SR005:Kanu AI": {"officialUrl":"https://speedrun.a16z.com/companies/kanu-ai","officialOverview":"Kanu brings the systems, models, and knowledge behind your business into one governed platform.","founderDetails":{"Karan Grover":{"role":"CEO & Co-Founder","bio":"I’m a three-time founder, YC W22 alum, former Machine Learning Engineer. My first company, helped blind individuals “hear” their surroundings through 3D audio using mounted sensors. It beat MIT and 843 global teams to win the Ericsson Innovation Awards. After that, I co-founded Trueplace (YC W22), a proptech startup that worked with one of Canada’s largest b"}}},
  "SR005:Lekondo": {"officialUrl":"https://speedrun.a16z.com/companies/lekondo","founderDetails":{"Mitchell Overfield":{"role":"Cofounder & CTO","bio":"I’m a day-0 builder driven by curiosity and the satisfaction of making hard things simple. I’m motivated by challenging, novel experiences; I obsess over quality, I make sense of ambiguity, I move mountains, and I deliver with a good attitude because I love solving problems.\nL45: At Dropbox I helped take Dash from rough prototypes to a flagship AI product by"},"Yeng Tan":{"role":"CoFounder & CEO","bio":"Tacit knowledge through observations of lived experience"}}},
  "SR005:Limy AI": {"officialUrl":"https://speedrun.a16z.com/companies/limy-ai","officialOverview":"Limy is putting AI Agent controls in the hands of brands.","founderDetails":{"Aviv Shamny":{"role":"CEO","bio":"2x founder and engineer. Built from scratch, scaled sales from $0 to $4M in months. Launched products from zero to market adoption, closed enterprise deals, and built teams that executed under pressure. Track record of turning early ideas into real traction. Surfer in heart."},"Ido Zabarsky":{"role":"COO","bio":"I’ve got over 10 years of management experience, leading growth and revenue in tech, building multi-million-dollar pipelines and running sales and GTM strategy. Before that, I spent 8 years as an officer in the Israeli army, where I learned how to lead teams, make decisions under pressure, and build strong processes.\nL43: Along the way I studied economics an"},"Ori Riechman":{"role":"CTO","bio":"17 years in engineering. Ex-8200. Specialized in data, infrastructure, and speed. Built scalable systems, real-time pipelines, and products that delivered - fast.\nL42: Experienced across early-stage startups that scaled. Always hands-on, always impact-first. Relentless problem solver."}}},
  "SR005:Loan Labs": {"officialUrl":"https://speedrun.a16z.com/companies/loan-labs","officialOverview":"If you’ve ever taken out a mortgage and been asked for the same document again and again, you’ve felt a symptom of a chronic disease plaguing the mortgage industry: outdated software and broken workflows layered on top of it. Behind every loan application is an army of humans manually reviewing documents, extracting data, and comparing inconsistencies across scattered systems—email, CRMs, POS and LOS platforms, file management systems, and more. This fragmentation leads to delays, lost information, and costly errors.","founderDetails":{"Brew Johnson":{"role":"Co-Founder & CEO","bio":"Co-founder & CEO of Loan Labs. I built PeerStreet, the first digital marketplace for real estate debt, which I grew to over $100M revenue, funded nearly $5 billion in loans, and was backed by a16z and guys like Michael Burry. I have a weird background as a real estate attorney, tech executive, and investor. Now applying AI to disrupt mortgage finance"}}},
  "SR005:Logical Health": {"officialUrl":"https://speedrun.a16z.com/companies/logical-health","officialOverview":"Logical Health is building Instinct for healthcare. Healthcare companies use Logical to close care gaps, steer members to more affordable care, and improve retention, while giving members an on-demand assistant that makes healthcare dramatically easier. Logical Health is currently working with a national payer and a TPA. The company originated from Stanford research that delivered $16M in annual savings for a major insurer and is backed by A16z Speedrun and Chris Klomp’s family office.","founderDetails":{"Baur Krykpayev":{"role":"CTO","bio":"Building logic in Logical Health. 2x founder. 🤞 Previously, building AI GPUs at Meta and moving protobuffers at Google. Builder."},"Lauren Bilbo":{"role":"CEO","bio":"Hi, I'm Lauren. Before founding Logical Health I was a software engineering manager at Google. I'm also a Stanford MBA and licensed health insurance broker."}}},
  "SR005:Luvu": {"officialUrl":"https://speedrun.a16z.com/companies/luvu","officialOverview":"Basis | The Human Foundation behind Frontier AI","founderDetails":{"Alexis Sursock":{"role":"CEO","bio":"Ex-Duolingo. 300k+ IG/YT. Princeton CS. Retention-obsessed."},"Creston Brooks":{"role":"CTO","bio":"ML at Princeton, TikTok, Sentient. Published at neurips/naacl/emnlp etc. Retired speedcuber."}}},
  "SR005:Margin": {"officialUrl":"https://speedrun.a16z.com/companies/margin","officialOverview":"Margin understands customer behavior in ways never before possible, enabling brands to offer precisely targeted rewards and creating new revenue opportunities. Customers earn points, with dynamic rewards that adapt to their preferences in real time. Built with AI, Margin enables experiences that traditional financial institutions cannot replicate. Premium brand partners are choosing Margin to create deeper customer relationships. From daily spending to mortgages, Margin is building the AI platform to power the future of personalized consumer credit.","founderDetails":{"rishi serumadar":{"role":"ceo","bio":"did sneaker bots at 17 to help resellers automate purchasing at scale, $XM ARR, $XXM+ gmv. also did a bnpl and a realtime credit bureau."}}},
  "SR005:Metal": {"officialUrl":"https://speedrun.a16z.com/companies/metal","officialOverview":"Metal provides an end-to-end operating system for fundraising. Equipped with industry data and the user's Company context, the platform brings efficiency and intelligence to key workflows involved in the fundraising process.","founderDetails":{"Usman Gul":{"role":"Founder/CEO","bio":"Raised $120m for my first startup from top-tier investors. Now building the infrastructure layer for fundraising."}}},
  "SR005:Moescape AI": {"officialUrl":"https://speedrun.a16z.com/companies/moescape-ai","officialOverview":"Moescape is the leading UGC platform for anime fans. In one place, users design characters, turn them into images and videos, give them voices, and actually chat with them. Fans don’t just make content here, they build universes together. That’s what makes Moescape different.","founderDetails":{"Arash Khazraie":{"role":"AI Head","bio":"Experienced in Deep Learning and Machine Learning. PhD in Physics."},"Rob Latt":{"role":"CEO","bio":"A life long anime fan, formerly in banking: JPMorgan, Goldman Sachs and the Federal Reserve bank of Chicago."},"Thiha Min":{"role":"CTO","bio":"was employee #1 at Postmates. Interested in building effective teams, good company culture, and creating products that customers would love."}}},
  "SR005:Nexxa.ai": {"officialUrl":"https://speedrun.a16z.com/companies/nexxaai","officialOverview":"Nexxa.ai is building Agentic AI for industrial engineering. 0 to 980K in 9 months. 3x every quarter. Our intelligent agents integrate with legacy systems and complex workflows to help heavy industry companies automate critical engineering and operational processes. With a 100% activation rate on all projects and rapidly growing contracted revenue, Nexxa is redefining how industrial enterprises deploy AI in mission-critical environments.","founderDetails":{"DH Huang":{"role":"Co-Founder & CTO","bio":"Silicon Valley native that grew up making printed circuit boards and building HAM radio antennas. 20+ years in Software, Engineering, IT/DevOps, Manufacturing and Solutions/Services.\nL42: Masters in Cybersecurity from UC Berkeley, CISSP, CCSP. Focused on skyrocketing Nexxa.ai to new levels!"},"Philipp Wehn":{"role":"CEO","bio":"Germany's top40under40, ex-Siemens, ex-Kearney 10+ Years in Rail, Metal, Automotive, Construction. Unique insights into these industries now bringing AI into this underserved, misunderstood and neglected market."},"O":{"role":"CE","bio":"at Nexxa.ai Philipp Wehn Germany's top40under40, ex-Siemens, ex-Kearney 10+ Years in Rail, Metal, Automotive, Construction. Unique insights into these industries now bringing AI into this underserved, misunderstood and neglected market."}}},
  "SR005:Ocoder": {"officialUrl":"https://speedrun.a16z.com/companies/ocoder","officialOverview":"Beyond simple vibe coding — Ocoder is a communication tool that helps non-technicals build on top of real codebases and share ideas with engineers, VPs and others within their company. New features can be built cheaply, and getting feedback is easy with share links.","founderDetails":{"Ben Standefer":{"role":"Founder & CEO","bio":"I'm a 3x founder. My previous company was Command E, a high-polish cloud search app which was funded by top Silicon Valley investors and acquired by Dropbox, where it became Dropbox Dash. Before that I was the 3rd engineer at Eventbrite and also worked at Digg.com and First Round Capital."},"Chris Dunavan":{"role":"Co-Founder & CTO","bio":"Eng #1 @ Command E (acq. by Dropbox), in Bay Area since the 90s: Responsys (acq. by Oracle), VMware, Idealab!"},"O":{"role":"Founder & CE","bio":"at Ocoder Ben Standefer I'm a 3x founder. My previous company was Command E, a high-polish cloud search app which was funded by top Silicon Valley investors and acquired by Dropbox, where it became Dropbox Dash. Before that I was the 3rd engineer at Eventbrite and also worked at Digg.com and First Round Capital."}}},
  "SR005:Oleum": {"officialUrl":"https://speedrun.a16z.com/companies/oleum","officialOverview":"The Oleum team is a group of former quants, building AI tools that help users better understand and interact with data. Our long-term vision is to become the ubiquitous infrastructure layer for all data-oriented businesses.","founderDetails":{"Alejandro Ballesteros":{"role":"CTO","bio":"Prev: Equities Quant Research @ Bridgewater, Quant Portfolio Manager @Gelber Group , Undergrad @ Stanford Engineering"},"Beni Shafer-Sull":{"role":"Head of Product","bio":"- Prev quant researcher at Bridgewater: Head of research engineering for Asia strategies, incl BW’s $8B AUM onshore China fund (largest hedge fund in China) - Former founder. Wharton (Finance).\nL44: Penn Engineering (Systems Eng, CS, Math)"},"Evan Steinberg":{"role":"COO","bio":"Employee #7 at Alchemy ($10bn valuation) Employee #1 at Down to Lunch (reached #1 social app on app store)"},"Leo Korsunsky":{"role":"CEO","bio":"Previosuly a quant researcher at Bridgewater"}}},
  "SR005:Pen.dev": {"officialUrl":"https://speedrun.a16z.com/companies/pendev","officialOverview":"VIDEO: https://x.com/tomkrcha/status/1973033971010449696 Design right where you code. No more design handoffs. Pencil is agent driven MCP canvas built around open design format that lives in your codebase. It works with Cursor, Claude Code, VSCode, OpenAI Codex, etc.","founderDetails":{"Tom Krcha":{"role":"Founder, CEO","bio":"Building Pencil.dev, previously worked on Around - video calls (Acquired by Miro) and co-founded Alter avatars (Acquired by Google). Product, design, code, ML, 3D, AR, audio/video."},"P":{"role":"Founder, CEO at","bio":"en.dev Tom Krcha Building Pencil.dev, previously worked on Around - video calls (Acquired by Miro) and co-founded Alter avatars (Acquired by Google). Product, design, code, ML, 3D, AR, audio/video."}}},
  "SR005:Prepp": {"officialUrl":"https://speedrun.a16z.com/companies/prepp","officialOverview":"We develop student- and educator-focused modules that solve both administrative and content-driven issues from material generation, automatic grading, attendance, and student engagement.","founderDetails":{"Eric Tang":{"role":"Chief Executive Officer"},"Simon Yang":{"role":"Co-Founder","bio":"By teaching, we learn!"}}},
  "SR005:Presia": {"officialUrl":"https://speedrun.a16z.com/companies/presia","officialOverview":"We build AI agents to automate the $1Tn wasted on manual work in management consulting, so consultants can focus on problem solving and collaboration. We’re already working with globally recognized enterprises and signing a new consultancy every week. We're ex-MBB consultants, Jane Street Alumni and Cambridge AI researchers, with angel backing by senior partners from top consultancies.","founderDetails":{"Nevin Pillai":{"role":"Co-founder and CEO","bio":"I studied Computer Engineering at Cambridge University with scholarships, graduating as the top student in my college. Then I worked at McKinsey as a consultant. I saw first-hand how much time was spent on grunt work. Much of this work can now be done with Presia Agents."},"Raghav Chandra":{"role":"Co-founder and CTO","bio":"I studied at Cambridge where I published research in AI.\nL40: I've worked in product at Jane Street, in ML and Software Engineering and as a Consultant at Bain. At Bain, I saw firsthand how much time was spent on grunt work and I have spent whole days on manual work. Much of this work can now be done with Presia."}}},
  "SR005:Rork": {"officialUrl":"https://speedrun.a16z.com/companies/rork","officialOverview":"Turn your ideas into real mobile apps in minutes Rork is the app that builds mobile apps. Prototype & share real native apps, on your phone or desktop. Build something you want with Rork now","founderDetails":{"Daniel Dhawan":{"role":"Co-founder & CEO","bio":"3x founder. Mobile apps since 21yo, grew to #2 App Store, 6 figures in annual revenue. Generalist: engineer, designer, growth hacker, prev physics in #1 uni in Eastern Europe, won national olympiads in physics & mats."},"Levan Kvirkvelia":{"role":"CTO","bio":"3x founder, dropout, built a mobile app with 2M users & 6 fig ARR at 17yo; Top 1 AppStore; fought Russian gov."}}},
  "SR005:Sans Strings Studio": {"officialUrl":"https://speedrun.a16z.com/companies/sans-strings-studio","officialOverview":"Sans Strings Studio is a first-of-its-kind tech-augmented transmedia studio operating at the convergence of gaming, film, social, and live events. Using real-time technology, we co-produce and develop properties seamlessly across interactive, linear, and live formats. Our non-linear, scalable toolsets allow us to meet rising demand with lower financial risk while preserving the artistry of human-crafted content. Our F.E.L.T.","founderDetails":{"Sébastien Deguy":{"role":"CEO"}}},
  "SR005:Shockwave": {"officialUrl":"https://speedrun.a16z.com/companies/shockwave","officialOverview":"We’re harnessing AI and decades of gaming expertise to create the ultimate destination for daily play! Daily games are a massive opportunity in the 50B+ casual gaming market. They are subscription driven business, with universal appeal to gamers and non gamers alike. With hundreds of millions of players hits like Wordle have popularized the daily game. We are building games across more categories more genres and new interactive experiences to expand and win this market!","founderDetails":{"Bill Kara":{"role":"CEO","bio":"Bill is the CEO / Cofounder of Shockwave where he oversees the company's operations, growth strategies and product development. As a lifelong gamer and entrepreneur, Bill has been in the gaming industry for over 20 years with a passion and love for blending gaming, education technology and now exploring web3 and AI powered gaming. Bill previously co-founded "},"Erin Torbiak":{"role":"Chief Technology Officer","bio":"Erin Torbiak has been working with her current cofounders since the startup days of Math Games during her university summers.\nL55: Erin’s role has expanded from writing the original math questions to include project and executive team management, process design and implementation, and ongoing technical learning as the library of products and games has evolve"},"Rhys Jones":{"role":"Chief Product Officer","bio":"I am a seasoned product and technology executive with over two decades of experience leading teams at the intersection of gaming, SaaS, and digital media.\nL58: Having served as CTO, VP of Product, and now Chief Product Officer, I bring a unique blend of product vision, technical expertise, and strategic leadership. My passion lies in building engaging digita"}}},
  "SR005:Sonatic": {"officialUrl":"https://speedrun.a16z.com/companies/sonatic","officialOverview":"a desktop assistant that observes your screen, learns how you work, and then does it for you.","founderDetails":{"Kinjal Nandy":{"role":"CEO","bio":"building autonomy engines focusing on tasteful creation, and devotion"},"Sahil Dhull":{"role":"Former CTO"}}},
  "SR005:SoulLink": {"officialUrl":"https://speedrun.a16z.com/companies/soullink","officialOverview":"Virtual friends are the next social revolution, and SoulLink is making it real. We fuse AAA game tech with emotional AI to craft next-gen companions that look cinematic, act human, and feel alive. With a proven founder and a high-speed team, SoulLink will bring presence to a billion lives.","founderDetails":{"Michael Shang":{"role":"Founder & CEO","bio":"Repeat Founder; 1 Exit Post Series-A; Ex-Director of Product; Dropped out from Carnegie Mellon MBA and MSE to build SoulLink - bringing virtual friends mainstream."}}},
  "SR005:Sounding": {"officialUrl":"https://speedrun.a16z.com/companies/sounding","officialOverview":"Pelago builds voice-first AI wellness apps that solve adherence: the hardest problem in health.","founderDetails":{"Sekip Gokalp":{"role":"Co-Founder & CEO","bio":"Şekip Can Gökalp is a repeat founder with two 8-digit exits in consumer and gaming. He co-founded Mobilike (acquired by Opera), ran AdColony as COO through critical turnaround at $500M+, grew Coda to $25M ARR, and as CEO of Fusebox drove a 10x rise to $50M ARR through to its sale to Nazara.\nL40: Now Pelago’s co-founder and CEO, he applies a proven zero-to-sc"},"Will Wynne":{"role":"Co-founder & CPO","bio":"Repeat founder, and previously Head of Product at mobile gaming unicorn Tripledot Studios. Responsible for two thirds of company revenue during growth from 30 to 450 people and $1.4B valuation."}}},
  "SR005:Sourcerer": {"officialUrl":"https://speedrun.a16z.com/companies/sourcerer","officialOverview":"Sourcerer is the world’s first fully autonomous AI procurement agent. We help distributors automate their entire sourcing process, from identifying suppliers and negotiating prices, to managing freight and credit terms, all through a single intelligent platform. Using proprietary AI technology, Sourcerer analyzes product needs, tariff exposure, supplier networks, and logistics constraints to instantly generate optimized sourcing recommendations. Our customers save time, reduce costs, and unlock access to high-quality manufacturers across Asia, Latin America, and the U.S.","founderDetails":{"Peter Cetale":{"role":"CEO","bio":"Led my first startup to be acquired and then during Covid ran a healthcare distribution business that did $60m in revenue. Now using AI to redefine global trade."}}},
  "SR005:Syzygy": {"officialUrl":"https://speedrun.a16z.com/companies/syzygy","officialOverview":"Category leaders own their AI models, unlocking deep customization, cost optimization, and data provenance. Pioneer, by Maniac, democratizes this power, swapping third-party vendors for proprietary, SoTA, task-specific models at enterprise scale. You plug in your live inference, evaluators, and post-training tools, and we orchestrate your model layer. With Maniac, every interaction with the AI layer is your Intellectual Property.","founderDetails":{"Dhruv Mangtani":{"role":"Founder","bio":"B.S. Physics and Mathematics at Stanford\\\\ 2x founder\\\\ theoretical physics at Caltech\\\\ ML research at Berkeley\\\\ building Maniac day & night"}}},
  "SR005:Taya": {"officialUrl":"https://speedrun.a16z.com/companies/taya","officialOverview":"Wearables today are gadgets. We believe they should be jewelry. Taya is a design-led wearable company founded by ex-Apple engineers and Stanford Product Design grads, creating jewelry-grade hardware that makes AI feel personal, beautiful, and effortless to wear. Our first product brings AI off the screen and into everyday life as a living memory layer, capturing experiences in real time, turning them into a searchable, contextual timeline, and evolving into intelligence that anticipates your future.","founderDetails":{"Elena Wagenmans":{"role":"Founder / CEO","bio":"Founder and CEO of TAYA, where we’re building the future of wearable AI. I studied Product Design B.S. and Mechanical Engineering M.S. at Stanford and worked on the iPad Pro at Apple, designing components like speakers and RF systems. Formerly NCAA DI Athlete and First Team All-American and Captain, I’m foregoing training for the LA 2028 Olympics to pursue t"}}},
  "SR005:URSA Mining": {"officialUrl":"https://speedrun.a16z.com/companies/ursa-mining","officialOverview":"At URSA, we're developing a universal, physically intelligent operating system for mining equipment. With our system, mines can transform their existing fleets into autonomous earth-moving robots, boosting revenue and increasing efficiency. Our team consists of world-leading experts in physical AI, robotics, and tele-operations. Founded by a second-generation miner and former particle physicist, URSA is on a mission to build the world's first fully autonomous mine.","founderDetails":{"Johann Dias":{"role":"CEO","bio":"Despite my interest in the industry, I actually wanted nothing to do with mining growing up. Being born in the industry does that to you. After studying particle physics at CERN, I rediscovered my love for mining while working for my dad at one of his mines. I've always been a bit of a dreamer, and I kept thinking, \"Autonomy just makes sense for this.\" And t"}}},
  "SR005:Variant": {"officialUrl":"https://speedrun.a16z.com/companies/variant","officialOverview":"Our proprietary AI models and design systems transform memes, jokes, fanfics, or even office drama into shareable interactive games. Variant is to interactive media what Facebook is for text, what Reddit is for GIFS, and what Tiktok is for videos.","founderDetails":{"Zoe Lynch":{"role":"Founder and CEO","bio":"I’m Zoe, an AI researcher and Stanford master’s graduate with experience at EA, Dolby, Amazon, with research spanning three Stanford labs in gaming, AR, and artificial intelligence. I founded Variant because I’ve always loved stories—but with word-processing differences growing up, “words” didn’t work for me. Games did. Games became my language of expression"}}},
  "SR005:Vega": {"officialUrl":"https://speedrun.a16z.com/companies/vega","officialOverview":"Vega: AI-Powered Social Orbits On Vega, you leave notes about friends to unlock notes about yourself. Our models analyze these notes to generate AI-powered social orbits, hyper-curated groups of people who will change your life, surfaced with perfect context like mutuals, trust, and shared experiences. We’re building the largest textual data moat on human relationships by gamifying the way people leave notes for each other. For the first time, LLMs can analyze millions of raw, human-written notes at scale and turn them into structured & meaningful insights about our relationships.","founderDetails":{"Benjamin Lee":{"role":"Cofounder, CTO","bio":"cto @ vega / BEING SO NORMAL"},"Madeline Park":{"role":"Cofounder, CEO","bio":"ceo @ vega / prev @ uber ml, atob, chan zuckerberg biohub, columbia, pear vc, neo nyc marathon finisher & published in science"}}},
  "SR005:YKB": {"officialUrl":"https://speedrun.a16z.com/companies/ykb","officialOverview":"Speculation is becoming how people engage with culture. Betting & prediction markets are exploding. But they’re built for gamblers, not fans. Our unlock = Receipts: interactive prompts generated by our agent when news breaks. Fans react, predict, & compete together. 1M+ Receipts created since NFL beta began in September. 140k+ Receipts created in the last week. Starts in sports, expands to all areas of culture. We believe tapping into this fan energy around takes & predictions will bring speculation beyond just gamblers, to a billion people.","founderDetails":{"David Lu":{"role":"CEO, Co-founder","bio":"Harvard CS dropout; co-founded Airr - social podcast app, 100k+ users; Built products used by ESPN & The Athletic. Now cofounder of YKB, building the prediction experience fans actually want."},"Sam Rukeyser":{"role":"Cofounder","bio":"Harvard dropout; cofounded Airr, grew to 100k+ organically; built products used by ESPN & The Athletic. With YKB, we're building the prediction platform fans actually want."}}},
  "SR005:Zero Billion": {"officialUrl":"https://speedrun.a16z.com/companies/zero-billion","officialOverview":"Zero Billion is creating BookTok, the fastest growing AI TV show platform. Shows are made in under 1 hour for <$10/min. Already Top 10 on iOS in our category with $2M+ annualized revenue.","founderDetails":{"Ansh Chopra":{"role":"Founder","bio":"Founder of Zero Billion ($2M ARR) Prev built an AI chatbot platform with over 2 million users. 5x Top 200 iOS apps. Started the #1 open-source AI wearable."},"Nik Shevchenko":{"role":"founder"}}},
  "SR005:Zingroll": {"officialUrl":"https://speedrun.a16z.com/companies/zingroll","officialOverview":"Zingroll is where creative 20-year olds become Walt Disney's of tomorrow by streaming their Netflix-quality AI-shows/movies to the rest of the world. This is the future of Netflix and streaming at-large. We all scroll Netflix but fail to find stuff to watch, and then finally settle on whatever is relatively watchable. Zingroll changes this forever. Come talk to us!","founderDetails":{"Harshit Yadav":{"role":"Founder & CEO","bio":"Previously built 2 viral consumer apps, led Dartmouth's Mixed Reality, Z Fellow, Thiel Fellow finalist, discovered 2 asteroids, and have been film-making since high-school."}}},
  "SR006:Acceler8": {"officialUrl":"https://speedrun.a16z.com/companies/acceler8","officialOverview":"CEOs spend $400B on AI transformation, consulting, and systems — and still can't answer their most critical workforce questions without months of manual work. What should org look like as humans and AI agents work side by side? Which roles to automate? Where to redeploy talent? Who should step into critical roles? Today these decisions run through spreadsheets, consultants, and static HR systems. They take months, cost millions, and are outdated before they land. As AI compresses years of org change into quarters, workforce decisions can no longer happen once a year.","founderDetails":{"Chinmay Chauhan":{"role":"Co-Founder","bio":"• 2nd-time Founder: previously raised $80M from Peter Thiel's fund, DST, Goodwater & YC; scaled to 400 employees, $5B in payments • Forbes 30 Under 30 • Product Leader at Grab, which acquired Uber SE Asia, during 21x hypergrowth • IIT Bombay, Computer Science • Angel investor in 40+ startups"},"Trisha Pathak":{"role":"Co-Founder","bio":"One of youngest Director at Big 4. Restructured 30+ companies, globally. Chief People Officer for Global Energy Company.\nL51: Wharton Fellow and Stanford-GSB. I built Acceler8—an AI-powered workforce intelligence platform that shows who is ready to step up, who needs support, and where tough decisions are needed—driven not by gut feel, but by agentic AI."}}},
  "SR006:Advocate": {"officialUrl":"https://speedrun.a16z.com/companies/advocate","officialOverview":"Advocate is the AI chief of staff for seniors and their families. If a senior can answer the phone, Advocate is built for them - they call one number and ask for anything: rides, groceries, home repairs, appointments. We complete each request end to end and text the family when it's done. We call them, too, so someone notices when something's off. Everything lands on one shared record, so no one person has to hold it all themselves.","founderDetails":{"Andrew Baran":{"role":"Co-Founder & CEO","bio":"I'm a 2x founder raised by a mom working as a care coordinator. Co-Founded Leilo.com (leading CPG brand in category, profitable, growing). Led software DD and AI workstreams at McKinsey. Software growth equity investor at Radian Capital (healthcare + vertical SaaS). Class President & Oxbridge scholar @ Columbia University; studied Economics, Political Scienc"}}},
  "SR006:Alike": {"officialUrl":"https://speedrun.a16z.com/companies/alike","officialOverview":"Agents move fast, but often miss what their team has decided or already built. Alike has built a semantic web for agents: a live model of your work that carries decisions and context between sessions, so agents can build on each other's progress. It works underneath tools like Claude Code, Codex and Cursor, alongside Slack, Linear and GitHub, while people control what they share. Built by a team of Oxford and MIT PhDs, Alike helps agents work as a team, not in isolation.","founderDetails":{"Addi Haran Diman":{"role":"Co-founder and CEO","bio":"I started university aged 13 and got my PhD from Oxford at 21, then pivoted to operational and leadership roles - but always out of an obsession with analytically studying group behavior and social networks"},"Danial Hussain":{"role":"Chief Commercial Officer","bio":"Hey, I'm Danial, the Chief Commercial Officer at Alike. Before starting Alike with my best friends, I represented over 30,000 individuals as student body president at Oxford and led national viral marketing campaigns. I also worked on growth at a sequoia-backed start-up."},"Max Van Kleek":{"role":"CTO, Alike","bio":"Hi! I'm CTO of Alike, and an Associate Professor of Computer Science at Oxford University, with a PhD in Computer Science from MIT (2011).\nL59: My research over the past 25 years (at MIT, PARC, Nokia, and IBM) has focused on human-AI interaction paradigms, privacy-preserving systems, and core AI ethics and safety."}}},
  "SR006:Amdahl": {"officialUrl":"https://speedrun.a16z.com/companies/amdahl","officialOverview":"Amdahl helps B2B enterprises make sense of messy go-to-market data — structuring it, operationalizing it, and giving teams one place to build data-driven strategies and execute on them, all grounded in rich customer context. AI in GTM fails when the input data is wrong. Amdahl is the intelligent context layer that structures and understands your data across Sales, Support, and Customer Success, and channel performance. So teams can act on the right context and drive real revenue outcomes.","founderDetails":{"Annette Sung":{"role":"Co-founder & CEO"},"Arya Soltanieh":{"role":"Cofounder & Lead Engineer"},"Robert Khoury":{"role":"Co-Founder & CTO"}}},
  "SR006:Antihero Studios": {"officialUrl":"https://speedrun.a16z.com/companies/antihero-studios","officialOverview":"💡 Insights: Gen Z play video game to socialize. Social mechanics increases organic growth and retention. Nobody is pushing social play on mobile. 👥 Team: We spent our careers taking complex multiplayer genres and making them accessible to hundreds of millions of players. Antihero Studios is a mobile game studio pushing the boundaries of social on mobile, founded by former Supercell and King veterans who collectively worked on eight billion-dollar games including Brawl Stars, Clash Royale, and Candy Crush.","founderDetails":{"Andre Parodi":{"role":"CTO Antihero Studios","bio":"Previously Senior Technical Director at King. CTO and Co-founder of 2 startups."},"Brice Laville Saint Martin":{"role":"CEO, Co-founder","bio":"CEO Cofounder at Antihero Studios. Previously Art Director of Clash Royale, and Supercell Marketing Creative Director at Supercell."},"Frank Yu Yan":{"role":"Chief Product Officer","bio":"Former Lead Game Designer on Brawl Stars at Supercell and Senior Game Designer on Hearthstone at Blizzard."}}},
  "SR006:August": {"officialUrl":"https://speedrun.a16z.com/companies/august","officialOverview":"August is the platform where banking work runs. Domain-specific AI for commercial banking, turning underwriting, servicing, risk etc. into software. Usage compounds a proprietary context layer. Deployed at a +$170B bank. Pipeline growing. Founded by ex-8200 operators who built military AI systems. reach out at bar@tryaugust.com","founderDetails":{"Bar Ittah":{"role":"Co-Founder & CEO"},"Tom Tankilevitch":{"role":"Co-Founder & CTO","bio":"Ex-unit 8200 / built the AI backbone of a national intelligence unit. Tech Lead @Iguazio (acq. by McKinsey) / AI infra for data scientist to deploy models fast. Founding Team @Port ($158M raised) / Led ~20 person engineering group building AI infra"}}},
  "SR006:Auto": {"officialUrl":"https://speedrun.a16z.com/companies/auto","officialOverview":"Auto is your AI camera. Turn your photos into Frames - mini apps that help you everyday. The founding team is ex-Snapchat, has spent years working on camera & creator products and both have significant previous exits. Frames make your camera intelligent. They know your calories, help you dress better, care for your plants, split the bill, give you travel advice, remember your goals, and anything else you can think of. And if Auto can't do it yet, you can build a Frame that can.","founderDetails":{"Dave Evans":{"role":"CEO","bio":"Dave is CEO of Auto. Dave was previous Director of Engineering at Snap for Snap Mini-Programs, Games, Bitmoji, SnapKit, Virtual Currencies. Dave previously built PlayCanvas, the world's leading 3D web graphics engine, which was acquired by Snap in 2017."},"Sam Hare":{"role":"CTO","bio":"Sam is CTO of Auto. He has a PhD in computer vision and previously founded Seene, which pioneered mobile 3D reconstruction technology and was acquired by Snap in 2016.\nL48: At Snap he led the Lens Experience engineering team, responsible for all the AR product surfaces in the Snapchat app."}}},
  "SR006:Belong": {"officialUrl":"https://speedrun.a16z.com/companies/belong","officialOverview":"The music business counts everything. Plays, tickets, followers, streams. Every number except the one that matters: who. Who’s been in the room ten times? Who bought the record, then the reissue. Who was there before anyone, and never left. Fans have spent decades proving their devotion. Belong is there to make that devotion mean something. We build artist-owned membership programs, on real financial infrastructure.","founderDetails":{"Ash Pournouri":{"role":"Co-Founder & President","bio":"Ash Pournouri (LL.M., Stockholm University) is a two-time Grammy-nominated serial entrepreneur who pioneered the modern music business, co-writing the majority of Avicii's catalogue and executive-producing all releases while building one of the most recognisable global brands in entertainment.\nL43: In 2014 he created and co-founded Brilliant Minds with Spoti"},"Nick Holmsten":{"role":"Co-Founder & CEO","bio":"Founder and operator at the intersection of culture, technology, and product.\nL42: Founder of Tunigo (acquired by Spotify), and former Global Head of Music at Spotify, where I spent seven years helping scale the platform globally—shaping playlists and discovery into core product infrastructure and working with many of the world’s biggest artists and labels."}}},
  "SR006:Bilrost": {"officialUrl":"https://speedrun.a16z.com/companies/bilrost","officialOverview":"Every credit decision runs on context, OMs, tax, financials, borrower history, the judgment of your best underwriters, scattered across systems that don't talk to each other. The hard part of automating credit was never the doc processing. It was turning that context into something accurate enough to act on and auditable enough to defend. Bilrost is AI-native infrastructure for commercial credit.","founderDetails":{"Peter Hsu":{"role":"Cofounder & CTO","bio":"I’m a founder-CTO focused on building AI-native systems that turn messy, real-world information into reliable, scalable products. At Bilrost, I’m building infrastructure that applies modern AI and systems engineering to high-stakes financial workflows—where accuracy, traceability, and performance actually matter.\nL45: My work sits at the intersection of AI-d"},"Silvia Chen":{"role":"Co-Founder & CEO","bio":"Silvia grew up around large-scale real estate development, seeing firsthand how underwriting decisions determine whether projects move forward, and how much of the process remains manual. She now leads Bilrost, building autonomous loan infrastructure to modernize real estate finance. She previously led product at Blockchain.com, where her team drove 30x trad"}}},
  "SR006:Bota": {"officialUrl":"https://speedrun.a16z.com/companies/bota","officialOverview":"Bota is the first AI agent infra for real world context, starting with voice data. In just 5 weeks, Bota grew from 0 to over $700k in contracted ARR. Our customers include top AI agent companies in sales, healthcare, law, finance, productivity and many more. The Bota founders sold their previous startup for 8 figures to a top AI hardware company. We built hardware at Stanford, Tesla and Apple, and built infra at Amazon and AWS. We deeply understand AI hardware and B2B. Our vision is to be the default real-world context engine for AI agents.","founderDetails":{"Qi Zhang":{"role":"Co-founder & CTO","bio":"Repeat AI founder with 8-figure exit. Ex-Amazon, YC"},"Ruming Zhen":{"role":"Cofounder CEO","bio":"Repeat AI founder with 8-figure exit. Ex-Stanford Robotics, YC, Tesla, Apple"}}},
  "SR006:Cascade": {"officialUrl":"https://speedrun.a16z.com/companies/cascade","officialOverview":"Cascade is the AI prediction layer for all construction projects, enabling the physical world to be built faster and financed smarter. Our clients have built airports like JFK & LGA, hotels like the Four Seasons & the Ritz, and data centers and nuclear reactors. Hannia & Joana worked together for many years at another AI startup before starting Cascade. Hannia helped scale Google Pay from zero to 100M users, built AI for Pakistan's COVID response and received an award from the Prime Minister. Joana built ML systems for Google Search and for the UK's largest trading app (scaleup).","founderDetails":{"Hannia Zia":{"role":"CEO","bio":"Started my career in product at Google, I was on the team that scaled Google Pay India 0 → 100M users. I got a patent for my payment authentication design and wrote White Paper with the World Bank on open API payment systems. Built AI for the Pakistani Government during COVID, received an award from the Prime Minister and got Forbes 30u30.\nL47: Led Product @"},"Joana Ferreira":{"role":"CTO","bio":"Early Eng @ Freetrade (UK largest trading app), ML for Google Search, Amazon and AI Platform Lead @ UnlikelyAI. Grew up in a family of carpenters."}}},
  "SR006:Cedar": {"officialUrl":"https://speedrun.a16z.com/companies/cedar","officialOverview":"Cedar is building the AI-native professional network. Recruiting is the wedge. The best talent doesn't apply. It gets referred. But referrals break as companies scale. Not from culture, but from math. Companies like Stripe threw 100 people and $10M a year at this problem. Cedar scales this with agents. Every 15-minute call maps an employee's trusted professional relationships, surfaces high-signal candidates, and deepens a graph no one else is building. Every customer makes it smarter. Traction: Closed $3M in revenue while in stealth.","founderDetails":{"Beier Cai":{"role":"Cofounder & CTO","bio":"Tech entrepreneur, Cofounder & CTO @ Cedar, @Commit.dev, @FirstCoin Capital. Founding engineer and senior director @ Hootsuite"},"Greg Gunn":{"role":"CEO / Co-Founder","bio":"Co-founder and CEO of Cedar. Built Hootsuite from 5 people to 1,500 and zero to $100M ARR in under four years."}}},
  "SR006:Clair Health": {"officialUrl":"https://speedrun.a16z.com/companies/clair-health","officialOverview":"$800K D2C revenue, $18M B2B contracts signed in <8 weeks. Clair is the first continuous hormone monitor- a jewelry-inspired wrist wearable that helps women understand their bodies and optimize their health. Clair leverages a custom biosensor stack and an in-house female biology world model to track estrogen, progesterone, LH, and PdG. Its unique hormonal insights can be applied to understanding skin health, fertility, mood changes, (peri)menopause, and female athletic optimization.","founderDetails":{"Jenny Duan":{"role":"CEO"}}},
  "SR006:Coalition Systems": {"officialUrl":"https://speedrun.a16z.com/companies/coalition-systems","officialOverview":"Coalition Systems is building the shared coordination layer for the national security ecosystem. The defense software stack is hyper-fragmented, and in the absence of purpose-built infrastructure, military units, agencies, intelligence services, and critical infrastructure coordinate on Signal, WhatsApp, and Google Sheets. None of them connected by software built for the purpose. Coalition OS fixes that. Founded by an Oxford AI Engineering PhD researcher, a critical infrastructure engineer, and a former US DoD intelligence officer. Backed by General H.R.","founderDetails":{"Freddie Wollen":{"role":"Co-Founder & CTO","bio":"www.coalition.systems Freddie Wollen is a mechanical engineer with expertise in energy systems and critical infrastructure."},"Vijay Pathak":{"role":"Co-Founder & CEO","bio":"Vijay Pathak is a PhD Researcher in AI Engineering at the University of Oxford. He holds a B.A. from Yale University. Speaker for NATO, TATA, CES."}}},
  "SR006:Concorda": {"officialUrl":"https://speedrun.a16z.com/companies/concorda","officialOverview":"Concorda is building the AI operating system for litigation. Built by two lawyer-engineers (Harvard CS, UChicago Law, Northwestern Law), we saw firsthand that existing legal AI tools sit on top of workflows instead of executing them. We’re building the system that runs litigation end to end, charging for both our legal services (AI-native litigation services) and access to our platform (B2B SaaS).","founderDetails":{"Ke Ma":{"role":"COO","bio":"I'm a former litigator and ex-mckinsey associate building the AI operating system for trial lawyers."},"Samuel Oh":{"role":"CEO","bio":"Building the future of litigation tech"}}},
  "SR006:Crebit": {"officialUrl":"https://speedrun.a16z.com/companies/crebit","officialOverview":"Crebit is unlocking the next wave of stablecoin-powered foreign exchange adoption. Stablecoin foreign exchange handles $9T in annual volume yet represents just 1% of global foreign exchange. The bottleneck: blockchain quotes expire in 10 minutes, making it impossible for businesses to lock in rates and guarantee payments. Crebit built the missing layer: the ability to lock blockchain exchange rates for up to 180 days. Combined with a Silicon Valley Bank partnership, Crebit gives enterprises the rate certainty they need while delivering the cost benefits of stablecoin foreign exchange.","founderDetails":{"Jensen Coonradt":{"role":"CEO - Crebit Pay"},"Simmi Sen":{"role":"Co-Founder","bio":"Stanford CS + Design"}}},
  "SR006:Emanate": {"officialUrl":"https://speedrun.a16z.com/companies/emanate","officialOverview":"We're building the AI Revenue Engine for industrial materials companies: autonomous AI agents that run and grow revenue operations end-to-end. Our mission is to help the most important industrial materials companies in America experience exponential growth.","founderDetails":{"Kiara Nirghin":{"role":"CEO","bio":"Award-winning Stanford AI researcher, engineer, and Thiel Fellow. Winner of the Google Science Grand Prize and one of TIME Magazine’s Most Influential."}}},
  "SR006:Grove Tax": {"officialUrl":"https://speedrun.a16z.com/companies/grove-tax","officialOverview":"Tax preparers spend 65% of their time not doing taxes. They chase documents, do manual data entry, and manage clients back-and-forth. The result: 75% have retired in the last decade, a third of those left want to quit, and the gap between demand and supply widens every year. You cannot close that gap with people. You close it with AI agents. Grove builds autonomous agents that handle the full tax return lifecycle: intake, document extraction, return preparation, and delivery. Grove launched with design customers this past season.","founderDetails":{"Gaurav Mathur":{"role":"Cofounder","bio":"Early engineer at Indeed, leader at Airbnb and Cloud Kitchens. Building Grove to automate the tax industry"},"Uday Nandam":{"role":"CEO","bio":"I've spent a decade building tax software from the inside. I co-founded Intuit Link, led Product at IBM Watson, ProConnect and Lacerte at Intuit, and served as Head of Product for UltraTax at Thomson Reuters. Now I'm building Grove to disrupt what I helped create."}}},
  "SR006:Hammock": {"officialUrl":"https://speedrun.a16z.com/companies/hammock","officialOverview":"Hammock is for start ups who want the easiest way to set up health insurance. Employees get a budget they can use on health insurance and wellness products, all with no admin. No paperwork, no guesswork, just covered employees and an AI agent to help along the way. Set up health insurance in 5 min and get back to building shareholder value.","founderDetails":{"Jesse Rose":{"role":"Cofounder & CEO","bio":"Before Hammock, Jesse co-founded Berry Street, a digital health company that he grew to $50M ARR and raised through Series B in 2.5 years. Backed by over $50M from Northzone, Village Global, FJ Labs, and others.\nL50: Prior to Berry Street, Jesse was a product leader at Zocdoc, Kaiyo, and The Infatuation / Zagat."},"Will Dennis":{"role":"Cofounder","bio":"Before Hammock, Will was VP of Product at WeightWatchers (NASDAQ: WW) leading the $1B ARR consumer subscription and telehealth business. Prior to WeightWatchers, Will was a product leader at WhatsApp and HouseParty, and a 2x founder."}}},
  "SR006:Heavi": {"officialUrl":"https://speedrun.a16z.com/companies/heavi","officialOverview":"Heavi is building an AI workforce for the $250B heavy duty repair and service market. As experienced technicians retire, they take decades of institutional knowledge with them. The result is longer service times, harder-to-find parts, and customers losing thousands of dollars a day when their vehicle isn't moving. Heavi fixes this. We're live with 5 design partners, saving up to 30% of employee time and improving margins by ~40%, earning us $100,000 contracted revenue.","founderDetails":{"Michael Holkesvik":{"role":"cofounder / cto","bio":"Prev. CTO at NCX, raised $75M from USV, JP Morgan, and Marc Benioff (board member) to build satellite imagery and machine learning tech for the timber industry.\nL48: Scaled landowner marketplace from 0 to 15,000 members in under 2 years. B.S. Yale Computer Science"},"Sanjay Dasari":{"role":"CoFounder","bio":"Repeat founder. Previously scaled agricultural supply chain marketplace to $250M revenue with $200M raised. Also a ASE T8 Certified Diesel Mechanic - the national standard for Automotive Service Excellence - and an MBA from Harvard Business School."}}},
  "SR006:Hotbox": {"officialUrl":"https://speedrun.a16z.com/companies/hotbox","officialOverview":"Hotbox is Clay for social commerce. Your next customers are already in your likes, comments, and DMs. Hotbox identifies them, matches them to your ICP through deep-level enrichment, and agentically converts your pipeline to expand your untapped revenue potential. Hotbox, pre-launch, has $350k ARR and $4M in pipeline in just 2 weeks of sales. Founded by Harpriya (CEO). She's had two exits and sold her last company to Salesforce, built the LinkedIn ranking algorithm, and is a published NeurIPS author.","founderDetails":{"Harpriya Bagri":{"role":"CEO","bio":"I've grown 3 companies from 0 to millions in ARR by building viral playbooks, with 2 exits. The last one was acquired by Salesforce. As a machine learning engineer, I've built the LinkedIn ranking algorithm, been published in NeurIPS, and built the deep reinforcement learning algorithm used to fine tune the particle beam for Canada's National Particle Accele"}}},
  "SR006:Idilio": {"officialUrl":"https://speedrun.a16z.com/companies/idilio","officialOverview":"Idilio is building the AI Powered Micodrama platform for the 1B Spanish and Portuguese speakers. Micro-dramas are a 14B and emerging global category, but no one owns the Latam market yet – a culturally rich audience raised on telenovelas and now consuming content on mobile. Idilio creates short-form, serialized stories designed for how people watch today: fast, immersive, and built for bingeing. But we’re not just a content platform.","founderDetails":{"Esteban Ramírez":{"role":"Co-founder / CTO","bio":"Software engineer and 2x founder. I build software products end to end, from model to product. MIT-trained in CS and deep learning, MBA from Sloan. I've spent my career in early-stage startups, where I'm most at home. Outside of building companies, I make music — I write, produce, and release my own songs."},"Gabriela Tafur":{"role":"Founder and CEO","bio":"Stanford MBA, lawyer, TV Host (1.5M Followers), Caracol TV, Univision, Forbes 30U30."}}},
  "SR006:Kaaro": {"officialUrl":"https://speedrun.a16z.com/companies/kaaro","officialOverview":"Kaaro is building AI agents for the manual work that still runs railroads, from paperwork and data entry to incident reporting, billing, and other operational workflows that still move through phone calls, email, and tribal knowledge. The founders are second-generation railroaders who have known each other for over a decade. Before Kaaro, they dropped out of Waterloo and UBC at 18 to join Toma (YC W24, a16z-backed) as its first two engineers, where Sai led product and growth and Gautham led infrastructure and reliability as the company scaled from roughly 20 customers to hundreds.","founderDetails":{"Gautham Venkateshwaran":{"role":"Co-founder & CTO","bio":"Building Kaaro, AI for Rail. Previously at founding engineer #2 at Toma (YC W24) & dropped out of UBC after freshman year."},"Sai Surisetti":{"role":"Co-Founder & CEO","bio":"Former professional gamer turned founder. First founding engineer at Toma (a16z, YC) at 18 & dropped out of University of Waterloo during freshman year. Canadian."}}},
  "SR006:Loops AI": {"officialUrl":"https://speedrun.a16z.com/companies/loops-ai","officialOverview":"Loops builds the commerce intelligence layer for brands deploying agents in AI search, virtual try-on, omnichannel sales, and product enrichment. Our agents turn shopper intent into sales, reduce returns, and drive deeper engagement, at every touchpoint, across every channel. With richer, AI-readable product data at its core, the Loops intelligence layer makes your catalog and commerce operations instantly accessible to any AI agent or system. Top brands trust Loops to make their commerce smarter, faster, and more revenue-driven from day one.","founderDetails":{"Ari Nazir":{"role":"CEO","bio":"Entrepreneur since high school, now working on Loopsai.com ($500k+ ARR)."},"Hakan Bas":{"role":"Co-Founder","bio":"Co-founded Peak Games ($1.8B exit to Zynga) https://techcrunch.com/2020/06/01/zynga-acquires-turkeys-peak-games-for-1-8b-after-buying-its-card-games-studio-for-100m-in-2017/"},"Ilker Zorluoglu":{"role":"President"},"Yusuf Bahadir":{"role":"CTO"}}},
  "SR006:Miraka": {"officialUrl":"https://speedrun.a16z.com/companies/miraka","officialOverview":"Miraka is an always-on cardiac care team. We deliver clinician-led preventative care, informed by continuous patient data. Our models use health records and wearables to predict emerging risk and our team intervenes before emergencies happen. All services are covered by insurance. The results: we're reducing readmissions for partner hospitals by >90% and capturing 94% of eligible patients vs the industry average of 10%. $340k annual run rate in 3 months, 71% MoM appointment growth. Founded by Nolan Abeyta (Princeton), Kaz Nakamura (Princeton), and Jesse Abeyta (Amazon)","founderDetails":{"Kazuo Nakamura":{"role":"COO","bio":"Eliminating cardiac readmissions. Youngest team to sell into a top-5 heart hospital. Princeton '23"},"Nolan Abeyta":{"role":"CEO","bio":"Princeton '24, ex-competitive rower, eliminating cardiac readmissions at Miraka."}}},
  "SR006:Mirror Mirror AI": {"officialUrl":"https://speedrun.a16z.com/companies/mirror-mirror-ai","officialOverview":"Mirror Mirror AI is the marketplace where fashion models license their likeness and brands get stunning AI-generated imagery featuring real people. Brands come to our platform, digitally cast real fashion models, and upon approval, use their likeness to generate lookbooks and campaigns in hours instead of weeks while models get paid. Our platform already features agency-signed models who have graced the covers of Vogue and Harper's Bazaar.","founderDetails":{"Yusan Lin":{"role":"CEO","bio":"Yusan Lin is the founder and CEO of Mirror Mirror AI. A fashion model turned computer science PhD and AI research scientist, she has worked across modeling and AI research, including roles at Visa Research and Amazon Fashion. She is now building a future where real people remain central and compensated in the age of AI."}}},
  "SR006:Modaic": {"officialUrl":"https://speedrun.a16z.com/companies/modaic","officialOverview":"Modaic is building the verification and alignment layer for AI decisions. For judgment-heavy workflows like classification, moderation, and automated evaluation, teams today are stuck choosing between expensive human review and weak automated systems that constantly break on edge cases. Modaic solves this by scoring how confident a model is in each decision, routing only uncertain cases to humans, and using that feedback to continuously improve it's underlying instructions.","founderDetails":{"Farouk Adeleke":{"role":"Co-Founder, CEO","bio":"Hey, I'm Farouk! My interests lie in AI-human interaction & search. Prev. Wayfair, IBM, Harvard"},"Tyrin-Ian Todd":{"role":"Co-Founder","bio":"MIT '25 AI+D, prev @ MIT Media Lab, Bloomberg, Axon - Trained foundation transformer models at the MIT Media Lab"}}},
  "SR006:Modern Industrials": {"officialUrl":"https://speedrun.a16z.com/companies/modern-industrials","officialOverview":"Modern Industrials is building the AI workforce for distribution, starting with the $450B+ building materials industry. Co-founders Austin, Vatsal, and Ankit have known each other for decades. Vatsal and Ankit are brothers and Austin is their childhood best friend. The team combines deep technical and operational experience from McKinsey, Google (MLE), and xAI (MTS). Their first product (AI Sales Engine) transforms the back office from a manual cost center into a high-margin engine by automating quoting, order entry, and analytics.","founderDetails":{"Ankit Bhargava":{"role":"CTO @ Modern Industrials","bio":"Former Member of Technical Staff at xAI building agentic AI systems. Previously architecting ML models at Uber on the Surge pricing team to optimize marketplace dynamics driving $XXM in revenue.\nL43: Developed algorithmic trading systems for Kalshi and Polymarket generating $200k+ in profit (16% ROI)."},"Austin Mao":{"role":"Co-Foudner & CEO","bio":"Former Head of Growth & Operations at Roon (Sequoia-backed Series A). Previously led F500 AI engagements at McKinsey and consistently ranked in the top 5% of the company. Selected for Northwestern’s BS/MD program (<0.1% acceptance) and awarded the Frederick Shipp Diebler Award as the top economics undergraduate."},"Vatsal Bhargava":{"role":"Co founder","bio":"Led ML initiatives for Google Ads Bidding, driving $XXXM in incremental revenue.\nL42: Previously built a real-time NBA injury intelligence platform to $10k MRR with 500+ users, and was an early engineer at Bloomfilter (Sequoia-backed)."}}},
  "SR006:Oasis": {"officialUrl":"https://speedrun.a16z.com/companies/oasis","officialOverview":"We’re ex-Palantir FDEs who’ve deployed agent systems in the real world. Everyone thinks of multi agent teams. Unless you are very technical, you can’t build one. Oasis is the hybrid workspace for human-agent teams.","founderDetails":{"Naveen Sharma":{"role":"CTO","bio":"Hey I'm Naveen, an ex-Palantir FDE with a background in AI, robotics, and applied mathematics"},"Stefano Fantini Delmanto":{"role":"CEO","bio":"Prev. Palantir FDE | Religious Studies and Electrical Engineering at Stanford | Ask me about beekeeping Building Mercury, letting anyone run multi agent teams with no code."}}},
  "SR006:Oasiz": {"officialUrl":"https://speedrun.a16z.com/companies/oasiz","officialOverview":"Oasiz is an interactive social distribution platform for software. As creation gets easier, software is evolving into a form of content, yet incumbent distribution channels aren't keeping up. Oasiz does for this next generation of AI-native creators what TikTok did for video creators. Starting with games, the most engaging and naturally social form of software, they launched less than a month ago and users have already spent over 9,000 hours on the platform, surpassed 300K plays, and gone viral on TikTok with over 7 million organic views.","founderDetails":{"Abel Dagne":{"role":"Founder & CEO","bio":"Abel is a highly technical and creative builder. He has shipped to billions of users at Google, won top of class at Stanford, built apps with over half a million downloads and have reached #1 on the App Store social charts."},"Jonathan Dinh":{"role":"COO/co-founder","bio":"Jonathan is a researcher and builder with experience at Berkeley and Amazon. At Berkeley, he helped develop teaching assistant systems for the world’s largest computer science class.\nL49: At Amazon, he worked on search engine optimization. He is also an elite mobile gamer, ranking in the top 0.01% in Wild Rift, Call of Duty: Mobile, and eFootball."}}},
  "SR006:Omi Health": {"officialUrl":"https://speedrun.a16z.com/companies/omi-health","officialOverview":"Omi is building the future of pet health—extending pet lifespans through longevity testing and AI-powered, personalized care. The co-founders met at Harvard Business School and built Omi for their own dogs. Between them, they bring a decade of experience in human healthcare, consumer branding expertise as Chief of Staff at Ritual ($250M+ ARR), and proven product chops as a second-time consumer tech founder. Gen Z and Millennial pet parents control a $94B market and spend nearly 2x more per household on their pets than prior generations.","founderDetails":{"Jakob Spiess":{"role":"COO and Co-Founder","bio":"Pet parent to Charlie the Italian Waterdog. Second-time founder and former mIlitary officer."},"Sindu Chaparala":{"role":"CEO and Co-Founder","bio":"Pet parent to her dog Omi, bioengineer with 10 years of experience in human healthcare (CVS Health, Aetna, MIT Longevity Lab) and deep consumer branding expertise as Chief of Staff to the CEO at Ritual where she helped scale the consumer brand to $250M in ARR."}}},
  "SR006:Panorama": {"officialUrl":"https://speedrun.a16z.com/companies/panorama","officialOverview":"Panorama is an AI platform that mines workplace data - Slack, email, docs, etc. - to surface hidden team workflows and deliver personalized AI adoption recommendations through a TikTok-like feed reducing friction and driving adoption from the bottom up. The company's CEO Jingwei Hao, lead and scaled technology adoption at Cash App and Lyft, and Jaclyn Lunger the CTO, is an MIT ML scientist and first employee at Lila Sciences ($1.3B), whose AI work on green hydrogen and carbon capture was patented and featured by the New York Times.","founderDetails":{"Jingwei Hao":{"role":"Founder & CEO","bio":"prev. infra eng @ Cash App, Lyft, Twitter"}}},
  "SR006:PartyHat": {"officialUrl":"https://speedrun.a16z.com/companies/partyhat","founderDetails":{"Jarret Cuisinier":{"role":"CEO"}}},
  "SR006:PayPath": {"officialUrl":"https://speedrun.a16z.com/companies/paypath","officialOverview":"PayPath is building the AI operating system for the $350 trillion global debt market. While debt is one of the largest financial systems on Earth, it remains trapped in a world of spreadsheets, manual workflows, and legacy tech. PayPath replaces these outdated systems with agentic AI infrastructure, transforming debt management from a fragmented cost center into a high-margin, automated engine. With over a dozen enterprise customers onboarded and more than half a billion dollars in assets managed on the platform, PayPath is bringing unmatched scale and efficiency to the modern debt economy.","founderDetails":{"Dean Glas":{"role":"CEO","bio":"Serial tech entrepreneur with an exit and over 10+ years of experience building and scaling companies from the ground up."},"Matthew Angelini":{"role":"CTO","bio":"Technology leader with 15+ years of experience building scalable software products for startups and enterprise clients, combining hands-on engineering, architecture, team leadership, and a passion for clean, reliable user experiences."},"Matthew Lippl":{"role":"CPO","bio":"Seasoned product leader with 15 years of experience in growth, building teams and crafting consistent, reliable user experiences, contributing to over $520 million in series funding and m&a exceeding $2.9 billion.\nL55: Previously leading product & growth at CoinMarketCap through a $400M acquisition to Binance."}}},
  "SR006:Piper-ai": {"officialUrl":"https://speedrun.a16z.com/companies/piper-ai","officialOverview":"Too much preconstruction time is spent assembling information, not improving the work. Days are lost finding, extracting, and reconciling information across drawings, specs, addenda, quotes, schedules, and spreadsheets, and senior team members cannot personally review every scope, bid, estimate, schedule, and project decision. Piper turns that fragmented process into a repeatable preconstruction system.","founderDetails":{"Erez Tepper":{"role":"Co-Founder & CTO","bio":"Started university at 14, founded and led a nationwide education organization at 16 with 400+ volunteers, and later built and deployed AI systems in production, before the generative AI boom, across defense, government, physics, and enterprise.\nL60: That path shaped how I think: in systems, under constraints, and in real-world complexity. I’m drawn to messy,"},"Ido Gedanken":{"role":"CEO | Harvey for construction","bio":"Started university at 14, led a robotics team that finished 2nd in the world, served in an elite military rescue unit, and later worked at Microsoft on products used by hundreds of millions of users. That path shaped how I think: from first principles, across complex systems, and under pressure. I’m drawn to problems that are hard, messy, and consequential.\n"},"Roi Menzin":{"role":"CRO","bio":"From commanding in a military special operations unit to bootstrapping a cybersecurity startup to nearly $1M ARR, where I led sales, customer success, and operations, I learned how to build in high-pressure environments where trust is earned and execution matters."}}},
  "SR006:Pluvo": {"officialUrl":"https://speedrun.a16z.com/companies/pluvo","officialOverview":"Pluvo is the agentic operating system for financial work. We help finance teams delegate analysis, reporting, reconciliations, forecasting, and entire workflows to AI while reducing risk and staying in control of the outcomes. Pluvo brings together governed business context, agents, and the formulas, code, and systems needed to execute work reliably. Every result can be traced back to its sources, calculations, and actions, so the people accountable can understand, verify, and stand behind it.","founderDetails":{"Alexandre Labreche":{"role":"CEO","bio":"Expert in FP&A, Data, ML, AI & Agent, trying to help organizations succeed through innovation."},"Andrew Ingram":{"role":"Co-Founder & CTO","bio":"CTO  |  Building the agentic operating system for finance | Builder at heart | Released two games with 200k+ downloads"},"Seb Fallenbuchl":{"role":"Co-founder & Chief Growth Officer","bio":"The agentic operating system for financial work | Built audience of 40k+ finance leaders & operators, 4M+ organic impressions | Biomedical-mechanical Engineer & Financial Researcher"},"Vanessa Galarneau":{"role":"Co-Founder, COO & CFO","bio":"10+ Years in Machine Learning & AI applications for finance and accounting.\nL56: 10x operator, passionate about the intersection of finance and technology. Big winning mentality. Thought Leader on AI for Finance on LinkedIn."}}},
  "SR006:Prior Foundry": {"officialUrl":"https://speedrun.a16z.com/companies/prior-foundry","officialOverview":"Prior Foundry is building a decision intelligence platform for governments and policy teams.","founderDetails":{"Jonne Kamphorst":{"role":"Chief Scientific Officer","bio":"Former Stanford postdoc leading research at the CS lab that pioneered human behavioral simulation - the next frontier in shaping society. Behavioral science @ LSE, Oxford and EUI, PhD, Fulbright Scholar"},"Keshav Sivakumar":{"role":"CTO","bio":"Builder at heart, second-time founder, passionate about the intersection of society and technology.\nL44: CS @ Cambridge, ex-palantir."},"Shirin Abrishami Kashani":{"role":"CEO","bio":"Oxford MS and Stanford PhD as Knight-Hennessy Scholar, former OECD policy analyst advising governments on major policy decisions."}}},
  "SR006:Quanto": {"officialUrl":"https://speedrun.a16z.com/companies/quanto","officialOverview":"Quanto is the AI workforce for accounting firms, automating client prospecting, onboarding, and bookkeeping cleanup so firms can scale revenue and margins without adding headcount. Built with AI from the ground up by CPAs for accountants, with $800K contracted ARR and a $5M+ pipeline.","founderDetails":{"Anderson Petergeorge":{"role":"Co-Founder - CEO","bio":"👋 Hey! Quanto is the AI workforce for accounting firms to scale revenue and margins. Quanto started as a bookkeeping and accounting practice that scaled to 40 customers in just 6 months with only one accountant (me) by leveraging off-the-shelf AI tooling. This gave us a front-row seat to the pain points of bookkeeping and the challenges of running a firm.\nL"},"Kajanth Nithiyananthan":{"role":"Co-Founder - CTO","bio":"Quanto is the AI workforce for accounting firms to scale revenue and margins.\nL50: With an incredible team, we're helping accounting firms attract more clients, onboard them quickly, and serve them with ease. Before Quanto, I built a 7-figure product studio that specialized in AI tech, working with accounting startups and firms. Before that, I was on the Gro"}}},
  "SR006:Quinn": {"officialUrl":"https://speedrun.a16z.com/companies/quinn","officialOverview":"Traction • $200K → $1.1M+ ARR in ~5 months • 65+ customers • Growing ACV + multiple 6-figure deals Why Now • Frontline workforce (2.7B people) lacks scalable training infrastructure. • Training is a $400B market, primarily to pay humans to train other humans. • We're turning this massive services industry into software margins. Team • Ben Anderson (Amino: 20M+ users, $70M raised, acquired) • Arlen Marmel (early Hulu + Crunchyroll, $1B+ exit) Hit LIKE to get in touch!","founderDetails":{"Arlen Marmel":{"role":"Cofounder","bio":"I’m the co-founder of Quinn, an AI training platform built for frontline teams. Before Quinn, I helped scale Hulu and Crunchyroll to millions of users, including through Crunchyroll’s $1B+ acquisition."},"Ben Anderson":{"role":"Co-Founder & CEO","bio":"Currently building Quinn with an incredible group of people. Former CEO and Co-founder of Amino Apps and Luna Park."}}},
  "SR006:Quo Labs": {"officialUrl":"https://speedrun.a16z.com/companies/quo-labs","officialOverview":"We're building the eldercare infrastructure layer for 1.4 billion seniors.","founderDetails":{"Audrey Lo":{"role":"Co-Founder & CEO"},"Jenny Wen":{"role":"Co-founder","bio":"18 years old. I published my first Minecraft mod when I was 8 and my first game when I was 10. I've been building ever since. At 16, I started and grew my own digital media company to 1.2 million+ minutes of watch time and 10k+ worth in revenue. I also raised thousands of dollars for charity through grassroots fundraising. At 17, I published AI research cite"}}},
  "SR006:SafeWorld": {"officialUrl":"https://speedrun.a16z.com/companies/safeworld","officialOverview":"SafeWorld is an evaluation platform for robots operating around people. We generate rare but critical scenarios to uncover failure modes, quantify risk, and help robotics teams deploy with confidence. Our team combines a Carnegie Mellon professor and NSF CAREER Award winner in robot safety with repeat founders who have built and scaled AI companies. If you believe safety is important to the deployment of Physical AI we'd love to chat https://safeai-lab.github.io/","founderDetails":{"Ding Zhao":{"role":"cofounder","bio":"Professor at CMU"},"Kyle Wong":{"role":"Cofounder"},"Simo Rachidi":{"role":"Cofounder"}}},
  "SR006:Sellara": {"officialUrl":"https://speedrun.a16z.com/companies/sellara","officialOverview":"Sellara is building custom AI agents for financial institutions. Our AI outperforms leading LLMs by 60%+ and runs 30x faster. We automate repetitive, manual workflows across front, middle, and back offices. We're working with banks, broker-dealers, hedge funds, asset managers, and wealth managers to make complex financial workflows feel automatic. Sellara is becoming the AI lab for financial institutions to turn training data into trading data.","founderDetails":{"Ahmad Roumie":{"role":"CTO"},"Charles-André Jolly":{"role":"CEO","bio":"Ex-Citi, covered 180 institutional clients across Macro Credit Derivatives, Investment Grade Credit, and Short Term Credit Sales."},"Spencer Secord":{"role":"COO","bio":"Ex-Citi, spent 6 years across Cross Asset, Fixed Income, and Convertible Sales desks. Built workflow automations and collaborated with IT, middle office, and engineering teams to integrate these functionalities and automations into core risk systems."}}},
  "SR006:Sentra": {"officialUrl":"https://speedrun.a16z.com/companies/sentra","officialOverview":"Enterprise General Intelligence starts with memory. Sentra captures the interactions where work actually happens, meetings, messages, emails & agent traces, and turns them into a shared organizational memory. That memory becomes the foundation for intelligent models that can understand and coordinate work across the entire company. As multiple time founders with backgrounds from MIT, IBM, and Caltech, we assembled a team of engineers and researchers from Google, Amazon, Meta, Microsoft, Apple, and Databricks to tackle this problem with us.","founderDetails":{"Andrey Starenky":{"role":"Co-Founder and CTO","bio":"Previous founder, did AI engineering at IBM, Vapi, and ML research at MIT building offline deployments of ML systems for military use"},"Ashwin Gopinath":{"role":"Co-Founder and CEO","bio":"I was previously a professor at MIT and earlier at Caltech working on applied physics and AI, and also a researcher at Google. I created one of the early agentic LLM frameworks, Reflexion, and previously founded and exited two venture-backed companies.\nL43: Currently exploring how organizational memory can enable Enterprise General Intelligence."}}},
  "SR006:Simula": {"officialUrl":"https://speedrun.a16z.com/companies/simula","officialOverview":"Simula helps AI apps monetize through native, interactive ad experiences. Launched three months ago, we’re integrating into AI apps covering 5M+ DAUs and 100M+ downloads, representing ~$10M+ in net revenue at full rollout. Traditional ads break AI products. We replace them with formats that feel like part of the experience – AI brand ambassadors, games users play with AI companions, and more. The team has built and scaled dozens of apps and worked across AdTech at Google and Bain Capital.","founderDetails":{"Yizhen Zhen":{"role":"CEO","bio":"CEO & Founder @ Simula Built dozens of games & apps since I was 10 Formerly SWE @ Google; PE @ Bain Cap HBS + Dartmouth"}}},
  "SR006:Sirius": {"officialUrl":"https://speedrun.a16z.com/companies/sirius","officialOverview":"We are solving one of the biggest problems for subscription companies: churn. Most brands see a huge drop in subscribers in the first few months. We developed a novel approach to solve this by building an AI model for retention. We are currently live and managing retention for unicorn-status consumer companies, processing millions of interactions daily.","founderDetails":{"Azamat K":{"role":"CEO","bio":"Azamat previously founded a consumer AI product that scaled to 5M MAU in 4 months and was the first ever acquisition in Telegram"},"Benazir Toleubekova":{"role":"Co-founder","bio":"Benazir is an engineering prodigy who won a full scholarship to Beijing University of Technology at age 15 and joined Taobao at 17. She later architected Alibaba's core recommendation engine, which currently serves 500M daily users"}}},
  "SR006:Smart Bricks": {"officialUrl":"https://speedrun.a16z.com/companies/smart-bricks","officialOverview":"Smart Bricks is an applied AI lab building agentic reasoning systems for real estate investing. We develop and deploy autonomous agents, multi-model reasoning, and continuous learning loops to transform how real-world assets are discovered, evaluated, and managed. We’re already at a ~$12M revenue run-rate, backed by a16z Speedrun alongside leading angels from OpenAI, Google DeepMind, and Anthropic. Our team brings experience from Blackstone, Goldman Sachs, McKinsey, and OpenAI — combining institutional investing expertise with frontier AI research.","founderDetails":{"Mohamed Mohamed":{"role":"Founder & CEO","bio":"Founder & CEO, Smart Bricks - Applied AI lab building agentic AI infrastructure for real-estate investing. Smart Bricks designs and deploys autonomous reasoning systems that allow capital to discover, evaluate, and transact real-estate assets end-to-end, compressing a traditional six-month acquisition cycle into minutes through data-driven, agentic workflows"}}},
  "SR006:snag": {"officialUrl":"https://speedrun.a16z.com/companies/snag","officialOverview":"snag is the AI-native sublet marketplace for GenZ. We generated $6.5m in requests in the last 30 days, growing 40% m/o/m, with 3k listings in NYC! Today millions exchange sublets on FB groups, IG, Craigslist. We're turning this raw, messy sublet culture into an organized, high-trust marketplace. Our proprietary AI model converts social posts into high quality listings instantly, and matches renters with the right sublet within seconds. snag fills the gap between Airbnb and Zillow, making housing liquid for a new generation of renters.","founderDetails":{"Niko Georgantas":{"role":"Co-founder & CPO","bio":"I'm Niko, Co-founder and CPO of Snag. The rental market was built for a world that no longer exists, we're building the one that replaces it."},"Selin Sonmez":{"role":"co-founder & ceo","bio":"I’m Selin, a 3x consumer founder obsessed with city living and the role of technology, community, and real-world connection. We’re helping GenZ find flexible, affordable housing."}}},
  "SR006:Snapp AI": {"officialUrl":"https://speedrun.a16z.com/companies/snapp-ai","officialOverview":"Snapp is a personalized sports feed powered by AI. It brings you the right content, news, highlights, and insights in real time, and lets you instantly go deeper with analytics when you want. No more tab-hopping. No more guesswork.","founderDetails":{"Alex Marshall":{"role":"Chief AI Officer/Cofounder","bio":"2x founder, former AI @ Genentech & the Pentagon"},"Andrew Tamura":{"role":"CTO"},"Min Park":{"role":"CFO / COO"},"Shawn Tsao":{"role":"CEO","bio":"Shawn is currently the CEO and co-founder of Snapp AI, a 24/7 AI Agent for Sports Fans. Shawn has been in the startup world since 2011 when he started a daily deals company with his college friends called Munch On Me (YC class of S11) and dove into the tech startup industry. He later co-founded a food delivery company, Caviar, in early 2012. Caviar was acqui"}}},
  "SR006:Sparta": {"officialUrl":"https://speedrun.a16z.com/companies/sparta","officialOverview":"Sparta lets teams test their AI agents locally in exact replicas of the tools they touch, like Stripe, Zendesk, and Salesforce, so they see exactly what an agent does before it ever hits production. You can describe a scenario in plain English, and Sparta builds the test, even across multiple tools at once, then inject the worst case yourself, like an API key expiring 30 days out, to see if the agent holds up.","founderDetails":{"Arya Kanna":{"role":"CEO & Co-Founder","bio":"Hello! I'm Arya Kanna. I left Berkeley to build Worlds, so AI agents are tested before they're trusted."},"Lalith Posam":{"role":"CTO"},"Saad Asad":{"role":"Co-Founder"}}},
  "SR006:Straia": {"officialUrl":"https://speedrun.a16z.com/companies/straia","officialOverview":"Straia is the agentic AI platform replacing legacy software across higher education. We unify siloed institutional data and deploy AI agents to analyze and act on that data. Building the AI-native operating system for every college in America.","founderDetails":{"Alan Chan":{"role":"CTO","bio":"Cofounder and CTO at Straia. Engineered the backbone of the systems at Skillz that scaled to a $3.5B public offering. Built Greenpark Sports from the ground up until acquisition by JOA.\nL44: Serial builder, now focused on higher ed where institutions are drowning in data they can't use."},"Gautam Narasimhan":{"role":"COO","bio":"Co-founder and COO at Straia. Prior to Straia, built the early US GTM and deployment motion for agentic AI platform at Sana Labs (acquired by Workday in 2025 for >$1B). Laser-focused on helping our partner schools derive immediate ROI from custom AI deployments.\nL45: Previously consumer internet investor at Advent International / founding operator at Kismet "},"Nikki Dansey":{"role":"CPO","bio":"Co-Founder and CPO of Straia. Previously, co-founded SageSpot (Khosla-backed) as CTO, first hire at Arcus (acquired by Addepar), and built the first AI-native programmatic platform in advertising at The Trade Desk. Studied computer science at UC Berkeley and have spent my career at the intersection of engineering and product."},"Ryan Lau":{"role":"CEO","bio":"Co-founder and CEO of Straia. Scaled first edtech startup to $5M in 9 months. Called over 3,000 colleges and universities before starting Straia. Spent nearly my entire career investing and operating at intersection of education and technology. Wharton grad."}}},
  "SR006:SUN": {"officialUrl":"https://speedrun.a16z.com/companies/sun","officialOverview":"Audio has always been static, limited, and the same for everyone. SUN makes it personal, dynamic, and always up to date. Create podcasts, audiobooks, or structured audio experiences on any topic. Customize everything, from length and voice to language. Ask questions at any moment and get answers in real time. Not sure what to create? SUN knows what to play. Connect the apps you already use, and it continuously adapts to your interests, delivering audio tailored to you.","founderDetails":{"Artin Bogdanov":{"role":"CEO","bio":"Founder & CEO of SUN, a new way to consume audio content."},"Matt Günhan Ertosun, PhD":{"role":"Co-founder","bio":"2x Founder | Co-founder @ SUN (a16z Speedrun SR006) | Stanford Eng.\nL53: PhD | Former Venture Builder @ $2.5B VC | AI & Generative AI | Scientist | Inventor | Author | Meditation Enthusiast Entrepreneur, AI technologist, and Stanford-trained scientist (more than 400 scientific citations and multiple patents) working at the intersection of artificial intellig"}}},
  "SR006:Syncere": {"officialUrl":"https://speedrun.a16z.com/companies/syncere","officialOverview":"Launch Tweet: https://x.com/aaronistan/status/2041909335220220252?s=20 We’re building robots that automate everyday chores at home. Our first product, Lume, looks like a normal lamp. When needed, it transforms into a pair of robotic arms that can complete tasks like folding laundry. When it’s done, it returns to being a lamp, so your home feels unchanged, except the chores are taken care of. Our team comes from top robotics programs like Stanford, the University of Toronto, and Berkeley, with experience building hardware at Tesla, Nuro, and AMD, and design experiences at Apple and Harvard.","founderDetails":{"Aaron Tan":{"role":"CEO","bio":"Stanford Postdoc + UofToronto PhD in Robotics. Hardware engineering at GM (self-driving) and photography/design at Apple."},"Angus Fung":{"role":"CTO","bio":"UofToronto PhD in Robotics. ML Researcher at Vector Institute and AMD."}}},
  "SR006:Taxnova": {"officialUrl":"https://speedrun.a16z.com/companies/taxnova","officialOverview":"Taxnova turns the engineering data you already have — Jira, GitHub, technical docs, Slack — into review-ready, evidence-backed R&D tax and CapEx documentation. We don't replace your tax advisor; we do the heavy lifting continuously throughout the year before they touch the claim. No engineer interviews, no annual reconstruction scramble — contemporaneous, source-linked evidence built to stand up to IRS/CRA/HMRC scrutiny, surfacing qualifying work that gets missed.","founderDetails":{"George Nichkov":{"role":"CEO & CFO","bio":"Founder of Taxnova — helping engineering teams focus on R&D, not R&D tax. Taxnova bridges the worlds of finance and engineering which is perfect reflection of my background: education in economics & finance (UCL, CFA) and career in B2B product, analytics, and consulting (Gett, Oliver Wyman)."},"Maria Malykh":{"role":"CTO","bio":"Hi there! I'm Maria, I'm passionate about saving engineers' time and turning messy unstructured data into insights.\nL45: Both combine perfectly in what we are doing at Taxnova. I'm an avid traveller — ask me about South America, Asia and Siberia. not easy to combine that with startups, but I'm trying!"}}},
  "SR006:ThirdBrain Labs": {"officialUrl":"https://speedrun.a16z.com/companies/thirdbrain-labs","officialOverview":"We help teams own and continuously improve their domain-specific AI, turning their knowledge into scalable intelligence. Our end-to-end post-training infrastructure captures expert decisions directly and applies them on top of base models, allowing teams to steer production models continuously without error-prone workflows, heavy datasets, and massive labor.","founderDetails":{"David Huang":{"role":"CTO"},"Margaret Zhang":{"role":"CEO"}}},
  "SR006:Variant": {"officialUrl":"https://speedrun.a16z.com/companies/variant-now","officialOverview":"Variant is building the infrastructure for the Adaptive Web: generative, adaptive experiences that change in real time for every user or agent. We provide a real-time decisioning and generation layer that continuously augments what each user sees in real time - across content, imagery, products and flows. $500K ARR, doubled in the last 30 days $2.5M in Pipeline Founders are ex Israel Defense Intelligence & Special Forces","founderDetails":{"Ben Segal":{"role":"Co-founder & COO","bio":"8+ years leading Product & Growth at consumer startups.\nL48: Previously led GTM at Workiz from $0 to $40M ARR, navigating the daily challenges of cross-functional execution. Now building AI to solve those same growth bottlenecks for modern brands."},"Elad Nissenberg":{"role":"Co-Founder & CEO","bio":"Co-founder & CEO of Variant, building the infrastructure for the Adaptive Web - where websites dynamically evolve around each user. Previously, led strategy and M&A at NICE (NASDAQ: NICE), a global leader in enterprise CX, and is a two-time founder with a background in Israeli Military Intelligence. Currently part of a16z Speedrun in SF."}}},
  "SR006:Vereda": {"officialUrl":"https://speedrun.a16z.com/companies/vereda","officialOverview":"Vereda addresses one of the largest structural inefficiencies in Brazilian agriculture (US$700b Market): distribution. It is building the most efficient way for suppliers to access fragmented farm demand in Brazil. Through a WhatsApp native procurement agent, Vereda captures and structures farmers’ purchasing intent, enabling direct distribution from manufacturers with structurally lower cost to serve for suppliers and improved pricing for farmers by eliminating inefficiencies in the distribution layer.","founderDetails":{"João Souza":{"role":"Co-founder, CEO","bio":"Raised in a farming family in Brazil; B.S. in Business Administration from the University of Southern California; lived and worked across three continents. Led over $1B in agribusiness transactions at BTG Pactual (BPAC11) and was part of the founding team of a Series B B2B marketplace in Brazil."},"Pedro Galindo":{"role":"Co-Founder & CPTO","bio":"Roots in Brazil’s largest agricultural hub; B.S.\nL41: in Business Administration and Artificial Intelligence Applications from the University of Southern California. Previously worked in tech investing at Patria Investments (NASDAQ:PAX), the most active private equity investor in agriculture in LatAm, and helped launch the fintech arm of one of the region’s "}}},
  "SR006:Verra": {"officialUrl":"https://speedrun.a16z.com/companies/verra","officialOverview":"Every consulting firm runs on knowledge that's unstructured, unsearchable, and lost when people leave. Generic AI tools don't fix this - they're stateless by design, starting from zero every conversation. Meridian is the system of record that fixes this. Every document organized automatically. Every prior engagement retrievable in seconds. Deliverables generated in the firm's exact templates. After two months, a firm's Meridian instance is irreplaceable. But the software isn't the bet. The bet is the data - behavioral signal on how consulting work actually gets done. You can't download it.","founderDetails":{"Chris Farrington":{"role":"CTO","bio":"ML eng at Sandia, SWE at Deloitte - RL for drones in multi agent swarms, then tech consulting. Now, building tech, for consulting"},"Kashyap Nathan":{"role":"CEO","bio":"FDE @ Palantir, then ChatGPT for Gov @ OpenAI. Dropped out of Georgia Tech"}}},
  "SR006:ZeroDrift": {"officialUrl":"https://speedrun.a16z.com/companies/zerodrift","officialOverview":"ZeroDrift is the Enforcement Runtime for AI. AI now speaks and acts on behalf of organizations, at machine speed, across every tool and channel. Every one of those companies runs on rules: regulations, internal policies, security controls. Nothing enforces those rules on what AI does. That infrastructure has not existed. ZeroDrift is that infrastructure. Every regulation, pre-loaded. Your policies, trained on top. Enforced on everything AI says, before it ships. Each message is passed, rewritten, blocked, or escalated in real time, with examiner-ready evidence for every verdict.","founderDetails":{"Kumesh Aroomoogan":{"role":"Founder and CEO","bio":"Repeat AI founder. Built one of the first NLP platforms for finance, raised $60M+, scaled to 100+ employees, and led the company to acquisition in 2025. Forbes 30 Under 30 (AI). Been building AI for financial services since 2014. Spent 12 years shipping NLP products to global banks and asset managers, helping enterprises extract and analyze unstructured data"}}},
};
for (const [key, details] of Object.entries(SPEEDRUN_OFFICIAL_DETAILS)) {
  if (details.officialOverview) details.officialOverview = details.officialOverview
    .replace(/https?:\/\/\S+/g, "")
    .replace(/\b[^\s@]+@[^\s@]+\.[^\s@]+\b/g, "")
    .replace(/\b(?:VIDEO|Launch Tweet):\s*/gi, "")
    .replace(/\b(?:Reach us|reach out) at\s*\.?\s*$/i, "")
    .trim();
  window.SPEEDRUN_CONTEXT[key] = { ...window.SPEEDRUN_CONTEXT[key], ...details };
}
